update books set isbn = '1952825180', cover_url = 'https://assets.hardcover.app/external_data/59414692/4d2848f3fdce34c7a8cd413c8734d39f2822c71b.jpeg', synopsis = 'It’s one kid versus an entire band of space pirates in this cosmic middle grade caper from New York Times bestselling author Dan Wells.

Zero is just one of 20,000 people aboard a spaceship bound for a new planet set to be colonized. The journey is over a century long but luckily, everyone is in stasis, so they’ll be safe and sound asleep during the trip. Everyone that is, except for Zero, whose pod has malfunctioned, waking him up a hundred years early. His initial excitement in roaming the ship alone quickly turns to a heart-stopping interstellar adventure when a family of space pirates show up, trying to hijack the ship and take the colonizers hostage. With everyone he knows fast asleep, it’s up to Zero to think fast and find a way to stop them–all on his own.

The full cast for this production includes Emily Woo Zeller, Margaret Ying Drake, Betsy Hogg, Josh Hurley, Jonathan Davis, Jennifer Van Dyck, Chelsea Spack, Charlie Thurston, David Shih, Eunice Wong, Eddy Lee, Allyson Johnson, and Polly Lee.
Now available in Dolby Atmos on Audible.

©2018 Dan Wells (P)2018 Audible Originals, LLC.', page_count = null, audiobook_duration_minutes = null, publication_year = 2018, hardcover_id = 463065, series_id = (select id from series where hardcover_id = 14094), position_in_series = '1', updated_at = now() where title = 'Zero G' and hardcover_id is null;
update books set isbn = null, cover_url = 'https://assets.hardcover.app/editions/31209030/5906010955911833.jpg', synopsis = 'Tessa Thompson stars as an idealistic young journalist trying to make a name for herself by following a group of paranormal explorers, obsessed with a seemingly harmless pastime known as the Left/Right Game. The journey takes her into a supernatural world that she and the other members of the expedition can neither handle nor survive.', page_count = 214, audiobook_duration_minutes = null, publication_year = null, hardcover_id = 1184322, series_id = null, position_in_series = null, updated_at = now() where title = 'The Left Right Game' and hardcover_id is null;
update books set isbn = '9513157792', cover_url = 'https://assets.hardcover.app/external_data/3855340/5c979a66a949f64f4c2498e9b5e416309dd6d5ba.jpeg', synopsis = 'After his childhood sweetheart is brutally killed and suspicion falls on him, Ig Parrish goes on a drinking binge and wakes up with horns on his head, hate in his heart, and an incredible new power which he uses in the name of vengeance.', page_count = null, audiobook_duration_minutes = null, publication_year = 2009, hardcover_id = 178955, series_id = null, position_in_series = null, updated_at = now() where title = 'Horns' and hardcover_id is null;
