insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Watchmen', 'Alan Moore', '8328152460', 'https://assets.hardcover.app/edition/30806897/f45cbdf0f15a21a6ff5368cafeef8ff9c039de2a.jpeg', 'Considered the greatest graphic novel in the history of the medium, the Hugo Award-winning story chronicles the fall from grace of a group of superheroes plagued by all-too-human failings. Along the way, the concept of the superhero is dissected as an unknown assassin stalks the erstwhile heroes.', 448, null, 1987, 308, (select id from series where hardcover_id = 5453), '1') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Ender in Exile', 'Orson Scott Card', '8378395030', 'https://assets.hardcover.app/edition/6178760/dab04baad5d63ec0723dc6a1108e3b3eb53ec7f8.jpeg', 'At the close of "Ender''s Game," Andrew Wiggin--called Ender--is told that he can no longer live on Earth. The 12-year-old chooses to leave his home world and begins the long relativistic journey out to the colonies.', 380, null, 2007, 312, (select id from series where hardcover_id = 1059), '5') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Burning Chrome', 'William Gibson', '9605211483', 'https://assets.hardcover.app/editions/1912660/3115113073320457.jpg', 'Burning Chrome collects Gibson''s early short fiction from the late 70''s and early 80''s.

Contents:
Preface / by Bruce Sterling --
Johnny Mnemonic --
The Gernsback continuum --
Fragments of a hologram rose --
The belonging kind / by John Shirley and William Gibson --
Hinterlands --
Red star, winter orbit / by Bruce Sterling and William Gibson --
New Rose Hotel --
The winter market --
Dogfight / by Michael Swanwick and William Gibson --
Burning chrome.', 191, null, 1981, 2440, (select id from series where hardcover_id = 19911), '0') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Excession', 'Iain M. Banks', '3453196791', 'https://assets.hardcover.app/external_data/3253850/183497ed8052dba12c98f90d47614e5563c95052.jpeg', 'Two and a half millennia ago, the artifact appeared in a remote corner of space, beside a trillion-year-old dying sun from a different universe. It was a perfect black-body sphere, and it did nothing. Then it disappeared.

Now it is back.', 500, null, 1996, 2931, (select id from series where hardcover_id = 1102), '5') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Buried Giant', 'Kazuo Ishiguro', '9513186520', 'https://assets.hardcover.app/external_data/59800787/456c0b0456f3afa6a2c9d12b334ad9304b5b2165.jpeg', 'In post-Arthurian Britain, the wars that once raged between the Saxons and the Britons have finally ceased. Axl and Beatrice, an elderly British couple, set off to visit their son, whom they haven''t seen in years. And, because a strange mist has caused mass amnesia throughout the land, they can scarcely remember anything about him. As they are joined on their journey by a Saxon warrior, his orphan charge, and an illustrious knight, Axl and Beatrice slowly begin to remember the dark and troubled past they all share.

By turns savage, suspenseful, and intensely moving, The Buried Giant is a luminous meditation on the act of forgetting and the power of memory.', 317, null, 2015, 3257, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Dauntless', 'Jack Campbell', '2841724069', 'https://assets.hardcover.app/edition/14963202/1b0da570-fd48-4cda-9e54-5e1cb5352b31.jpg', 'The Alliance has been fighting the Syndic for a century-and losing badly. Now its fleet is crippled and stranded in enemy territory. Their only hope is Captain John "Black Jack" Geary-a man who''s emerged from a century-long hibernation to find he has been heroically idealized beyond belief. Now, he must live up to his own legend.', 302, null, 2006, 5922, (select id from series where hardcover_id = 1718), '1') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Shōgun', 'James Clavell', '2253032549', 'https://assets.hardcover.app/external_data/925345/fcf14e4ecfc553f27f96cd74b6e27d9c52e25500.jpeg', 'After Englishman John Blackthorne is lost at sea, he awakens in a place few Europeans know of and even fewer have seen--Nippon. Thrust into the closed society that is seventeenth-century Japan, a land where the line between life and death is razor-thin, Blackthorne must negotiate not only a foreign people, with unknown customs and language, but also his own definitions of morality, truth, and freedom. As internal political strife and a clash of cultures lead to seemingly inevitable conflict, Blackthorne''s loyalty and strength of character are tested by both passion and loss, and he is torn between two worlds that will each be forever changed.

Powerful and engrossing, capturing both the rich pageantry and stark realities of life in feudal Japan, Shōgun is a critically acclaimed powerhouse of a book. Heart-stopping, edge-of-your-seat action melds seamlessly with intricate historical detail and raw human emotion. Endlessly compelling, this sweeping saga captivated the world to become not only one of the best-selling novels of all time but also one of the highest-rated television miniseries, as well as inspiring a nationwide surge of interest in the culture of Japan. Shakespearean in both scope and depth, Shōgun is, as the New York Times put it, "...not only something you read--you live it." Provocative, absorbing, and endlessly fascinating, there is only one: Shōgun.', 1125, null, 1975, 6705, (select id from series where hardcover_id = 5500), '1') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Green Mars', 'Kim Stanley Robinson', '8377314932', 'https://assets.hardcover.app/edition/15780362/f3c8afe3fc6039c58f8de55d78277e12663ce904.jpeg', '"In the Nebula Award winning Red Mars, Kim Stanley Robinson began his critically acclaimed epic saga of the colonization of Mars, Now the Hugo Award winning Green Mars continues the thrilling and timeless tale of humanity''s struggle to survive at its farthest frontier.

Nearly a generation has passed since the first pioneers landed, but the transformation of Mars to an Earthlike planet has just begun The plan is opposed by those determined to preserve the planet''s hostile, barren beauty. Led by rebels like Peter Clayborne, these young people are the first generation of children born on Mars. They will be joined by original settlers Maya Toitovna, Simon Frasier, and Sax Russell. Against this cosmic backdrop, passions, rivalries, and friendships explode in a story as spectacular as the planet itself." --Publisher''s description.', 624, null, 1992, 8533, (select id from series where hardcover_id = 1114), '2') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Vampire Academy', 'Richelle Mead', '1595143602', 'https://assets.hardcover.app/external_data/38061582/dcb56794c52e9e7fb7247baf8e30afa68c83795c.jpeg', '"St. Vladimir’s Academy isn’t just any boarding school—it’s a hidden place where vampires are educated in the ways of magic and half-human teens train to protect them. Rose Hathaway is a Dhampir, a bodyguard for her best friend Lissa, a Moroi Vampire Princess. They’ve been on the run, but now they’re being dragged back to St. Vladimir’s—the very place where they’re most in danger. . . . 

Rose and Lissa become enmeshed in forbidden romance, the Academy’s ruthless social scene, and unspeakable nighttime rituals. But they must be careful lest the Strigoi—the world’s fiercest and most dangerous vampires—make Lissa one of them forever."-- Provided by Amazon', 354, null, 2007, 11463, (select id from series where hardcover_id = 5623), '1') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Glass Castle', 'Jeannette Walls', '1419341049', 'https://assets.hardcover.app/book_mappings/7332926/f737c395fb5693a0ee8540f086885768f1f01df9.jpeg', 'The Glass Castle is a remarkable memoir of resilience and redemption, and a revelatory look into a family at once deeply dysfunctional and uniquely vibrant. When sober, Jeannette''s brilliant and charismatic father captured his children''s imagination, teaching them physics, geology, and how to embrace life fearlessly. But when he drank, he was dishonest and destructive. Her mother was a free spirit who abhorred the idea of domesticity and didn''t want the responsibility of raising a family.
The Walls children learned to take care of themselves. They fed, clothed, and protected one another, and eventually found their way to New York. Their parents followed them, choosing to be homeless even as their children prospered.
The Glass Castle is truly astonishing -- a memoir permeated by the intense love of a peculiar but loyal family.', 304, null, 2005, 12666, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Hunchback of Notre Dame', 'Victor Hugo, Tim Wynne-Jones', '0831714654', 'https://assets.hardcover.app/external_data/41589217/c9b9d4321855c4ef5647d67a31c7c79da53e6510.jpeg', 'A retelling of the tale, set in medieval Paris, of Quasimodo, the hunchbacked bellringer of Notre Dame Cathedral, and his struggles to save the beautiful gypsy dancer Esmaralda from being unjustly executed.', 40, null, 1831, 15962, (select id from series where hardcover_id = 5682), null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Stone of Tears', 'Terry Goodkind', '0613224477', 'https://assets.hardcover.app/edition/20224040/dbc7e00a2057ca97b1a02da04378babaf4585d4c.jpeg', 'In Wizard’s First Rule, forest guide Richard Cypher becomes a Seeker of Truth in order to defeat the tyrannical Wizard Darken Rahl—only to discover that he is in fact Darken’s son. Now, with Darken vanquished, Richard and the beautiful Kahlan Amnell head back to the Mud People to be married. But their adventures are far from over.

As the wedding day approaches, Richard is visited by three Sisters of Light who insist on bringing him to the Palace of the Prophets to be trained as a Wizard. Meanwhile, the veil to the underworld has been torn, and the Stone of Tears has passed through. According to prophecy, the only person who has a chance at closing the veil is the one bonded to the blade, the one born true.', 1056, null, 1995, 18015, (select id from series where hardcover_id = 1078), '2') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Darkness That Comes Before', 'R. Scott Bakker', '1841494089', 'https://assets.hardcover.app/external_data/60875763/527b88098acef464f1008a6198f84ffd4bd815dc.jpeg', 'Strikingly original in its conception, ambitious in scope, with characters engrossingly and vividly drawn, the first book in R. Scott Bakker''s Prince of Nothing series creates a remarkable world from whole cloth—it''s language and classes of people, its cities, religions, mysteries, taboos, and rituals—the kind of all-embracing universe that has thrilled readers of Stephen R Donaldson and George R.R. Martin.It''s a world scarred by an acopalyptic past, evoking a time both two thousand years past and two thousand years into the future, as untold thousands gather for a crusade. Travelling among them, two men and two women are ensnared by a mysterious traveler, Anasurimbor Kellhus—part warrior, part philosopher, part sorcerous, charismatic presence—from lands long thought dead. The Darkness that Comes Before is a history of this great holy war, and like all histories, the survivors write its conclusion.With this stunning debut, R. Scott Bakker is poised to become one of the next great fantasy writers of his generation. The Darkness that Comes Before proves again that epic fantasy can be intelligent, majestic, and terrifying.', 657, null, 2003, 20065, (select id from series where hardcover_id = 5629), '1') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Foucault''s Pendulum', 'Umberto Eco', '9872060940', 'https://assets.hardcover.app/edition/30628450/153e253a-101a-44cf-bb36-2c7726994e65.jpeg', 'Extraordinary narrative by Italian semiotician and professor Umberto Eco, who guides us through the darkest corners of history.', 641, null, 1988, 20318, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Atrocity Archives', 'Charles Stross', '0748107959', 'https://assets.hardcover.app/editions/30403858/9c825c0e-740c-4e29-8b9e-354d77c26461.jpg', 'Bob Howard is a computer-hacker desk jockey, who has more than enough trouble keeping up with the endless paperwork he has to do on a daily basis. He should never be called on to do anything remotely heroic. But for some reason, he is.', 368, null, 2004, 21233, (select id from series where hardcover_id = 1859), '1') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Fool''s Fate', 'Robin Hobb', '8401019303', 'https://assets.hardcover.app/external_data/61081446/987756ec2b09c709628262c097473b426e4f0214.jpeg', '''Fantasy as it ought to be written'' George R.R. Martin The thrilling conclusion to Robin Hobb''s Tawny Man trilogy.', 816, null, 2003, 23273, (select id from series where hardcover_id = 6035), '3') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Horus Rising', 'Dan Abnett', '1448780993', 'https://assets.hardcover.app/external_data/4059431/2b29d55181341f14064d6020e26bd225cbba5a3a.jpeg', 'A Horus Heresy Novel - Book 1

After thousands of years of expansion and conquest, the human Imperium is at its height. His dream for humanity accomplished, the Emperor hands over the reins of power to his Warmaster, Horus, and heads back to Terra.

It is the 31st millennium. Under the benevolent leadership of the Immortal Emperor, the Imperium of Man has stretched out across the galaxy. It is a golden age of discovery and conquest. But now, on the eve of victory, the Emperor leaves the front lines, entrusting the great crusade to his favourite son, Horus. Promoted to Warmaster, can the idealistic Horus carry out the Emperor''s grand plan, or will this promotion sow the seeds of heresy amongst his brothers? Horus Rising is the first chapter in the epic tale of the Horus Heresy, a galactic civil war that threatened to bring about the extinction of humanity.', 412, null, 2016, 31879, (select id from series where hardcover_id = 215570), '1') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Soulless', 'Gail Carriger', '0316438952', 'https://assets.hardcover.app/edition/30400353/14c421285e68d8f3674ca240af355a9f437d816a.jpeg', 'Alexia Tarabotti is laboring under a great many social tribulations. First, she has no soul. Second, she''s a spinster whose father is both Italian and dead. Third, she was rudely attacked by a vampire, breaking all standards of social etiquette. Where to go from there? From bad to worse apparently, for Alexia accidentally kills the vampire -- and then the appalling Lord Maccon (loud, messy, gorgeous, and werewolf) is sent by Queen Victoria to investigate. With unexpected vampires appearing and expected vampires disappearing, everyone seems to believe Alexia responsible. Can she figure out what is actually happening to London''s high society? Will her soulless ability to negate supernatural powers prove useful or just plain embarrassing? Finally, who is the real enemy, and do they have treacle tart?SOULLESS is a comedy of manners set in Victorian London: full of werewolves, vampires, dirigibles, and tea-drinking.', 357, null, 2009, 33557, (select id from series where hardcover_id = 5508), '1') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Reptile Room', 'Lemony Snicket, Brett Helquist', '9864170694', 'https://assets.hardcover.app/edition/29733844/107518b9-b92b-4d46-8d1d-f4ddef1cc5af.jpg', 'Book 2 of A Series of Unfortunate Events. The three unluckiest children in the world return for another misfortunate adventure. The Baudelaire children survived their first encounter with the dastardly and scheming Olaf, but the Count doesn''t give up easily. Nor does the Baudelaire luck ever seem to improve.', 192, null, 1999, 33577, (select id from series where hardcover_id = 1570), '2') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Gathering Blue', 'Lois Lowry', '957570990X', 'https://assets.hardcover.app/external_data/31980056/2eb0f2212dbaf529a17cd01ef19085c9763e8c7a.jpeg', 'In her strongest work to date, Lois Lowry once again creates a mysterious but plausible future world. It is a society ruled by savagery and deceit that shuns and discards the weak. Left orphaned and physically flawed, young Kira faces a frightening, uncertain future. Blessed with an almost magical talent that keeps her alive, she struggles with ever broadening responsibilities in her quest for truth, discovering things that will change her life forever.

As she did in The Giver, Lowry challenges readers to imagine what our world could become, and what will be considered valuable. Every reader will be taken by Kira''s plight and will long ponder her haunting world and the hope for the future.', 240, null, 2000, 34056, (select id from series where hardcover_id = 5782), '2') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Paper Magician', 'Charlie N. Holmberg', '1491519223', 'https://assets.hardcover.app/edition/30402252/ae2384f97855e0eb3c9e546eb2db79a01dc46c5d.jpeg', 'Ceony Twill arrives at the cottage of Magician Emery Thane with a broken heart. Having graduated at the top of her class from the Tagis Praff School for the Magically Inclined, Ceony is assigned an apprenticeship in paper magic despite her dreams of bespelling metal. And once she''s bonded to paper, that will be her only magic…forever.

Yet the spells Ceony learns under the strange yet kind Thane turn out to be more marvelous than she could have ever imagined—animating paper creatures, bringing stories to life via ghostly images, even reading fortunes. But as she discovers these wonders, Ceony also learns of the extraordinary dangers of forbidden magic.

An Excisioner—a practitioner of dark, flesh magic—invades the cottage and rips Thane''s heart from his chest. To save her teacher''s life, Ceony must face the evil magician and embark on an unbelievable adventure that will take her into the chambers of Thane''s still-beating heart—and reveal the very soul of the man.

From the imaginative mind of debut author Charlie N. Holmberg, The Paper Magician is an extraordinary adventure both dark and whimsical that will delight listeners of all ages.', 222, null, 2014, 36893, (select id from series where hardcover_id = 1656), '1') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Witches', 'Roald Dahl, Quentin Blake', '1417786167', 'https://assets.hardcover.app/edition/5663639/341b4925-d144-4ea4-9f66-1b81ee252d04.jpg', 'This is not a fairy tale. This is about real witches. Real witches don''t ride around on broomsticks. They don''t even wear black cloaks and hats. They are vile, cunning, detestable creatures who disguise themselves as nice, ordinary ladies. So how can you tell when you''re face to face with one? Well, if you don''t know yet you''d better find out quickly-because there''s nothing a witch loathes quite as much as children and she''ll wield all kinds of terrifying powers to get rid of them.', 208, null, 1976, 39482, (select id from series where hardcover_id = 210403), null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Abhorsen', 'Garth Nix', '0606297200', 'https://assets.hardcover.app/external_data/61322940/653996faf7ea6db8f041f852c15d42bde0e7bf75.jpeg', 'Book three in Garth Nix''s internationally acclaimed Old Kingdom fantasy trilogy that began with Sabriel and Lirael.Beneath the earth, a malignant force lies waiting, greedy for freedom from its ancient prison. As the Old Kingdom falls once more into a realm of darkness and terror, the people look desperately to the Abhorsen, the scourge of the Dead, to save them. Yet Abhorsen Sabriel is lost, missing in Ancelstierre.Only Lirael has any chance of stopping the Destroyer. With her companions Sameth, Mogget and the Disreputable Dog, she travels across the Old Kingdom in a race against time, battling Shadow Hands and dark necromancers to reach Ancelstierre before it is too late. But what hope can one young woman have against a terrible evil with the power to destroy life itself?This eagerly awaited conclusion to Garth Nix''s extraordinary Sabriel and Lirael is a complex and vividly imagined story, powerful, terrifying and compelling.This beautiful edition includes Garth Nix''s answers to the questions he is most frequently asked about the Old Kingdom books and writing in general, and a discussion of his favourite books from his own childhood.''The reader''s absorption into the intrigue, magic and dazzling richness of the worlds and characters created by Nix is irresistible pleasure ...'' Australian Review of Books''Terror, courage, bitterness, love, desperation, and sacrifice all swirl together in an apocalyptic climax that pits both Life and Death together against the destruction of everything ... This one is breathtaking, bittersweet and utterly unforgettable.'' Kirkus Reviews', 420, null, 2003, 40324, (select id from series where hardcover_id = 3510), '3') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Bonehunters', 'Steven Erikson', '8417347313', 'https://assets.hardcover.app/edition/1527364/1b83617c99b2698a9d4becf06c48d57c873b57b6.jpeg', 'The Seven Cities Rebellion is over, Sha''ik is dead, but a last rebel force remains, holed up in the city of Y''Ghatan under the fanatical command of Leoman of the Flails. The prospect of laying siege to this ancient fortress makes the battle-weary Malaz 14th Army uneasy - for it was here that the Empire''s greatest champion Dassem Ultor was slain and a tide of Malazan blood spilled... But agents of a far greater conflict have made their opening moves. The Crippled God has been granted a place in the pantheon, a schism threatens, sides must be chosen but whatever each god decides, the rules have changed - and the first blood spilled will be in the mortal world: a world in which a host of characters, familiar and new, search for a fate that they might fashion by their own will. If only the gods would leave them alone. But gods are disinclined to be kind. There shall be war, war in the heavens. And the prize? Nothing less than existence itself...', 1203, null, 2006, 44100, (select id from series where hardcover_id = 1167), '6') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Lirael', 'Garth Nix', '0061474347', 'https://assets.hardcover.app/external_data/59737804/8920d4bfc50c4838861a7e9858f12460f324faf1.jpeg', 'When a dangerous necromancer threatens to unleash a long-buried evil, Lirael and Prince Sameth are drawn into a battle to save the Old Kingdom and reveal their true destinies.', 552, null, 2001, 52026, (select id from series where hardcover_id = 3510), '2') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Deception Point', 'Dan Brown', '1416524886', 'https://assets.hardcover.app/editions/194827/9908714625976342.jpg', 'Deception Point is a 2001 mystery-thriller novel by American author Dan Brown. It is Brown''s third novel. It was published by Simon & Schuster.

The novel follows White House intelligence analyst Rachel Sexton''s involvement in corroborating NASA''s discovery of a meteorite that supposedly contains proof of extraterrestrial life, resembling the ALH84001 case. The discovery comes at a time close to the United States presidential election in which her father is running. The discovery will aid the campaign of her employer, the incumbent president of the United States, Zachary Herney, but put her further at odds with her already estranged father, Senator Sedgwick Sexton, a senator who is running for election. Sexton, accompanied by a team of experts, must uncover the authenticity of the meteorite which will either make or break the campaign of President Herney.

Contains:
[Deception Point [1/2]](https://openlibrary.org/works/OL25327019W)
[Deception Point [2/2]](https://openlibrary.org/works/OL30946570W)', 451, null, 2001, 52468, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Mysterious Benedict Society', 'Trenton Lee Stewart, Carson Ellis', '190642702X', 'https://assets.hardcover.app/external_data/3488427/de6e7588d7fd17e6a0c436bdfea6694717bf2e8b.jpeg', '"Are you a gifted child looking for special opportunities?"

Dozens of children respond to this peculiar ad in the newspaper and are then put through a series of mind-bending tests, which readers take along with them. Only four children--two boys and two girls--succeed. Their challenge: to go on a secret mission that only the most intelligent and inventive children could complete. To accomplish it they will have to go undercover at the Learning Institute for the Very Enlightened, where the only rule is that there are no rules. But what they''ll find in the hidden underground tunnels of the school is more than your average school supplies. So, if you''re gifted, creative, or happen to know Morse Code, they could probably use your help.', 512, null, 2007, 53869, (select id from series where hardcover_id = 2622), '1') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Brave New World / Brave New World Revisited', 'Aldous Huxley, Christopher Hitchens', '9562910369', 'https://assets.hardcover.app/edition/22472892/7fcc858edc546cd2f34805c4dca8d98408e8e2a9.jpeg', 'In *Brave New World*, Aldous Huxley prophesied a capitalist civilization, which had been reconstituted through scientific and psychological engineering, a world in which people are genetically designed to be passive and useful to the ruling class. Huxley opens the book by allowing the reader to eavesdrop on the tour of the fertilizing Room of the Central London Hatchery and Conditioning center, where the high tech reproduction takes place. One of the characters, Bernard Marx, seems alone, harboring an ill-defined longing to break free. Satirical and disturbing, *Brave New World* is set some 600 years into the future. Reproduction is controlled through genetic engineering, and people are bred into a rigid class system. As they mature, they are conditioned to be happy with the roles that society has created for them.', 184, null, 1932, 53913, (select id from series where hardcover_id = 198565), '1') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Rosewater', 'Tade Thompson', '0356513157', 'https://assets.hardcover.app/edition/31497112/f846d11652c5cf5841a545bc8f7eb5ab60d4066a.jpeg', '"Rosewater is a town on the edge. A community formed around the edges of a mysterious biodome, its residents comprise the hopeful, the hungry, and the helpless--people eager for a glimpse inside the dome or a taste of its rumored healing powers. Kaaro is a government agent with a criminal past. A sensitive, he can navigate the massive psychic space created by the dome. But when something within the dome begins killing other sensitives, Kaaro must defy his masters to avert a horrifying future."--Back cover.', 423, null, 2016, 54631, (select id from series where hardcover_id = 2858), '1') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Reality Dysfunction', 'Peter F. Hamilton', '0333634276', 'https://assets.hardcover.app/edition/23538700/75b65ba3b1c1d89771514f9e6c5f85d3e03b2317.jpeg', 'Space is not the only void...In AD 2600 the human race is finally beginning to realize its full potential.  Hundreds of colonized planets scattered across the galaxy host a multitude of prosperous and wildly diverse cultures.  Genetic engineering has pushed evolution far beyond nature''s boundaries, defeating disease and producing extraordinary spaceborn creatures.  Huge fleets of sentient trader starships thrive on the wealth created by the industrialization of entire star systems.  And throughout inhabited space the Confederation Navy keeps the peace.  A true golden age is within our grasp.

But now something has gone catastrophically wrong.  On a primitive colony planet a renegade criminal''s chance encounter with an utterly alien entity unleashes the most primal of all our fears.  An extinct race which inhabited the galaxy aeons ago called it "The Reality Dysfunction."  It is the nightmare which has prowled beside us since the beginning of history. *The Reality Disfunction* is a modern classic of science fiction, an extraordinary feat of storytelling on a truly epic scale.', 1236, null, 1996, 56545, (select id from series where hardcover_id = 3425), '1') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Pride and Prejudice and Zombies', 'Seth Grahame-Smith, Jane Austen', '060617110X', 'https://assets.hardcover.app/edition/4319320/b3dc00d5ffd6afa94029c36fadac3955c2813aab.jpeg', '“It is a truth universally acknowledged that a zombie in possession of brains must be in want of more brains.”

So begins Pride and Prejudice and Zombies, an expanded edition of the beloved Jane Austen novel featuring all-new scenes of bone-crunching zombie mayhem. As our story opens, a mysterious plague has fallen upon the quiet English village of Meryton—and the dead are returning to life! Feisty heroine Elizabeth Bennet is determined to wipe out the zombie menace, but she’s soon distracted by the arrival of the haughty and arrogant Mr. Darcy. What ensues is a delightful comedy of manners with plenty of civilized sparring between the two young lovers—and even more violent sparring on the blood-soaked battlefield. Can Elizabeth vanquish the spawn of Satan? And overcome the social prejudices of the class-conscious landed gentry? Complete with romance, heartbreak, swordfights, cannibalism, and thousands of rotting corpses.', 362, null, 1999, 58414, (select id from series where hardcover_id = 6068), '1') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Orlando', 'Virginia Woolf', '0241436303', 'https://assets.hardcover.app/edition/21037021/4f74bb620e1910386793b93a1d5eab731417396e.jpeg', '"Virginia Woolf''s exuberant ''biography'' tells the story of the cross-dressing, sex-changing Orlando who begins life as a young noble in the sixteenth century and moves through numerous historical and geographical worlds to finish as a modern woman writer in the 1920s. The book is in part a happy tribute to the ''life'' that her love for Vita Sackville-West had breathed into Virginia Woolf''s own day-to-day existence; it is also Woolf''s light-hearted and light-handed teasing out of the assumptions that lie behind the normal conventions for writing about a fictional or historical life. In this novel, Virginia Woolf plays loose and fast: Orlando uncovers a literary and sexual revolution overnight."--Jacket.', 333, null, 1919, 59356, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Daughter of the Empire', 'Raymond E. Feist, Janny Wurts', '0586074813', 'https://assets.hardcover.app/editions/4785088/4790343802542467.jpg', 'Mara, a young, untested Ruling Lady of Kelewan, is called upon to lead her people in a heroic stuggle for survival. But first she must rally an army of rebel warriors, form a pact with the alien cho-ja and marry the son of a hated enemy. Queen Mara of Acoma vows to avenge the deaths of her brother and father, even if it means killing her own husband.', 436, null, 1987, 59480, (select id from series where hardcover_id = 5648), '1') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Beyond the Shadows', 'Brent Weeks', '9022555151', 'https://assets.hardcover.app/external_data/3518106/63e7c8ef81edd77e6408c1242a3e7158fbf8c301.jpeg', 'A new queen has usurped the throne and is leading Cenaria into disaster. The country has become a broken realm with a threadbare army, little food, and no hope. Kylar Stern plans to reinstate his closest friend Logan as King, but can he really get away with murder?
In the north, the Godking''s death has thrown Khalidor into civil war. To gain the upper hand, one faction attempts to raise the goddess Khali herself. But they are playing with volatile powers, and trigger conflict on a vast scale. Seven armies will converge to save - or destroy - an entire continent.
Kylar has finally learnt the bitter cost of immortality, and is faced with a task only he can complete. To save his friends, and perhaps his enemies, he must assassinate a goddess. Failure will doom the south. Success will cost him everything he''s ever loved.', 720, null, 2008, 59766, (select id from series where hardcover_id = 5535), '3') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Heartless', 'Marissa Meyer', '1509818022', 'https://assets.hardcover.app/editions/4207411/afb6ce23-dd28-4f29-874b-b5ae8633a78b-heartless.jpg', 'Catherine may be one of the most adored girls in Wonderland, and a favorite of the yet-unmarried King of Hearts, but her interests lie elsewhere. A talented baker, all she wants is to open a shop with her best friend and supply the Kingdom of Hearts with delectable pastries and confections. But according to her mother, such a goal is unthinkable for the young woman who could be the next Queen.

At a royal ball where Cath is expected to receive the king’s marriage proposal, she meets Jest, the handsome and mysterious court joker. For the first time, she feels the pull of true attraction. At the risk of offending the King and infuriating her parents, she and Jest enter into an intense, secret courtship. Cath is determined to define her own destiny and fall in love on her terms. But in a land thriving with magic, madness, and monsters, fate has other plans.', 450, null, 2015, 70276, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Mother Night', 'Kurt Vonnegut', '9736818284', 'https://assets.hardcover.app/edition/26790089/e72b1c16a366e3e7b2cf1ab3527d9fd8d4cdf247.jpeg', 'Mother Night is a daring challenge to our moral sense. American Howard W. Campbell, Jr., a spy during World War II, is now on trial in Israel as a Nazi war criminal. But is he really guilty? In this brilliant book rife with true gallows humor, Vonnegut turns black and white into a chilling shade of gray with a verdict that will haunt us all.', 268, null, 1962, 80091, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Anthem', 'Ayn Rand, Leonard Peikoff', '1633849864', 'https://assets.hardcover.app/edition/17439533/78ea8acf81427e57581469e38646639a101b9cd9.jpeg', 'Anthem is a tale of a future dark age of the great “we” – a world that deprives individuals of name, independence, and values.

He lived in the dark ages of the future. In a loveless world he dared to love the woman of his choice. In an age that had lost all traces of science and civilization he had the courage to seek and find knowledge. But these were not the crimes for which he would be hunted He was marked for death because he had committed the unpardonable sin: He had stood forth from the mindless human herd. He was alone.', 110, null, 1936, 81466, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Wide Window', 'Lemony Snicket', '853590171X', 'https://assets.hardcover.app/editions/30426300/6647670831477237-20249296.jpg', 'Dear Reader, If you have not read anything about the Baudelaire orphans, then before you read even one more sentence, you should know this: Violet, Klaus, and Sunny are kindhearted and quick-witted, but their lives, I am sorry to say, are filled with bad luck and misery. All of the stories about these three children are unhappy and wretched, and this one may be the worst of them all.If you haven''t got the stomach for a story that includes a hurricane, a signalling device, hungry leeches, cold cucumber soup, a horrible villain, and a doll named Pretty Penny, then this book will probably fill you with despair.I will continue to record these tragic tales, for that is what I do. You, however, should decide for yourself whether you can possibly endure this miserable story. With all due respect, Lemony Snicket', null, null, 2000, 83145, (select id from series where hardcover_id = 1570), '3') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Killing Moon', 'N. K. Jemisin', '0316187283', 'https://assets.hardcover.app/edition/30403184/ccf812e7c4e68efb63637854055d0118d4049ada.jpeg', '**FOLLOWING HER SERIES, HUGO, NEBULA, AND WORLD FANTASY-NOMINATED DEBUT SERIES, N. K. JEMISIN RETURNS WITH A CAPTIVATING NEW TALE.**

In the ancient city-state of Gujaareh, peace is the only law. Upon its rooftops and among the shadows of its cobbled streets wait the Gatherers--the keepers of this peace. Their duty is to harvest the magic of the sleeping mind and use it to heal, soothe...and kill those judged corrupt.

But when a conspiracy blooms within Gujaareh''s great temple, Ehiru--the most famous of the city''s Gatherers--must question everything he knows. Someone, or something, is stalking its prey both in Gujaareh''s alleys and the realm of dreams. Ehiru must now protect the woman he was sent to kill--or watch the city be devoured by war and forbidden magic.

This description comes from the publisher. *The Killing Moon* is the first book in the Dreamblood Duology.', 418, null, 2012, 87698, (select id from series where hardcover_id = 1708), '1') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Dragonfly in Amber', 'Diana Gabaldon', '060636255X', 'https://assets.hardcover.app/edition/32856027/6814aa3a-a287-4fa7-8e3f-0518c85716a0.jpg', 'With her classic novel Outlander, Diana Gabaldon introduced two unforgettable characters—Claire Randall and Jamie Fraser—delighting readers with a story of adventure and love that spanned two centuries. Now Gabaldon returns to that extraordinary time and place in this vivid, powerful sequel to Outlander.
 
For twenty years, Claire Randall has kept her secrets. But now she is returning with her grown daughter to the mysteries of Scotland’s mist-shrouded Highlands. Here Claire plans to reveal a truth as shocking as the events that gave it birth: the secret of an ancient circle of standing stones, the secret of a love that transcends centuries, and the truth of a man named Jamie Fraser—a Highland warrior whose gallantry once drew the young Claire from the security of her century to the dangers of his.
 
Claire’s spellbinding journey continues through the intrigue-ridden French court and the menace of Jacobite plots, to the Highlands of Scotland, through war and death in a desperate fight to save both the child and the man she loves.', 976, null, 1992, 92809, (select id from series where hardcover_id = 1162), '2') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Darkest Minds', 'Alexandra Bracken', '2732451681', 'https://assets.hardcover.app/edition/30399875/f433e3ca8a45e137c3181036b3c5b7430db19a0d.jpeg', 'When Ruby woke up on her tenth birthday, something about her had changed. Something alarming enough to make her parents lock her in the garage and call the police. Something that gets her sent to Thurmond, a brutal government “rehabilitation camp.” She might have survived the mysterious disease that’s killed most of America’s children, but she and the others have emerged with something far worse: frightening abilities they cannot control.

Now sixteen, Ruby is one of the dangerous ones.

When the truth comes out, Ruby barely escapes Thurmond with her life. Now she’s on the run, desperate to find the one safe haven left for kids like herEast River. She joins a group of kids who escaped their own camp. Liam, their brave leader, is falling hard for Ruby. But no matter how much she aches for him, Ruby can’t risk getting close. Not after what happened to her parents.

When they arrive at East River, nothing is as it seems, least of all its mysterious leader. But there are other forces at work, people who will stop at nothing to use Ruby in their fight against the government. Ruby will be faced with a terrible choice, one that may mean giving up her only chance at a life worth living.', 496, null, 2012, 93547, (select id from series where hardcover_id = 5673), '1') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Gateway', 'Frederik Pohl', '0345253787', 'https://assets.hardcover.app/external_data/4209647/d8e6a0e6cb89aedde2e4972ef315ee22d50ccd14.jpeg', 'Heechee Saga', 294, null, 1977, 97435, (select id from series where hardcover_id = 3105), '1') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Pillars of the Earth', 'Ken Follett', '2221190777', 'https://assets.hardcover.app/edition/32856871/bdab1721-61a6-454e-8e1e-05977ef697fe.jpg', 'The Pillars of the Earth tells the story of Philip, prior of Kingsbridge, a devout and resourceful monk driven to build the greatest Gothic cathedral the world has known . . . of Tom, the mason who becomes his architect—a man divided in his soul . . . of the beautiful, elusive Lady Aliena, haunted by a secret shame . . . and of a struggle between good and evil that will turn church against state and brother against brother.
 
A spellbinding epic tale of ambition, anarchy, and absolute power set against the sprawling medieval canvas of twelfth-century England, this is Ken Follett’s historical masterpiece.', 1008, null, 1989, 98094, (select id from series where hardcover_id = 1156), '1') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Inferno', 'Dan Brown', '0385539851', 'https://assets.hardcover.app/edition/21477318/4d7cf319-eaab-4986-9915-e616f2afbc02.jpg', 'Harvard professor of symbology Robert Langdon awakens in an Italian hospital, disoriented and with no recollection of the past thirty-six hours, including the origin of the macabre object hidden in his belongings. With a relentless female assassin trailing them through Florence, he and his resourceful doctor, Sienna Brooks, are forced to flee.

Embarking on a harrowing journey, they must unravel a series of codes, which are the work of a brilliant scientist whose obsession with the end of the world is matched only by his passion for one of the most influential masterpieces ever written: Dante Alighieri’s The Inferno.', 461, null, 2013, 99335, (select id from series where hardcover_id = 1084), '4') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Vita Nostra', 'Marina Dyachenko', '5041011265', 'https://assets.hardcover.app/edition/14143375/008198b60fee7d5242637fdf4caa66641300ee05.jpeg', '"While vacationing at the beach with her mother, Sasha Samokhina meets the mysterious Farit Kozhennikov under the most peculiar circumstances. The teenage girl is powerless to refuse when this strange and unusual man with an air of the sinister directs her to perform a task with potentially scandalous consequences. He rewards her effort with a strange golden coin. As the days progress, Sasha carries out other acts for which she receives more coins from Kozhennikov. As summer ends, her domineering mentor directs her to move to a remote village and use her gold to enter the Institute of Special Technologies. Though she does not want to go to this unknown town or school, she also feels it''s the only place she should be. Against her mother''s wishes, Sasha leaves behind all that is familiar and begins her education. As she quickly discovers, the institute''s "special technologies" are unlike anything she has ever encountered. The books are impossible to read, the lessons obscure to the point of maddening, and the work refuses memorization. Using terror and coercion to keep the students in line, the school does not punish them for their transgressions and failures; instead, their families pay a terrible price. Yet despite her fear, Sasha undergoes changes that defy the dictates of matter and time; experiences which are nothing she has ever dreamed of . . . and suddenly all she could ever want" -- Front jacket flap.', 525, null, 2007, 102463, (select id from series where hardcover_id = 42263), '1') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The BFG', 'Roald Dahl, Quentin Blake', '9188876519', 'https://assets.hardcover.app/book_mappings/7333400/6588de17f8382a796b5e8467c788e8a3bbaa2692.jpeg', 'The BFG is no ordinary bone-crunching giant. He is far too nice and jumbly. It''s lucky for Sophie that he is. Had she been carried off in the middle of the night by the Bloodbottler, or any of the other giants—rather than the BFG—she would have soon become breakfast. When Sophie hears that the giants are flush-bunking off to England to swollomp a few nice little chiddlers, she decides she must stop them once and for all. And the BFG is going to help her!', 199, null, 1982, 103126, (select id from series where hardcover_id = 210403), null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('White Noise', 'Don DeLillo, Richard Powers', '0147798388', 'https://assets.hardcover.app/external_data/3643397/19dc2294223ce8f7b54bb4cbf325a84d4e429084.jpeg', 'White Noise is the story of Jack, his wife, Babette, and their four ultramodern offspring. They live in a college town where Jack is Professor of Hitler Studies (and conceals the fact that he does not speak a word of German), and Babette teaches posture and volunteers by reading tabloids to a group of elderly shut-ins. They are happy enough, until a deadly toxic accident and Babette’s addiction to an experimental drug make Jake question everything. 

White Noise is considered a postmodern classic and its unfolding of themes of consumerism, family and divorce, and technology as a deadly threat have attracted the attention of literary scholars since its publication.', 337, null, 1984, 103997, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Last Hero', 'Terry Pratchett, Paul Kidby', '1417700920', 'https://assets.hardcover.app/edition/31767091/f24f51e506334b41cc6d462b04c0cfbfc6da107d.jpeg', 'Pratchett''s perceptive and laugh-out-loud Discworld series is a literary phenomenon. And in The Last Hero, one aging hero with a grudge decides enough is enough. Beautifully illustrated throughout by Paul Kidby. A brand-new paperback edition of The Last Hero, featuring a new text design, glorious illustrations by Paul Kidby, and a brand-new cover by artist Leo Nicholls. ''An enduring, endearing presence in comic literature'' Guardian It stars the legendary Cohen the Barbarian, a legend in his own lifetime. Cohen can remember when a hero didn''t have to worry about fences and lawyers and civilisation, and when people didn''t tell you off for killing dragons. But he can''t always remember, these days, where he put his teeth... So now, with his ancient sword and his new walking stick and his old friends - and they''re very old friends - Cohen the Barbarian is going on one final quest. He''s going to climb the highest mountain in the Discworld and meet his gods. The last hero in the world is going to return what the first hero stole. With a vengeance. That''ll mean the end of the world, if no one stops him in time.', 238, null, 2001, 108853, (select id from series where hardcover_id = 1018), '27') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Lord of Light', 'Roger Zelazny', '1857988205', 'https://assets.hardcover.app/edition/8741986/aa30a4adc57048824736986cf11d46b595651351.jpeg', 'A colony of humankind is subjugated by the First Colonists, the crew of the starship that brought them to their new home 1000 years before. They have taken control of ancient technologies and enhanced themselves with godlike psychic powers and virtual immortality. Adopting the panoply of the venerable Hindu religion, they live lives as its Gods, surrounded by advanced technology within the trappings of a primitive civilization.

Our hero Sam, unready to battle the tyrannical forces of the Celestial City allied with his former wife, now the rapturous Kali, Goddess of Destruction.  A story of the classic drama of power, love, honor, pride, and fantasy erupting in an epic war of the Gods and ultimate transcendence.', 328, null, 1967, 109204, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The End of Eternity', 'Isaac Asimov', '0765319195', 'https://assets.hardcover.app/edition/30664799/72f3ffbc-c1b3-4e21-81b8-fa2089436916.jpg', 'The story of temporal engineers who meta-regulate the history of humanity through the centuries, eliminating risk, adventure, and space travel in the process. One man rebels in order to save the existence of someone he loves, and in the end the time bureaucracy is destroyed for the sake of individuality and human achievement. The theme is the opposite of the Foundation stories, where the central planners and manipulators of humanity always dominate.', 256, null, 1955, 110329, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Provenance', 'Ann Leckie', '0316388653', 'https://assets.hardcover.app/external_data/61087461/a362f5e9dd8992e9c338a7b456da9057aeef44bd.jpeg', 'A stand-alone adventure set in the world of Ancillary Justice. Ingray has just one chance to secure the status she craves and regain priceless lost artefacts prized by her people: she must free a thief from a prison planet from which no one has ever returned.', 448, null, 2017, 111078, (select id from series where hardcover_id = 993), '4') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Alcatraz vs. the Evil Librarians', 'Brandon Sanderson, Hayley Lazo', '1648812023', 'https://assets.hardcover.app/edition/30513799/3f621ec2db89e9ad72f48b94893421176010913f.jpeg', 'A hero with an incredible talent...for breaking things. A life-or-death mission...to rescue a bag of sand. A fearsome threat from a powerful secret network...the evil Librarians. 

Alcatraz Smedry doesn''t seem destined for anything but disaster. On his 13th birthday he receives a bag of sand, which is quickly stolen by the cult of evil Librarians plotting to take over the world. The sand will give the Librarians the edge they need to achieve world domination. Alcatraz must stop them!...by infiltrating the local library, armed with nothing but eyeglasses and a talent for klutzines', 320, null, 2007, 113379, (select id from series where hardcover_id = 5612), '1') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Judas Unchained', 'Peter F. Hamilton, Marta García Martínez', '1447291670', 'https://assets.hardcover.app/edition/24783790/6806817-L.jpg', 'The previous novel, Pandora''s Star, introduced the Intersolar Commonwealth, a star-spanning civilization of the twenty-fourth century. Robust, peaceful, and confident, the Commonwealth dispatched a ship to investigate the mystery of a disappearing star, only to inadvertently unleash a predatory alien species that turned on its liberators, striking hard, fast, and utterly without mercy. The Prime are the Commonwealth''s worst nightmare. Coexistence is impossible with the technologically advanced aliens, who are genetically hardwired to exterminate all other forms of life. Twenty-three planets have already fallen to the invaders, with casualties in the hundreds of millions. And no one knows when or where the genocidal Prime will strike next. Against this backdrop, Captain Wilson Kime confides to Paula Myo, chief investigator at the Intersolar Serious Crimes Directorate, his belief that humans are being manipulated. For more than a hundred years, a shadowy cult, the Guardians of Selfhood, has warned that an alien with mind-control abilities impossible to detect or resist - the Starflyer - has secretly infiltrated the Commonwealth. Branded as terrorists, the Guardians and their leader, Bradley Johansson, have been hunted by Paula. But now evidence suggests that the Guardians were right all along, and that the Starflyer has placed agents in vital posts throughout the Commonwealth - agents who are now sabotaging the war effort. Is the Starflyer an ally of the Prime, or has it orchestrated a fight to the death between the two species for its own advantage? Caught between two deadly enemies, one a brutal invader striking from without, the other a remorseless cancer killing from within, the fractious Commonwealth must unite as never before.', 827, null, 2005, 117607, (select id from series where hardcover_id = 1138), '2') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Deep', 'Rivers Solomon, Daveed Diggs, William Hutson, Jonathan Snipes', '8412354303', 'https://assets.hardcover.app/book_mappings/7333387/84b5694f80da7146f9e66ad8760d7c952ec7457c.jpeg', 'Yetu holds the memories for her people—water-dwelling descendants of pregnant African slave women thrown overboard by slave owners—who live idyllic lives in the deep. Their past, too traumatic to be remembered regularly is forgotten by everyone, save one—the historian. This demanding role has been bestowed on Yetu.

Yetu remembers for everyone, and the memories, painful and wonderful, traumatic and terrible and miraculous, are destroying her. And so, she flees to the surface escaping the memories, the expectations, and the responsibilities—and discovers a world her people left behind long ago.

Yetu will learn more than she ever expected about her own past—and about the future of her people. If they are all to survive, they’ll need to reclaim the memories, reclaim their identity—and own who they really are.', 166, null, 2019, 118594, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Shadow of Night', 'Deborah Harkness', '0606316264', 'https://assets.hardcover.app/edition/30443430/f084199f-53c4-4860-8f94-057374a04756.jpg', 'When Diana Bishop, descended from a line of powerful witches, discovered a significant alchemical manuscript in the Bodleian Library, she sparked a struggle in which she became bound to long-lived vampire Matthew Clairmont. Now the coexistence of witches, daemons, vampires and humans is dangerously threatened.

Seeking safety, Diana and Matthew travel back in time to London, 1590. But they soon realise that the past may not provide a haven. Reclaiming his former identity as poet and spy for Queen Elizabeth, the vampire falls back in with a group of radicals known as the School of Night. Many are unruly daemons, the creative minds of the age, including playwright Christopher Marlowe and mathematician Thomas Harriot.

Together Matthew and Diana scour Tudor London for the elusive manuscript Ashmole 782, and search for the witch who will teach Diana how to control her remarkable powers...', 592, null, 2011, 119693, (select id from series where hardcover_id = 5579), '2') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Salvation', 'Peter F. Hamilton', '1515962784', 'https://assets.hardcover.app/edition/30557535/73a827f1-3c49-454f-b0a6-2248c2b6224f.jpg', 'An alien shipwreck is found on a newly discovered world, and it carries a cargo as strange as it is horrifying. Security Director Feriton Kayne assembles a high-powered squad to assess the threat. But one of the group is hiding something – it will be up to the team to bring back answers, answers that will change everything . . .

Back on Earth, humanity can extend lifespans indefinitely, travel to the stars via portal technology and even make deserts bloom. We seem invulnerable. So when the alien Olyix contacted us, years earlier, we welcomed them. They needed fuel for their pilgrimage across the galaxy – and in exchange they helped advance our technology. But will they prove a blessing – or a curse?', 592, null, 2018, 119951, (select id from series where hardcover_id = 3428), '1') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Lottery', 'Shirley Jackson', '8845921840', 'https://assets.hardcover.app/external_data/3705178/0c23857d5b26d44c8826b11ba85aae8a63e0803f.jpeg', 'Also contained in:

 - [Come Away with Me](https://openlibrary.org/works/OL3171081W/Come_Along_With_Me)
 - [Fifth Fontana Book of Great Horror Stories](https://openlibrary.org/works/OL15393309W/The_Fifth_Fontana_Book_of_Great_Horror_Stories)
 - [Great Short Stories of the World](https://openlibrary.org/works/OL16048288W/Great_Short_Stories_of_the_World)
 - [Magic of Shirley Jackson](https://openlibrary.org/works/OL3171077W/The_Magic_of_Shirley_Jackson)
 - [Scarlet Letter and Related Readings](https://openlibrary.org/works/OL455418W/Scarlet_Letter_and_Related_Readings)
 - [Scarlet Letter with Connections](https://openlibrary.org/works/OL455436W/Scarlet_Letter_with_Connections)', 32, null, 1948, 123252, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Amazing Maurice and His Educated Rodents', 'Terry Pratchett', '0753173891', 'https://assets.hardcover.app/edition/32195809/f6e7ecf21269240b93778bd4ea1806e2841d559a.jpeg', 'Carnegie Medal Winner * ALA Best Fiction for Young Adults * New York Public Library Books for the Teen Age * VOYA Best Science Fiction, Fantasy, and Horror * Book Sense Pick In this standalone Discworld novel, bestselling fantasy grandmaster Sir Terry Pratchett turns a classic fairy tale on its head, and no one will ever look at the Pied Piper--or rats--the same way again! "Hilarious, moving, scary, impishly vulgar, and wickedly wise." --Locus The Amazing Maurice runs the perfect Pied Piper scam. This streetwise alley cat knows the value of cold, hard cash and can talk his way into and out of anything. But when Maurice and his cohorts decide to con the town of Bad Blinitz, it will take more than fast talking to survive the danger that awaits. For this is a town where food is scarce and rats are hated, where cellars are lined with deadly traps, and where a terrifying evil lurks beneath the hunger-stricken streets.... The Discworld novels can be read in any order, but The Amazing Maurice and His Educated Rodents is a standalone. This book''s feline hero was first mentioned in the Discworld novel Reaper Man and stars in the movie version of his adventure, The Amazing Maurice, featuring David Tenant, Emilia Clarke, Hamish Patel, and Hugh Laurie. Fans of Maurice will relish the adventures of Tiffany Aching, starting with The Wee Free Men and A Hat Full of Sky!', 272, null, 2001, 123382, (select id from series where hardcover_id = 1018), '28') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Shadow of the Hegemon', 'Orson Scott Card', '060630570X', 'https://assets.hardcover.app/edition/29404281/daa64dc6651c1b469b3daa806650b2f43d48b680.jpeg', 'The War is over, won by Ender Wiggin and his team of brilliant child-warriors. The enemy is destroyed, the human race is saved. Ender himself refuses to return to the planet, but his crew has gone home to their families, scattered across the globe. The battle school is no more.

But with the external threat gone, the Earth has become a battlefield once more. The children of the Battle School are more than heroes; they are potential weapons that can bring power to the countries that control them. One by one, all of Ender''s Dragon Army are kidnapped. Only Bean escapes; and he turns for help to Ender''s brother Peter.

Peter Wiggin, Ender''s older brother, has already been manipulating the politics of Earth from behind the scenes. With Bean''s help, he will eventually rule the world.', 451, null, 1995, 123427, (select id from series where hardcover_id = 1051), '2') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Pushing Ice', 'Alastair Reynolds', '0441014011', 'https://assets.hardcover.app/edition/32777315/1e04a6bc-17cb-4529-aabc-c148f605da3d.jpg', '“A thrilling ride in the new era of well-written space adventure”(The Denver Post) from the author of the Revelation Space series. 2057. Bella Lind and the crew of her nuclear-powered ship, the Rockhopper, push ice. They mine comets. But when Janus, one of Saturn’s ice moons, inexplicably leaves its natural orbit and heads out of the solar system at high speed, Bella is ordered to shadow it for the few vital days before it falls forever out of reach. In accepting this mission she sets her ship and her crew on a collision course with destiny—for Janus has many surprises in store, and not all of them are welcome...', 457, null, 2005, 127926, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Wintersmith', 'Terry Pratchett, Paul Kidby', '0061285765', 'https://assets.hardcover.app/edition/31705891/c6d90dfbd7e2c03b47f224272e70559d4c9156a7.jpeg', 'Tiffany Aching is a trainee witch — now working for the seriously scary Miss Treason. But when Tiffany witnesses the Dark Dance — the crossover from summer to winter — she does what no one has ever done before and leaps into the dance. Into the oldest story there ever is. And draws the attention of the wintersmith himself.

As Tiffany-shaped snowflakes hammer down on the land, can Tiffany deal with the consequences of her actions? Even with the help of Granny Weatherwax and the Nac Mac Feegle — the fightin’, thievin’ pictsies who are prepared to lay down their lives for their “big wee hag.”', 384, null, 2006, 129258, (select id from series where hardcover_id = 1018), '35') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Walking Dead, Vol. 1: Days Gone Bye', 'Robert Kirkman, Tony Moore', '0606351361', 'https://assets.hardcover.app/edition/4843817/a323d9ce7614add43afe54d28c92a20417a4c4be.jpeg', 'Rick Grimes is not prepared for this. A couple months ago he was a small town cop who had never fired a shot and only ever saw one dead body. Separated from his family he must now sort through the death and confusion to try and find his wife and son.', 144, null, 2004, 129496, (select id from series where hardcover_id = 5845), '1') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('House of Chains', 'Steven Erikson', '841734716X', 'https://assets.hardcover.app/edition/30748083/2fe516fa-e3f5-49a8-853c-bb3c23825714.png', 'In Northern Genabackis, just before the events recounted in GARDENS OF THE MOON, a raiding party of savage tribal warriors descends from the mountains into the southern flat lands. Their intention is to wreak havoc among the despised lowlanders, but for the one named Karsa Orlong it marks the beginning of what will prove an extraordinary destiny. Some years later, it is the aftermath of the Chain of Dogs. Coltaine, revered commander of the Malazan 7th Army is dead. And now Tavore, elder sister of Ganoes Paran and Adjunct to the Empress, has arrived in the last remaining Malazan stronghold of the Seven Cities to take charge. Untested and new to command, she must hone a small army of twelve thousand soldiers, mostly raw recruits, into a viable fighting force and lead them into battle against the massed hordes of Sha''ik''s Whirlwind. Her only hope lies in resurrecting the shattered faith of the few remaining survivors from Coltaine''s legendary march, veterans one and all.In distant Raraku, in the heart of the Holy Desert, the seer Sha''ik waits with her rebel army. But waiting is never easy. Her disparate collection of warlords - tribal chiefs, High Mages, a renegade Malazan Fist and his sorceror - is locked in a vicious power struggle that threatens to tear the rebellion apart from within. And Sha''ik herself suffers, haunted by the private knowledge of her nemesis, Tavore...her own sister.So begins the awesome new chapter in Steven Erikson''s MALAZAN BOOK OF THE FALLEN - an epic novel of war, intrigue, magic and betrayal from a writer regarded as one of the most original, imaginative and exciting storytellers in fantasy today.', 1044, null, 2002, 130810, (select id from series where hardcover_id = 1167), '4') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Life After Life', 'Kate Atkinson', '9896414076', 'https://assets.hardcover.app/book_mappings/7333177/311fba28fe808cc3f12104078783c45c9d630e74.jpeg', 'What if you could live again and again, until you got it right? On a cold and snowy night in 1910, Ursula Todd is born to an English banker and his wife. She dies before she can draw her first breath. On that same cold and snowy night, Ursula Todd is born, lets out a lusty wail, and embarks upon a life that will be, to say the least, unusual. For as she grows, she also dies, repeatedly, in a variety of ways, while the young century marches on towards its second cataclysmic world war. Does Ursula''s apparently infinite number of lives give her the power to save the world from its inevitable destiny? And if she can -- will she?', 544, null, 2013, 132800, (select id from series where hardcover_id = 1127), '1') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Number the Stars', 'Lois Lowry', '0606044930', 'https://assets.hardcover.app/external_data/59534251/55349128631d81497cc05353d1e720a6f8bf468e.jpeg', 'In 1943, during the German occupation of Denmark, ten-year-old Annemarie learns how to be brave and courageous when she helps shelter her Jewish friend from the Nazis.', 137, null, 1989, 132962, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Mere Christianity', 'C. S. Lewis, Kathleen Norris', '8936501852', 'https://assets.hardcover.app/external_data/43340530/befa3e30068dc360cca1b23097c1560a4ac8e630.jpeg', 'A forceful and accessible discussion of Christian belief that has become one of the most popular introductions to Christianity and one of the most popular of Lewis''s books. Uncovers common ground upon which all Christians can stand together.', 256, null, 1942, 142593, (select id from series where hardcover_id = 129030), null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Casual Vacancy', 'J.K. Rowling', '0316228534', 'https://assets.hardcover.app/editions/5529044/5683124737161778.jpg', 'When Barry Fairbrother dies unexpectedly in his early forties, the little town of Pagford is left in shock. Pagford is, seemingly, an English idyll, with a cobbled market square and an ancient abbey, but what lies behind the pretty façade is a town at war. Rich at war with poor, teenagers at war with their parents, wives at war with their husbands, teachers at war with their pupils…. Pagford is not what it first seems. And the empty seat left by Barry on the town’s council soon becomes the catalyst for the biggest war the town has yet seen. Who will triumph in an election fraught with passion, duplicity and unexpected revelations? Blackly comic, thought-provoking and constantly surprising, *The Casual Vacancy* is J.K. Rowling’s first novel for adults.', 503, null, 2012, 147273, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('On Basilisk Station', 'David Weber', '0671721631', 'https://assets.hardcover.app/editions/30405548/9750822732276612.jpg', 'Having made him look a fool, she''s been exiled to Basilisk Station in disgrace and set up for ruin by a superior who hates her.

Her demoralized crew blames her for their ship''s humiliating posting to an out-of-the-way picket station.

The aborigines of the system''s only habitable planet are smoking homicide-inducing hallucinogens.

Parliament isn''t sure it wants to keep the place; the major local industry is smuggling; the merchant cartels want her head; the star-conquering, so-called "Republic" of Haven is Up To Something; and Honor Harrington has a single, over-age light cruiser with an armament that doesn''t work to police the entire star system.

But the people out to get her have made one mistake. They''ve made her mad.', 464, null, 1993, 148644, (select id from series where hardcover_id = 5704), '1') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Plague', 'Albert Camus, Stuart Gilbert', '3869749288', 'https://assets.hardcover.app/edition/2707798/7be060fefe972fcc6c85a3a65649d64d2517ad03.jpeg', 'The Plague (French: La Peste) is a novel by Albert Camus, published in 1947, that tells the story of a plague sweeping the French Algerian city of Oran. It asks a number of questions relating to the nature of destiny and the human condition. The characters in the book, ranging from doctors to vacationers to fugitives, all help to show the effects the plague has on a populace.', 296, null, 1947, 149844, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Odd Thomas', 'Dean Koontz', '9870408044', 'https://assets.hardcover.app/external_data/3801830/5921fdc4b34844ee12a8158443031990ac8ca6e6.jpeg', 'Over the course of two days, Odd Thomas, his soulmate Stormy Llewellyn, and an assortment of allies make their way through a dark, terrifying world in which past and present, and life and death collide as they try to avert a cataclysm.', 16, null, 2003, 156813, (select id from series where hardcover_id = 5709), '1') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Queen of the Tearling', 'Erika Johansen', '0062328093', 'https://assets.hardcover.app/edition/30400851/5d71bdc2e60ec9bc50cf570c22022ce5f7d16a40.jpeg', '"On her nineteenth birthday, Princess Kelsea Raleigh Glynn, raised in exile, sets out on a perilous journey back to the castle of her birth to ascend her rightful throne. Plain and serious, a girl who loves books and learning, Kelsea bears little resemblance to her mother, the vain and frivolous Queen Elyssa. But though she may be inexperienced and sheltered, Kelsea is not defenseless: Around her neck hangs the Tearling sapphire, a jewel of immense magical power; and accompanying her is the Queen''s Guard, a cadre of brave knights led by the enigmatic and dedicated Lazarus. Kelsea will need them all to survive a cabal of enemies who will use every weapon--from crimson-caped assassins to the darkest blood magic--to prevent her from wearing the crown."--', 512, null, 2014, 162015, (select id from series where hardcover_id = 5714), '1') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Trail of Lightning', 'Rebecca Roanhorse', '3732578399', 'https://assets.hardcover.app/book_mappings/7333302/84bc18c7983e3f7eafd8162e760810290d068050.jpeg', 'One of the Time 100 Best Fantasy Books Of All Time 2019 LOCUS AWARD WINNER, BEST FIRST NOVEL 2019 HUGO AWARD FINALIST, BEST NOVEL Nebula Award Finalist for Best Novel One of Bustle’s Top 20 “landmark sci-fi and fantasy novels” of the decade “Someone please cancel Supernatural already and give us at least five seasons of this badass Indigenous monster-hunter and her silver-tongued sidekick.” —The New York Times “An excitingly novel tale.” —Charlaine Harris, #1 New York Times bestselling author of the Sookie Stackhouse and Midnight Crossroads series “Fun, terrifying, hilarious, and brilliant.” —Daniel José Older, New York Times bestselling author of Shadowshaper and Star Wars: Last Shot “A powerful and fiercely personal journey through a compelling postapocalyptic landscape.” —Kate Elliott, New York Times bestselling author of Court of Fives and Black Wolves While most of the world has drowned beneath the sudden rising waters of a climate apocalypse, Dinétah (formerly the Navajo reservation) has been reborn. The gods and heroes of legend walk the land, but so do monsters—and it is up to one young woman to unravel the mysteries of the past before they destroy the future. Maggie Hoskie is a Dinétah monster hunter, a supernaturally gifted killer. When a small town needs help finding a missing girl, Maggie is their last best hope. But what Maggie uncovers about the monster is much more terrifying than anything she could imagine. Maggie reluctantly enlists the aid of Kai Arviso, an unconventional medicine man, and together they travel the rez, unraveling clues from ancient legends, trading favors with tricksters, and battling dark witchcraft in a patchwork world of deteriorating technology. As Maggie discovers the truth behind the killings, she will have to confront her past if she wants to survive. Welcome to the Sixth World.', 287, null, 2006, 164876, (select id from series where hardcover_id = 5529), '1') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Blue Mars', 'Kim Stanley Robinson', '8384080054', 'https://assets.hardcover.app/edition/30400617/3388adec-fe5e-4bad-908b-7168676972a1.jpg', 'The red planet is red no longer, as Mars has become a perfectly inhabitable world. But while Mars flourishes, Earth is  threatened by overpopulation and ecological disaster. Soon people look to Mars as a refuge, initiating a possible interplanetary conflict, as well as political strife between the Reds, who wish to preserve the planet in its desert state, and the Green "terraformers".  The ultimate fate of Earth, as well as the possibility of new explorations into the solar system, stand in the balance.From the Paperback edition.', 612, null, 199, 167439, (select id from series where hardcover_id = 1114), '3') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Pretties', 'Scott Westerfeld', '0606348468', 'https://assets.hardcover.app/editions/30863063/8478989890207813.jpg', 'Gorgeous. Popular. Perfect.

Perfectly wrong.

Tally has finally become pretty. Now her looks are beyond perfect, her clothes are awesome, her boyfriend is totally hot, and she''s completely popular. It''s everything she''s ever wanted.

But beneath all the fun -- the nonstop parties, the high-tech luxury, the total freedom -- is a nagging sense that something''s wrong. Something important. Then a message from Tally''s ugly past arrives. Reading it, Tally remembers what''s wrong with pretty life, and the fun stops cold.

Now she has to choose between fighting to forget what she knows and fighting for her life -- because the authorities don''t intend to let anyone with this information survive.', 432, null, 2005, 168458, (select id from series where hardcover_id = 5729), '2') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Fangirl', 'Rainbow Rowell', '1509817360', 'https://assets.hardcover.app/edition/30818174/6ec3965b-3b20-406f-9ec5-33baf6405ff2.jpg', 'Okay, the whole world is a Simon Snow fan, but for Cath, being a fan is her life―and she''s really good at it. She and her twin sister, Wren, ensconced themselves in the Simon Snow series when they were just kids; it''s what got them through their mother leaving.

Reading. Rereading. Hanging out in Simon Snow forums, writing Simon Snow fan fiction, dressing up like the characters for every movie premiere.

Cath''s sister has mostly grown away from fandom, but Cath can''t let go. She doesn''t want to.
Now that they''re going to college, Wren has told Cath she doesn''t want to be roommates. Cath is on her own, completely outside of her comfort zone. She''s got a surly roommate with a charming, always-around boyfriend, a fiction-writing professor who thinks fan fiction is the end of the civilized world, a handsome classmate who only wants to talk about words . . . And she can''t stop worrying about her dad, who''s loving and fragile and has never really been alone.

For Cath, the question is: Can she do this? Can she make it without Wren holding her hand? Is she ready to start living her own life? And does she even want to move on if it means leaving Simon Snow behind?', 406, null, 2013, 174866, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Out of the Silent Planet', 'C. S. Lewis', '8499988512', 'https://assets.hardcover.app/external_data/44206403/1e8845f6487fe85cd955503ff21a6dcc48874723.jpeg', 'The first book in Lewis''s Space Trilogy, *Out of the Silent Planet* tells the story of Dr. Elwin Ransom, a philologist who likes to explore the English countryside on foot.  Seeking out a place to stay the night, he ends up at the estate of a colleague who is away in London.  However, the house is not empty.  Ransom stumbles upon the plot of a megalomaniacal scientist and his collaborator, who just happens to be an old schoolmate of Ransom''s.  Drugged, kidnapped, and wisked away in the scientists rocket to the planet Malacandra where he is to serve as a human sacrifice, Dr. Ransom escapes into the strange Malacandran wilderness pursued by his kidnappers and abandoning his hopes of returning to Earth.

Ransom discovers that the inhabitants of Malacandra are not what his kidnappers believed them to be.  In his adventures in the often strangely beautiful, sometimes dangerous, and sometimes surprisingly familiar Malacandra and its inhabitants, Ransom uncovers information about the larger universe and Earth''s place that suggest he has as much to discover about his home planet as he does about the alien Malacandra.', 155, null, 1938, 180190, (select id from series where hardcover_id = 1091), '1') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Mortal Engines', 'Philip Reeve', '9000356539', 'https://assets.hardcover.app/books/447666/21071-L.jpg', 'London is hunting The great Traction City lumbers after a small town, eager to strip its prey of all assets and move on. Resources on the Great Hunting Ground that once was Europe are so limited that mobile cities must consume one another to survive, a practice known as Municipal Darwinism. Tom, an apprentice in the Guild of Historians, saves his hero, Head Historian Thaddeus Valentine, from a murder attempt by the mysterious Hester Shaw -- only to find himself thrown from the city and stranded with Hester in the Out Country. As they struggle to follow the tracks of the city, the sinister plans of London''s leaders begin to unfold ...', 373, null, 2001, 181024, (select id from series where hardcover_id = 6647), '1') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Turn Coat', 'Jim Butcher', '1101032421', 'https://assets.hardcover.app/external_data/45078473/8f86a89227f7c6276c812a484b135d627b9af5de.jpeg', 'The Warden Morgan has been accused of treason against the Wizards of the White Council and theres only one, final punishment for that crime. He''s on the run, wants his name cleared, and needs someone with a knack for backing the underdog. Someone like Harry Dresden...

Now, Harry must uncover a traitor within the Council, keep a less-than-agreeable Morgan under wraps, and avoid coming under scrutiny himself. And a single mistake may cost someone his headsomeone like Harry', 420, null, 2009, 187503, (select id from series where hardcover_id = 990), '11') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('If I Stay', 'Gayle Forman', '3442377277', 'https://assets.hardcover.app/edition/25607816/cb5e252a5b4110f7d23007549e502dcf2f46ea9f.jpeg', '"For Mia, the day started like any other, surrounded by a loving family, an adoring boyfriend, and a bright future filled with music and infinite possibilities. What she never expected is the choice before her now. Caught between life and death, between a happy past and an uncertain future, Mia has to contemplate everything she holds dear and make a choice: to go or to stay. "-- Provided by Amazon', 261, null, 2009, 189027, (select id from series where hardcover_id = 5723), '1') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Surface Detail', 'Iain M. Banks', '1841498939', 'https://assets.hardcover.app/external_data/38918287/b7c6e8a2fecfcd203e39d70095ac44b67f38fca6.jpeg', 'It begins in the realm of the Real, where matter still matters.

It begins with a murder.

And it will not end until the Culture has gone to war with death itself.

Lededje Y''breq is one of the Intagliated, her marked body bearing witness to a family shame, her life belonging to a man whose lust for power is without limit. Prepared to risk everything for her freedom, her release, when it comes, is at a price, and to put things right she will need the help of the Culture.

Benevolent, enlightened and almost infinitely resourceful though it may be, the Culture can only do so much for any individual. With the assistance of one of its most powerful - and arguably deranged - warships, Lededje finds herself heading into a combat zone not even sure which side the Culture is really on. A war - brutal, far-reaching - is already raging within the digital realms that store the souls of the dead, and it''s about to erupt into reality.

It started in the realm of the Real and that is where it will end. It will touch countless lives and affect entire civilizations, but at the center of it all is a young woman whose need for revenge masks another motive altogether.

SURFACE DETAIL is Iain M. Banks'' new Culture novel, a breathtaking achievement from a writer whose body of work is without parallel in the modern history of science fiction.', 627, null, 2010, 191980, (select id from series where hardcover_id = 1102), '9') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Replay', 'Ken Grimwood', '1473226392', 'https://assets.hardcover.app/external_data/59804883/8f34b65b1a25f0d1c13ed78f0b7278aa61b9fc70.jpeg', 'Jeff Winston, forty-three, didn''t know he was a replayer until he died and woke up twenty-five years younger in his college dorm room; he lived another life. And died again. And lived again and died again -- in a continuous twenty-five-year cycle -- each time starting from scratch at the age of eighteen to reclaim lost loves, remedy past mistakes, or make a fortune in the stock market. A novel of gripping adventure, romance, and fascinating speculation on the nature of time, Replay asks the question: "What if you could live your life over again?"', 173, null, 1945, 194063, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Dragon Haven', 'Robin Hobb', '1400193346', 'https://assets.hardcover.app/external_data/50330452/f1ac4279b181e24b69bf361499e8d0c8fd87e01f.jpeg', 'The acclaimed New York Times bestselling author of Dragon Keeper returns with a second enthralling tale of dragons and humans, adventure and discovery, love and freedom. Centuries had passed since dragons last roamed the war-torn world of the Rain Wild River. But as peace once again settled upon the land, a lost generation of sea serpents—ancient, half-starved, and weary—returned to cocoon, certain that they would be reborn as the beautiful and powerful dragons of legend. But their arduous journey exacted a heavy toll, and the proud serpents emerged as sickly, half-formed beasts, unable to fly or hunt . . . or thrive. For years now they have been trapped on a swampy riverbank between forest and river, hungry and barely alive, reliant on humans to provide for them. With their survival at stake, fifteen dragons—among them the wise golden Mercor, the haughty and dazzling silver-blue queen Sintara, and the delicate copper beauty Relpda—have set off on a dangerous trek into the unknown, up the Rain Wild River, in hopes of rediscovering the ancient Elderling city of Kelsingra, the lost haven for dragons and Elderlings alike. The dragons are accompanied by a disparate group of human keepers, rejects from Rain Wild society. They, too, yearn to find Kelsingra and create a home of their own, one in which they may make their own rules and decide their own fate. But is Kelsingra real or merely a fragment of a glorified past buried deep in the dragons'' shared memories? No map exists to guide them, and the noble creatures find their ancient recollections of little use in a land changed by generations of flooding and seismic chaos. As the dragons, the humans—including the strong and defiant Rain Wild girl Thymara; the wealthy dragon scholar and Trader''s wife, Alise; and her companion, the urbane Sedric—and their magical supply barge, captained by the gruff Leftrin, forge their way ever deeper into uncharted wilderness, human and beast alike discover they are changing in mysterious and dangerous ways. While the bonds between them solidify, starvation, flashfloods, and predators will imperil them all. But dragons and humans soon learn that the most savage threats come from within their own company . . . and not all of them may survive. Returning to the territory of her beloved Liveship Traders and Tawny Man trilogies, New York Times bestselling author Robin Hobb creates a lush and ultimately triumphant tale set in an imaginative world of magic and wonder as compelling and emotionally resonant as our own.', 544, null, 2010, 197775, (select id from series where hardcover_id = 6193), '2') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Three Parts Dead', 'Max Gladstone', '1721320687', 'https://assets.hardcover.app/edition/30599003/2c6f8ce01f74fb1b862789649aa1dfbf74e7263b.jpeg', 'A god has died, and it’s up to Tara, first-year associate in the international necromantic firm of Kelethres, Albrecht, and Ao, to bring Him back to life before His city falls apart.

Her client is Kos, recently deceased fire god of the city of Alt Coulumb. Without Him, the metropolis’s steam generators will shut down, its trains will cease running, and its four million citizens will riot.

Tara’s job: resurrect Kos before chaos sets in. Her only help: Abelard, a chain-smoking priest of the dead god, who’s having an understandable crisis of faith.

When Tara and Abelard discover that Kos was murdered, they have to make a case in Alt Coulumb’s courts—and their quest for the truth endangers their partnership, their lives, and Alt Coulumb’s slim hope of survival.

Set in a phenomenally built world in which justice is a collective force bestowed on a few, craftsmen fly on lightning bolts, and gargoyles can rule cities, Three Parts Dead introduces readers to an ethical landscape in which the line between right and wrong blurs.', 332, null, 2012, 200901, (select id from series where hardcover_id = 3249), '1') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Phantom of the Opera', 'Gaston Leroux', '8726572818', 'https://assets.hardcover.app/edition/30476320/10212298a56ef4f7b43c8cb8e4f5a6ffc04de614.jpeg', 'First published in the year 1909, celebrated French writer Gaston Leroux''s fictional work ''The Phantom of the Opera'' is a gothic novel. The novel is partly inspired by historical events at the Paris Opera during the nineteenth century and an apocryphal tale concerning the use of a former ballet pupil''s skeleton in Carl Maria von Weber''s 1841 production of Der Freischütz.', 211, null, 1909, 201074, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Restore Me', 'Tahereh Mafi', '8492918225', 'https://assets.hardcover.app/edition/30399872/ff514711a242fdda447ead90bc5367d9dd735400.jpeg', 'An instant New York Times bestseller! Juliette and Warner’s story continues in the electrifying fourth installment of Tahereh Mafi’s bestselling Shatter Me series.

The girl with the power to kill with a single touch now has the world in the palm of her hand. Juliette Ferrars thought she’d won. She took over Sector 45, was named the new Supreme Commander of North America, and now has Warner by her side. But when tragedy strikes, she must confront the darkness that dwells both around and inside her.

Who will she become in the face of adversity? Will she be able to control the power she wields, and use it for good?

This bestselling series from powerhouse author Tahereh Mafi showcases relentlessly thrilling action, heart-stopping romance, and a war-torn world in which rebellion is the only path to freedom.', 435, null, 2018, 205581, (select id from series where hardcover_id = 1064), '4') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Quidditch Through the Ages', 'J.K. Rowling, Kennilworthy Whisp', '4863893809', 'https://assets.hardcover.app/edition/17495108/6997871b26eae5571c991494359885c819beafc2.jpeg', 'If you have ever asked yourself where the Golden Snitch came from, how the Bludgers came into existence, or why the Wigtown Wanderers have pictures of meat cleavers on their robes, you need QUIDDITCH THROUGH THE AGES. This invaluable volume is consulted by young Quidditch fans on an almost daily basis.

Proceeds from the sale of this book will go to Comic Relief, who will use your money to continue improving and changing lives -- work that is even more important and astonishing than the three-and-a-half-second capture of the Golden Snitch by Roderick Plumpton in 1921.', null, null, 2001, 213743, (select id from series where hardcover_id = 5441), '2') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('To Say Nothing of the Dog', 'Connie Willis', '5170652208', 'https://assets.hardcover.app/editions/23176457/6022320910080636.jpg', 'From Connie Willis, winner of multiple Hugo and Nebula Awards, comes a comedic romp through an unpredictable world of mystery, love, and time travel . . . Ned Henry is badly in need of a rest. He’s been shuttling between the 21st century and the 1940s searching for a Victorian atrocity called the bishop''s bird stump. It’s part of a project to restore the famed Coventry Cathedral, destroyed in a Nazi air raid over a hundred years earlier. But then Verity Kindle, a fellow time traveler, inadvertently brings back something from the past. Now Ned must jump back to the Victorian era to help Verity put things right—not only to save the project but to prevent altering history itself.', 514, null, 1997, 216723, (select id from series where hardcover_id = 1137), '2') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Look to Windward', 'Iain M. Banks', '2221095529', 'https://assets.hardcover.app/edition/25573835/8e3bc43d4746b23170b97a637d606f57eb6b0680.jpeg', 'It was one of the less glorious incidents of a long-ago war.

It led to the destruction of two suns and the billions of lives they supported.

Now, eight hundred years later, the light from the first of those ancient mistakes has reached the Culture Orbital, Masaq.

The light from the second may not.', 403, null, 2000, 222307, (select id from series where hardcover_id = 1102), '7') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('World Without End', 'Ken Follett', '8466341773', 'https://assets.hardcover.app/edition/24593311/19794160-798a-411e-a441-223b2a6bcd13.jpg', 'World Without End takes place in the same town of Kingsbridge, two centuries after the townspeople finished building the exquisite Gothic cathedral that was at the heart of The Pillars of the Earth. The cathedral and the priory are again at the center of a web of love and hate, greed and pride, ambition and revenge, but this sequel stands on its own. This time the men and women of an extraordinary cast of characters find themselves at a crossroads of new ideas—about medicine, commerce, architecture, and justice. In a world where proponents of the old ways fiercely battle those with progressive minds, the intrigue and tension quickly reach a boiling point against the devastating backdrop of the greatest natural disaster ever to strike the human race—the Black Death. ', 1030, null, 2007, 222828, (select id from series where hardcover_id = 1156), '2') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Dark Force Rising', 'Timothy Zahn', '8863551928', 'https://assets.hardcover.app/edition/23248383/11435c31f07c2b91b2297f2da3b1c588e6fe3139.jpeg', 'The dying Empire''s most cunning and ruthless warlord--Grand Admiral Thrawn--has taken command of the remnants of the Imperial fleet and launched a massive campaign aimed at the New Republic''s destruction. With the aid of unimaginable weapons long hidden away by the Emperor on a backwater planet, Thrawn plans to turn the tide of battle, overwhelm the New Republic, and impose his iron rule throughout the galaxy. Meanwhile, Han and Lando Calrissian race against time to find proof of treason inside the highest Republican Council--only to discover instead a ghostly fleet of warships that could bring doom to their friends and victory to their enemies. Yet most dangerous of all is a new Dark Jedi, risen from the ashes of a shrouded past, consumed by bitterness... and scheming to corrupt Luke Skywalker to the Dark Side.', 439, null, 1992, 229885, (select id from series where hardcover_id = 1110), '2') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('There There', 'Tommy Orange', '0771073011', 'https://assets.hardcover.app/edition/30404859/38c2c5e2c2ba5cf0f6438f738d86c76ab5113e4f.jpeg', 'A contemporary classic, this “astonishing literary debut” (Margaret Atwood, bestselling author of The Handmaid’s Tale) “places Native American voices front and center” (NPR/Fresh Air).

Among them is Jacquie Red Feather, newly sober and trying to make it back to the family she left behind. Dene Oxendene, pulling his life together after his uncle’s death and working at the powwow to honor his memory. Fourteen-year-old Orvil, coming to perform traditional dance for the very first time. They converge and collide on one fateful day at the Big Oakland Powwow and together this chorus of voices tells of the plight of the urban Native American—grappling with a complex and painful history, with an inheritance of beauty and spirituality, with communion and sacrifice and heroism

A book with “so much jangling energy and brings so much news from a distinct corner of American life that it’s a revelation” (The New York Times). It is fierce, funny, suspenseful, and impossible to put down–full of poetry and rage, exploding onto the page with urgency and force. There There is at once poignant and unflinching, utterly contemporary and truly unforgettable.
', 292, null, 2018, 231490, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Reaper''s Gale', 'Steven Erikson', '1409083292', 'https://assets.hardcover.app/external_data/30193027/415184bab336dc819ee74387d28ff65ecc55f86e.jpeg', 'All is not well in the Letherii Empire. Rhulad Sengar, the Emperor of a Thousand Deaths, spirals into madness, surrounded by sycophants and agents of his Machiavellian chancellor, while the Letherii secret police conduct a campaign of terror against its own people. The Errant, once a farseeing god, is suddenly blind to the future. Conspiracies seethe throughout the palace, as the empire - driven by the corrupt and self-interested - edges ever-closer to all-out war with the neighbouring kingdoms. And the great Edur fleet - its warriors selected from countless peoples - draws ever closer. Amongst them are Karsa Orlong and Icarium Lifestealer - each destined to cross blades with the emperor himself. That yet more blood is to be spilled is inevitable... Against this backdrop, a band of fugitives seek a way out of the empire, but one of them, Fear Sengar must find the soul of Scabandari Bloodeye. It is his hope that it might help halt the Tiste Edur, and so save his brother, the emperor. Yet, travelling with them is Scabandari''s most ancient foe: Silchas Ruin, brother of Anomander Rake. And his motives are anything but certain - for the wounds he carries on his back, made by the blades of Scabandari, are still fresh. Fate decrees that there is to be a reckoning, for such bloodshed cannot go unanswered - and it will be a reckoning on an unimaginable scale... A brutal, harrowing novel of war, intrigue and dark, uncontrollable magic, this is epic fantasy at its most imaginative, storytelling at its most thrilling.', 910, null, 2007, 236602, (select id from series where hardcover_id = 1167), '7') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Book of Life', 'Deborah Harkness', '1611762669', 'https://assets.hardcover.app/edition/27863835/74d708b7-6693-42cf-b394-8528d219f32d.jpg', 'After travelling through time in SHADOW OF NIGHT, the second book in Deborah Harkness''s enchant­ing series, historian and witch Diana Bishop and vampire scientist Matthew Clairmont return to the present to face new crises and old enemies.

At Matthew''s ancestral home in France they reunite with their families - with one heart-breaking exception. But the real threat to their future is yet to be revealed, and when it is, the search for the elusive manuscript Ashmole 782 and its missing pages takes on a terrifying urgency.

Using ancient knowl­edge and modern science, from the palaces of Venice and beyond, Diana and Matthew will finally learn what the witches discovered so many centuries ago.', 523, null, 2014, 238651, (select id from series where hardcover_id = 5579), '3') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Strain', 'Guillermo del Toro, Chuck Hogan', '1616555483', 'https://assets.hardcover.app/edition/19097091/abaf6744b00281c063a9ce084f8520721982f211.jpeg', 'A Boeing 777 arrives at JFK and is on its way across the tarmac, when it suddenly stops dead. All window shades are pulled down. All lights are out. All communication channels have gone quiet. Crews on the ground are lost for answers, but an alert goes out to the CDC. Dr. Eph Goodweather, head of their Canary project, a rapid-response team that investigates biological threats, gets the call and boards the plane. What he finds makes his blood run cold.

In a pawnshop in Spanish Harlem, a former professor and survivor of the Holocaust named Abraham Setrakian knows something is happening. And he knows the time has come, that a war is brewing . . .

So begins a battle of mammoth proportions as the vampiric virus that has infected New York begins to spill out into the streets. Eph, who is joined by Setrakian and a motley crew of fighters, must now find a way to stop the contagion and save his city—a city that includes his wife and son—before it is too late.

An epic battle for survival begins between man and vampire in The Strain—the first book in a heart-stopping trilogy from one of Hollywood’s most inventive storytellers and a critically acclaimed thriller writer. Guillermo del Toro, the genius director of the Academy Award-winning Pan’s Labyrinth and Hellboy, and Hammett Award-winning author Chuck Hogan have joined forces to boldly reinvent the vampire novel. Brilliant, blood-chilling, and unputdownable, The Strain is a nightmare of the first order.', 422, null, 2009, 242191, (select id from series where hardcover_id = 203164), '1') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Overstory', 'Richard Powers', '2749158842', 'https://assets.hardcover.app/edition/30401461/19567cead6be7afe3c46572b7219daa6620b892b.jpeg', 'WINNER OF THE PULITZER PRIZE NEW YORK TIMES BESTSELLER An Air Force loadmaster in the Vietnam War is shot out of the sky, then saved by falling into a banyan. An artist inherits a hundred years of photographic portraits, all of the same doomed American chestnut. A hard-partying undergraduate in the late 1980s electrocutes herself, dies, and is sent back into life by creatures of air and light. A hearing- and speech-impaired scientist discovers that trees are communicating with one another. These four, and five other strangers—each summoned in different ways by trees—are brought together in a last and violent stand to save the continent’s few remaining acres of virgin forest. In his twelfth novel, National Book Award winner Richard Powers delivers a sweeping, impassioned novel of activism and resistance that is also a stunning evocation of—and paean to—the natural world. From the roots to the crown and back to the seeds, The Overstory unfolds in concentric rings of interlocking fables that range from antebellum New York to the late twentieth-century Timber Wars of the Pacific Northwest and beyond, exploring the essential conflict on this planet: the one taking place between humans and nonhumans. There is a world alongside ours—vast, slow, interconnected, resourceful, magnificently inventive, and almost invisible to us. This is the story of a handful of people who learn how to see that world and who are drawn up into its unfolding catastrophe. The Overstory is a book for all readers who despair of humanity’s self-imposed separation from the rest of creation and who hope for the transformative, regenerating possibility of a homecoming. If the trees of this earth could speak, what would they tell us? "Listen. There’s something you need to hear."', 502, null, 2018, 243129, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Superintelligence: Paths, Dangers, Strategies', 'Nick Bostrom, Napoleon Ryan', '0198739834', 'https://assets.hardcover.app/external_data/24975705/6188b294ae7b1fb1a229f50e6d623cc737653262.jpeg', 'The human brain has some capabilities that the brains of other animals lack. It is to these distinctive capabilities that our species owes its dominant position. Other animals have stronger muscles or sharper claws, but we have cleverer brains. If machine brains one day come to surpass human brains in general intelligence, then this new superintelligence could become very powerful. As the fate of the gorillas now depends more on us humans than on the gorillas themselves, so the fate of our species then would come to depend on the actions of the machine superintelligence. But we have one advantage: we get to make the first move. Will it be possible to construct a seed AI or otherwise to engineer initial conditions so as to make an intelligence explosion survivable? How could one achieve a controlled detonation? To get closer to an answer to this question, we must make our way through a fascinating landscape of topics and considerations. Read the book and learn about oracles, genies, singletons; about boxing methods, tripwires, and mind crime; about humanity''s cosmic endowment and differential technological development; indirect normativity, instrumental convergence, whole brain emulation and technology couplings; Malthusian economics and dystopian evolution; artificial intelligence, and biological cognitive enhancement, and collective intelligence.', null, null, 2014, 247328, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Screwtape Letters', 'C. S. Lewis', '5902430127', 'https://assets.hardcover.app/edition/30400086/0ad4a540-9e05-4ef2-8a9c-97dad0f9096f.png', 'This profound and striking narrative takes the form of a series of letters from Screwtape, a devil high in the Infernal Civil Service, to his nephew Wormwood, a junior colleague engaged in his first mission on earth, trying to secure the damnation of a young man who has just become a Christian. 

Although the young man initially looks to be a willing victim, he changes his ways and is "lost" to the young devil. 

Dedicated to Lewis''s friend and colleague J. R. R. Tolkien, The Screwtape Letters is a timeless classic on spiritual conflict and the psychology of temptation which are part of our religious experience', 272, null, 1942, 249749, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Shadow''s Edge', 'Brent Weeks', '184149741X', 'https://assets.hardcover.app/external_data/30226991/0803ab750bfed0afaeef844cdc6ef56f450c24d7.jpeg', 'Kylar Stern has rejected the assassin''s life. In the wake of the Godking''s violent coup, both his master and his closest friend are dead. His friend was Logan Gyre, heir to Cenaria''s throne, but few of the ruling class survive to mourn his loss. So Kylar is starting over: new city, new companions, and new profession.
But when he learns that Logan might be alive, trapped and in hiding, Kylar faces an impossible choice. He could give up the way of shadows forever, and find peace with his young family. Or Kylar could succumb to his flair for destruction, the years of training, to save his friend and his country - and lose all he holds precious.', 656, null, 2008, 249941, (select id from series where hardcover_id = 5535), '2') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Atlas Shrugged', 'Ayn Rand, Leonard Peikoff', '0451132157', 'https://assets.hardcover.app/book_mappings/7332596/2fa893c1afc323f67e0706b831d0eb9f417ac97e.jpeg', 'Set in a near-future U.S.A. whose economy is collapsing as a result of the mysterious disappearance of leading innovators and industrialists, this novel presents an astounding panorama of human life-from the productive genius who becomes a worthless playboy...to the great steel industrialist who does not know that he is working for his own destruction...to the philosopher who becomes a pirate...to the woman who runs a transcontinental railroad...to the lowest track worker in her train tunnels.

Peopled by larger-than-life heroes and villains, charged with towering questions of good and evil, Atlas Shrugged is a philosophical revolution told in the form of an action thriller.', 946, null, 1957, 257153, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Freedom', 'Daniel Suarez', '0525951571', 'https://assets.hardcover.app/external_data/59735153/06028c3026e4ab2b42150a2ae9fc0b867184a7f3.jpeg', 'Human freedom has one last hope to survive the information revolution in the epic, apocalyptic sequel to the international bestseller Daemon. The Daemon - a lethal computer program created by a twisted genius - is firmly in control and moving towards its endgame. As the global economy begins to collapse, the world''s most powerful organizations - monolithic corporations, complete with armies of their own - prepare to fight their unseen enemy. When civil conflict erupts in the United States, former detective Pete Sebeck finds himself forced to protect the new world order. Amid conflicting loyalties, rapidly diminishing human power and the possibility that anyone can be a daemon operative or a corporate spy, Sebeck knows that he embodies the last hope that freedom can survive the information revolution.', 416, null, 2010, 258738, (select id from series where hardcover_id = 1056), '2') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Leviathan', 'Scott Westerfeld, Alan Cumming', '0857070002', 'https://assets.hardcover.app/external_data/60908905/84631ca7eb3680df8cc9b6bb240a920cdc278ed9.jpeg', 'The year is 1914 and Europe, armed with futuristic machines and biotechnology, is on the precipice of war. Prince Aleksandar is fleeing for his life, having discovered that his parents have been assassinated and he is now a target for the Clanker Powers, a group determined to take over the globe with their mechanical machinery. When he meets Deryn Sharpe, an orphan girl who has disguised herself as a boy so she can to join the British Air Service, they form an uneasy, but necessary, alliance. But the pair will soon discover that their emerging friendship will dramatically change their lives - and the entire course of the Great World War...', null, null, 2002, 259887, (select id from series where hardcover_id = 1792), '1') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Invisible Cities', 'Italo Calvino, Anthony Doerr, Karina Maria Puente Frantzen', '1784871885', 'https://assets.hardcover.app/edition/32603206/20656abffd58474aa2973211008aff5d6c8aefe1.jpeg', '“Cities, like dreams, are made of desires and fears, even if the thread of their discourse is secret, their rules are absurd, their perspectives deceitful, and everything conceals something else.” In a garden sit the aged Kublai Khan and the young Marco Polo—Mongol emperor and Venetian traveler. Kublai Khan has sensed the end of his empire coming soon. Marco Polo diverts his host with stories of the cities he has seen in his travels around the empire: cities and memory, cities and desire, cities and designs, cities and the dead, cities and the sky, trading cities, hidden cities. As Marco Polo unspools his tales, the emperor detects these fantastic places are more than they appear.', 174, null, 1972, 260343, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Invisible Man', 'Ralph Ellison', '0451027221', 'https://assets.hardcover.app/external_data/4049609/10ca8857cf6647f99bdf87774a74d27b849b2ede.jpeg', 'Invisible Man is the story of a young black man from the South who does not fully understand racism in the world. Filled with hope about his future, he goes to college, but gets expelled for showing one of the white benefactors the real and seamy side of black existence. He moves to Harlem and becomes an orator for the Communist party, known as the Brotherhood. In his position, he is both threatened and praised, swept up in a world he does not fully understand. As he works for the organization, he encounters many people and situations that slowly force him to face the truth about racism and his own lack of identity. As racial tensions in Harlem continue to build, he gets caught up in a riot that drives him to a manhole. In the darkness and solitude of the manhole, he begins to understand himself - his invisibility and his identity. He decides to write his story down (the body of the novel) and when he is finished, he vows to enter the world again.', 610, null, 1952, 261317, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Pattern Recognition', 'William Gibson', '0399149864', 'https://assets.hardcover.app/edition/30399419/4c7e0c329106c349de3505153b3607b0a5064bae.jpeg', 'One of the most influential and imaginative writers of the past twenty years turns his attention to London - with dazzling results.Cayce Pollard owes her living to her pathological sensitivity to logos. In London to consult for the world''s coolest ad agency, she finds herself catapulted, via her addiction to a mysterious body of fragmentary film footage, uploaded to the Web by a shadowy auteur, into a global quest for this unknown ''garage Kubrick''. Cayce becomes involved with an eccentric hacker, a vengeful ad executive, a defrocked mathematician, a Tokyo Otaku-coven known as Eye of the Dragon and, eventually, the elusive ''Kubrick'' himself. William Gibson''s new novel is about the eternal mystery of London, the coolest sneakers in the world, and life in (the former) USSR.', 367, null, 2003, 265984, (select id from series where hardcover_id = 5551), '1') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('A Farewell to Arms', 'Ernest Hemingway', '9798212633673', 'https://assets.hardcover.app/external_data/3309645/ba66bced530b505b7730d34cbcb25fe85f2568ce.jpeg', '"Their romance begins tentatively, built on moments of solace in an otherwise shattered world. But as their connection deepens, it becomes a beacon of hope and escape—a fragile sanctuary from the horrors around them. Their love story is passionate yet fraught with obstacles, as both the war and their inner struggles threaten to pull them apart.

     Hemingway’s stark, unadorned prose cuts to the core, rendering every moment vivid and deeply felt. He weaves a narrative that not only captures the grit and terror of battle but also illuminates the tenderness and vulnerability of two people daring to love in an unforgiving world. Themes of loyalty, sacrifice, disillusionment, and the unyielding passage of fate are woven seamlessly into a story that is as gripping as it is profoundly human.

     As Frederic grapples with the meaning of duty, honor, and personal survival, A Farewell to Arms confronts the universal questions that arise in times of conflict: How do we hold onto our humanity when surrounded by inhumanity? And can love truly triumph in a world overshadowed by death and despair?"-- Provided by Amazon', 352, null, 1929, 271546, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Feed', 'Mira Grant', '2070459047', 'https://assets.hardcover.app/edition/30399911/9acdd36931b45ed9f8c1013c2a4ba7b7863187ec.jpeg', 'BOOK 1 IN THE NEW YORK TIMES BESTSELLING SERIES

''Gripping, thrilling and brutal . . . a masterpiece of suspense'' Publishers Weekly

''The zombie novel Robert A. Heinlein might have written'' Sci-Fi Magazine

The year was 2014. We had cured cancer. We had beaten the common cold. But in doing so we created something new, something terrible that no one could stop. The infection spread, virus blocks taking over bodies and minds with one, unstoppable command: FEED.

Now, twenty years after the Rising, bloggers Georgia and Shaun Mason are on the trail of the biggest story of their lives - the dark conspiracy behind the infected. The truth will get out, even if it kills them.', 608, null, 2010, 273279, (select id from series where hardcover_id = 5552), '1') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Kill Order', 'James Dashner', '0606355723', 'https://assets.hardcover.app/external_data/61838742/efbb2199a4e6b3c0dc5c1ed7b2f18691635adba3.jpeg', 'Before WICKED was formed, before the Glade was built, before Thomas entered the Maze, sun flares hit the earth and mankind fell to disease.

Mark and Trina were there when it happened, and they survived. But surviving the sun flares was easy compared to what came next. Now a disease of rage and lunacy races across the eastern United States, and there’s something suspicious about its origin. Worse yet, it’s mutating, and all evidence suggests that it will bring humanity to its knees.

Mark and Trina are convinced there’s a way to save those left living from descending into madness. And they’re determined to find it—if they can stay alive. Because in this new, devastated world, every life has a price. And to some, you’re worth more dead than alive.', 369, null, 2012, 277804, (select id from series where hardcover_id = 1073), '4') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Robots of Dawn', 'Isaac Asimov', '0898451426', 'https://assets.hardcover.app/edition/27747434/a66879b034e13c675624c8237842bf316cab3c59.jpeg', 'A millennium into the future two advances have altered the course of human history: the colonization of the Galaxy and the creation of the positronic brain. Isaac Asimov''s Robot novels chronicle the unlikely partnership between a New York City detective and a humanoid robot who must learn to work together.

Detective Elijah Baley is called to the Spacer world Aurora to solve a bizarre case of roboticide. The prime suspect is a gifted roboticist who had the means, the motive, and the opportunity to commit the crime. There''s only one catch: Baley and his positronic partner, R. Daneel Olivaw, must prove the man innocent. For in a case of political intrigue and love between woman and robot gone tragically wrong, there''s more at stake than simple justice. This time Baley''s career, his life, and Earth''s right to pioneer the Galaxy lie in the delicate balance. ', 432, null, 1958, 278611, (select id from series where hardcover_id = 1044), '3') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Alanna: The First Adventure', 'Tamora Pierce', '1417720611', 'https://assets.hardcover.app/edition/8811964/fa46d44ce768b26dc73771de2636675b3655b044.jpeg', '"From now on, I''m Alan of Trebond, the younger twin. I''ll be a knight.

And so yound Alanna of Trebond begins the journey to knighthood. Though a girl, Alanna has always craved the adventure and daring allowed only for boys; her twin brother, Thom, yearns to learn the art of magin. So one day they decide to switch places. Disguised as a girl, Thom heads for the convent to learn magic; Alanna, pretending to be a boy, is on her way to the castle of King Roald to begin training as a page.

But the road to knighthood is not an easy one. As Alanna masters the skills necessary for battle, she must also learn to control her heart and discern her enemies from her allies.

Filled with swords and scorcery, adventure and intrigue, good and evil, Alanna''s first adventure begins--one that will lead to the fulfillment of her dreams and the magical destiny that will mke her a legend in her land.', 288, null, 1983, 282955, (select id from series where hardcover_id = 5553), '1') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Little Brother', 'Cory Doctorow', '9639828483', 'https://assets.hardcover.app/external_data/4011880/701f78304996ce8e0571c2267a7a0b7ef7e69cf7.jpeg', 'Interrogated for days by the Department of Homeland Security in the aftermath of a terrorist attack on San Francisco, 17-year-old Marcus is released into what is now a police state and decides to use his expertise in computer hacking to set things right.', 386, null, 2008, 284514, (select id from series where hardcover_id = 6274), '1') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Midnight Tides', 'Steven Erikson', '1804995525', 'https://assets.hardcover.app/edition/30422707/52917419a0ded86ecca16b576418d2fa7b2c2983.jpeg', 'After decades of internecine warfare, the tribes of the Tiste Edur have at last united under the Warlock King of the Hiroth. There is peace--but it has been exacted at a terrible price: a pact made with a hidden power whose motives are at best suspect, at worst, deadly.

To the south, the expansionist kingdom of Lether, eager to fulfill its long-prophesized renaissance as an Empire reborn, has enslved all its less-civilized neighbors with rapacious hunger. All, that is, save one--the Tiste Edur. And it must be only a matter of time before they too fall--either beneath the suffocating weight of gold, or by slaughter at the edge of a sword. Or so destiny has decreed.
Yet as the two sides gather for a pivotal treaty neither truly wants, ancient forces are awakening. For the impending struggle between these two peoples is but a pale reflection of a far more profound, primal battle--a confrontation with the still-raw wound of an old betrayal and the craving for revenge at its seething heart.', 966, null, 2004, 289044, (select id from series where hardcover_id = 1167), '5') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('S.', 'Doug Dorst, J.J. Abrams', '8817068691', 'https://assets.hardcover.app/edition/3857770/4ec4b478-3677-48d1-ba05-778b91ee3ed0.jpg', 'This one-of-a-kind bestseller from J.J. Abrams and Doug Dorst captures the excitement of solving a mystery like no other book: "Both as literature and as a physical object, S. is a profound and tremendous work of art" (Miami Herald). 

One book. Two readers. A world of mystery, menace, and desire.

The chronicle of two readers finding each other, and their deadly struggle with forces beyond their understanding — all within the margins of a book conceived by Star Wars director J.J. Abrams and written by award-winning novelist Doug Dorst.

The book: Ship of Theseus, the final novel by a prolific but enigmatic writer named V.M. Straka, in which a man with no past is shanghaied onto a strange ship with a monstrous crew and launched onto a disorienting and perilous journey.

The writer: Straka, the incendiary and secretive subject of one of the world''s greatest mysteries, a revolutionary about whom the world knows nothing apart from the words he wrote and the rumors that swirl around him.

The readers: Jennifer and Eric, a college senior and a disgraced grad student, both facing crucial decisions about who they are, who they might become, and how much they''re willing to trust another person with their passions, hurts, and fears.

S. contains 22 inserts and will be delivered in a sealed slipcase. 
', 473, null, 2013, 305890, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Prodigy', 'Marie Lu', '2362310930', 'https://assets.hardcover.app/external_data/47189964/c4b2d4f12f22daef074b3badc50c49be2921e9c0.jpeg', 'June and Day arrive in Vegas just as the unthinkable happens: the Elector Primo dies, and his son Anden takes his place. With the Republic edging closer to chaos, the two join a group of Patriot rebels eager to help Day rescue his brother and offer passage to the Colonies. They have only one request—June and Day must assassinate the new Elector. It’s their chance to change the nation, to give voice to a people silenced for too long. 

But as June realizes this Elector is nothing like his father, she’s haunted by the choice ahead. What if Anden is a new beginning? What if revolution must be more than loss and vengeance, anger and blood—what if the Patriots are wrong?

In this highly-anticipated sequel to the New York Times bestseller Legend, Lu delivers a breathtaking thriller with high stakes and cinematic action. ', 418, null, 2013, 306888, (select id from series where hardcover_id = 5717), '2') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Toll the Hounds', 'Steven Erikson', '8490696896', 'https://assets.hardcover.app/edition/30512989/5974ba1d-0e98-4292-8e38-0f9d14d464fd.png', 'In Darujhistan, the city of blue fire, it is said that love and death shall arrive dancing. It is summer and the heat is oppressive, but for the small round man in the faded red waistcoat, discomfiture is not just because of the sun. All is not well. Dire portents plague his nights and haunt the city streets like fiends of shadow. Assassins skulk in alleyways, but the quarry has turned and the hunters become the hunted.

Hidden hands pluck the strings of tyranny like a fell chorus. While the bards sing their tragic tales, somewhere in the distance can be heard the baying of Hounds...And in the distant city of Black Coral, where rules Anomander Rake, Son of Darkness, ancient crimes awaken, intent on revenge. It seems Love and Death are indeed about to arrive...hand in hand, dancing.

A thrilling, harrowing novel of war, intrigue and dark, uncontrollable magic, Toll the Hounds is the new chapter in Erikson''s monumental series - epic fantasy at its most imaginative and storytelling at its most exciting.', 1299, null, 2008, 309316, (select id from series where hardcover_id = 1167), '8') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Titus Groan', 'Mervyn Peake, Anthony Burgess', '1483069745', 'https://assets.hardcover.app/edition/31640722/891acf39-e767-4e0a-8018-9c6cde3dbc23.jpg', 'As the novel opens, Titus, heir to Lord Sepulchrave, has just been born. He stands to inherit the miles of rambling stone and mortar that form Gormenghast Castle. Meanwhile, far away and in the kitchen, a servant named Steerpike escapes his drudgework and begins an auspicious ascent to power.Inside of Gormenghast, all events are predetermined by complex rituals, the origins of which are lost in time. The castle is peopled by dark characters in half-lit corridors. Dreamlike and macabre, Peake''s extraordinary novel is one of the most astonishing and fantastic works in modern fiction.', 496, null, 1946, 309438, (select id from series where hardcover_id = 3177), '1') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('If We Were Villains', 'M.L. Rio', '3328100539', 'https://assets.hardcover.app/book_mappings/7332896/3d6f1c74c62f208ce1605c61bab47389b771bcbd.jpeg', 'On the day Oliver Marks is released from jail, the man who put him there is waiting at the door. Detective Colborne wants to know the truth, and after ten years, Oliver is finally ready to tell it.

A decade ago: Oliver is one of seven young Shakespearean actors at Dellecher Classical Conservatory, a place of keen ambition and fierce competition. In this secluded world of firelight and leather-bound books, Oliver and his friends play the same roles onstage and off: hero, villain, tyrant, temptress, ingénue, extras.

But in their fourth and final year, good-natured rivalries turn ugly, and on opening night real violence invades the students’ world of make-believe. In the morning, the fourth-years find themselves facing their very own tragedy, and their greatest acting challenge yet: convincing the police, each other, and themselves that they are innocent.

If We Were Villains was named one of Bustle''s Best Thriller Novels of the Year, and Mystery Scene says, "A well-written and gripping ode to the stage...A fascinating, unorthodox take on rivalry, friendship, and truth."', 368, null, 2017, 321898, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Phantom Tollbooth', 'Norton Juster, Jules Feiffer', '754425061X', 'https://assets.hardcover.app/edition/30402242/daef9f8c-026a-4daf-9fb1-c3fb8c5cdb4a.jpg', 'For Milo, everything’s a bore. When a tollbooth mysteriously appears in his room, he drives through only because he’s got nothing better to do. But on the other side, things seem different. Milo visits the Island of Conclusions (you get there by jumping), learns about time from a ticking watchdog named Tock, and even embarks on a quest to rescue Rhyme and Reason! Somewhere along the way, Milo realizes something astonishing. Life is far from dull. In fact, it’s exciting beyond his wildest dreams!
--back cover', 268, null, 1961, 327327, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Shadow of the Giant', 'Orson Scott Card', '8490194289', 'https://assets.hardcover.app/edition/20342395/3f95f4b405c8cd6510163547413c25d226d7ea20.jpeg', 'Bean, nearing death, and his wife Petra search for their stolen children with the help of their former Battle School classmates while Peter Wiggin attempts to restore world government with himself as hegemon.', 365, null, 2000, 329688, (select id from series where hardcover_id = 5616), '9') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Legendary', 'Stephanie Garber', '9655840085', 'https://assets.hardcover.app/external_data/35675547/7a6f0456ea1d6d71ba29b80c719741f4e7ad644e.jpeg', 'Donatella and Scarlett Dragna escaped their cruel father and made it out of Caraval alive, but the games aren’t over yet. What Scarlett doesn’t know is that, in order to gain their freedom, Tella made a deal with a mysterious stranger and now it’s time to pay.

Except what Tella owes is something that no one has ever been able to deliver: the true name of Caraval Master Legend. Tella’s only chance at uncovering Legend’s true identity is to enter the dangerous game of Caraval once more, and win. But what will she have to sacrifice to do that?', 416, null, 2018, 330503, (select id from series where hardcover_id = 4886), '2') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Aristotle and Dante Discover the Secrets of the Universe', 'Benjamin Alire Sáenz', '8367815823', 'https://assets.hardcover.app/edition/32059402/e10016c7-9fba-4667-aa2e-ae1dc9faf79e.jpg', 'Aristotle is an angry teen with a brother in prison. Dante is a know-it-all who has an unusual way of looking at the world. When the two meet at the swimming pool, they seem to have nothing in common. But as the loners start spending time together, they discover that they share a special friendship—the kind that changes lives and lasts a lifetime. And it is through this friendship that Ari and Dante will learn the most important truths about themselves and the kind of people they want to be.', 368, null, 2012, 336232, (select id from series where hardcover_id = 1399), '1') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Raven Tower', 'Ann Leckie', '3608122923', 'https://assets.hardcover.app/book/337974/a420a617-1d62-4484-8cba-058b630f39c6.jpg', 'Listen. A god is speaking. My voice echoes through the stone of your master''s castle. The castle where he finds his uncle on his father''s throne. You want to help him. You cannot. You are the only one who can hear me. You will change the world. A triumph of the imagination, The Raven Tower is the first fantasy novel by Ann Leckie, New York Times bestselling author and winner of the Hugo, Nebula, and Arthur C. Clarke Awards. Gods meddle in the fates of men, men play with the fates of gods and a pretender must be cast down from the throne in this breathtaking fantasy masterpiece.', 465, null, 2019, 337974, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Blind Assassin', 'Margaret Atwood', '1860498809', 'https://assets.hardcover.app/edition/2635498/b99432bcaba657ad7e171e1c46eb1f665d9a0509.jpeg', 'The bestselling author of The Handmaid’s Tale and The Testaments weaves together strands of gothic suspense, romance, and science fiction into one utterly spellbinding narrative, beginning with the mysterious death of a young woman named Laura Chase in 1945.

Decades later, Laura’s sister Iris recounts her memories of their childhood, and of the dramatic deaths that have punctuated their wealthy, eccentric family’s history. Intertwined with Iris’s account are chapters from the scandalous novel that made Laura famous, in which two illicit lovers amuse each other by spinning a tale of a blind killer on a distant planet.

These richly layered stories-within-stories gradually illuminate the secrets that have long haunted the Chase family, coming together in a brilliant and astonishing final twist.', 521, null, 2000, 338637, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Around the World in Eighty Days', 'Jules Verne, Henry Frith', '2092703390', 'https://assets.hardcover.app/external_data/61911333/fb0269566478f75747dfda5d2cbd3cdbf86ebbcf.jpeg', 'In 1872 Phileas Fogg wins a bet by traveling around the world in seventy-nine days, twenty-three hours, and fifty-seven minutes.', 297, null, 1872, 338756, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Hobbit & The Lord of the Rings', 'J.R.R. Tolkien, Alan Lee', '3608933204', 'https://assets.hardcover.app/external_data/44171367/13004cc8b3506181bf8c35d11e4124ee2c5a80d5.jpeg', 'Contains:

 - [Hobbit]
 - [The Fellowship of the Ring][1]
 - [The Two Towers][2]
 - [The Return of the King][3]', 1178, null, 1937, 346073, (select id from series where hardcover_id = 127396), '0') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Naked Lunch', 'William S. Burroughs', '8402081762', 'https://assets.hardcover.app/edition/3899749/f105ee75178322d49025760a3a74d153a28b7911.jpeg', 'Controversial and bizarre cult novel based on the author’s own experiences as a drug addict, first published in 1959. Formed as a series of inter-connected adventures set in locations as diverse as the U.S. Mexico and Morocco sees the protagonist, Burroughs’ alter-ego William Lee on the run from the police and always searching for his next fix. Burroughs once stated that the chapters can be read in any order.', 288, null, 1959, 346984, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Reamde', 'Neal Stephenson', '0062106422', 'https://assets.hardcover.app/editions/30451598/5532944589427888.jpg', 'Across the globe, millions of computer screens flicker with the artfully coded world of T''Rain - an addictive internet role-playing game of fantasy and adventure. But backstreet hackers in China have just unleashed a contagious virus called Reamde, and as it rampages through the gaming world spreading from player to player - holding hard drives hostage in the process - the computer of one powerful and dangerous man is infected, causing the carefully mediated violence of the on-line world to spill over into reality. A fast-talking, internet-addicted mafia accountant is brutally silenced by his Russian employers, and Zula - a talented young T''Rain computer programmer - is abducted and bundled on to a private jet. As she is flown across the skies in the company of the terrified boyfriend she broke up with hours before, and a brilliant Hungarian hacker who may be her only hope, she finds herself sucked into a whirl of Chinese Secret Service agents and gun-toting American Survivalists; the Russian criminal underground and an al-Qaeda cell led by a charismatic Welshman; each a strand of a connected world that devastatingly converges in T''Rain. An inimitable and compelling thriller that careers from British Columbia to South-West China via Russia and the fantasy world of T''Rain, Reamde is an irresistible epic from the unique imagination of one of today''s most individual writers.', 1056, null, 2011, 347774, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Cosmos', 'Carl Sagan, Paulo Geiger', '286374075X', 'https://assets.hardcover.app/edition/30405706/2ff2b3f7c52439133219623498812f604d38ca68.jpeg', 'This book is about science in its broadest human context, how science and civilization grew up together. It is the story of our long journey of discovery and the forces and individuals who helped to shape modern science, including Democritus, Hypatia, Kepler, Newton, Huygens, Champollion, Lowell and Humason. The book also explores spacecraft missions of discovery of the nearby planets, the research in the Library of ancient Alexandria, the human brain, Egyptian hieroglyphics, the origin of life, the death of the Sun, the evolution of galaxies and the origins of matter, suns and worlds. The author retraces the fifteen billion years of cosmic evolution that have transformed matter into life and consciousness, enabling the cosmos to wonder about itself. He considers the latest findings on life elsewhere and how we might communicate with the beings of other worlds. ~ WorldCat.org', 450, null, 1980, 349240, (select id from series where hardcover_id = 219692), '1') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('After Dark', 'Haruki Murakami, Jay Rubin', '9734670182', 'https://assets.hardcover.app/editions/1924870/302280743261159.jpg', 'A short, sleek novel of encounters set in the witching hours of Tokyo between midnight and dawn, and every bit as gripping as Haruki Murakami’s masterworks The Wind-Up Bird Chronicle and Kafka on the Shore.

At its center are two sisters: Yuri, a fashion model sleeping her way into oblivion; and Mari, a young student soon led from solitary reading at an anonymous Denny’s into lives radically alien to her own: those of a jazz trombonist who claims they’ve met before; a burly female “love hotel” manager and her maidstaff; and a Chinese prostitute savagely brutalized by a businessman. These “night people” are haunted by secrets and needs that draw them together more powerfully than the differing circumstances that might keep them apart, and it soon becomes clear that Yuri’s slumber–mysteriously tied to the businessman plagued by the mark of his crime – will either restore or annihilate her.

After Dark moves from mesmerizing drama to metaphysical speculation, interweaving time and space as well as memory and perspective into a seamless exploration of human agency – the interplay between self-expression and understanding, between the power of observation and the scope of compassion and love. Murakami’s trademark humor, psychological insight, and grasp of spirit and morality are here distilled with an extraordinary, harmonious mastery.', 191, null, 2004, 354537, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Lamb: The Gospel According to Biff, Christ''s Childhood Pal', 'Christopher Moore', '5864713422', 'https://assets.hardcover.app/edition/22233126/237949-L.jpg', 'The birth of Jesus has been well chronicled, as have his glorious teachings, acts, and divine sacrifice after his thirtieth birthday. But no one knows about the early life of the Son of God, the missing years -- except Biff, the Messiah''s best bud, who has been resurrected to tell the story in the divinely hilarious yet heartfelt work "reminiscent of Vonnegut and Douglas Adams" (Philadelphia Inquirer).Verily, the story Biff has to tell is a miraculous one, filled with remarkable journeys, magic, healings, kung fu, corpse reanimations, demons, and hot babes. Even the considerable wiles and devotion of the Savior''s pal may not be enough to divert Joshua  from his tragic destiny. But there''s no one who loves Josh more -- except maybe "Maggie," Mary of Magdala -- and Biff isn''t about to let his extraordinary pal suffer and ascend without a fight.', 408, null, 2002, 358881, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Cold Days', 'Jim Butcher', '1101617039', 'https://assets.hardcover.app/external_data/59738479/d303b2f29719a6f0647b4dab145e3fc0da38aba1.jpeg', 'After a brief interlude in the afterlife, Harry Dresden’s new job makes him wonder if death was really all that bad. 

Harry Dresden is no longer Chicago’s only professional wizard. Now, he’s Winter Knight to Mab, the Queen of Air and Darkness. Her word is his command. And her first command is the seemingly impossible: kill an immortal. Worse still, there is a growing threat to an unfathomable source of magic that could mean the deaths of millions. Beset by enemies new and old, Harry must gather his friends and allies, prevent an apocalypse, and find a way out of his eternal subservience before his newfound infinite powers claim the only thing he has left to call his own... His soul.', 528, null, 2012, 361447, (select id from series where hardcover_id = 990), '14') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Fountainhead', 'Ayn Rand', '0452273331', 'https://assets.hardcover.app/edition/14870863/e8168a2d424d4123c9d9ae6363d4f0a12a74c596.jpeg', 'The revolutionary literary vision that sowed the seeds of Objectivism, Ayn Rand''s groundbreaking philosophy, and brought her immediate worldwide acclaim.

This modern classic is the story of intransigent young architect Howard Roark, whose integrity was as unyielding as granite...of Dominique Francon, the exquisitely beautiful woman who loved Roark passionately, but married his worst enemy...and of the fanatic denunciation unleashed by an enraged society against a great creator. As fresh today as it was then, Rand’s provocative novel presents one of the most challenging ideas in all of fiction—that man’s ego is the fountainhead of human progress...

“A writer of great power. She has a subtle and ingenious mind and the capacity of writing brilliantly, beautifully, bitterly...This is the only novel of ideas written by an American woman that I can recall.”—The New York Times ', 728, null, 1943, 367940, (select id from series where hardcover_id = 68954), '1') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Aurora', 'Kim Stanley Robinson', '3641177677', 'https://assets.hardcover.app/editions/30400651/1f89c6fd-140a-4784-939d-d8583ac0cabf-aurora.jpg', 'Our voyage from Earth began generations ago. Now, we approach our destination. A new home. Aurora. 

A major new novel from one of science fiction''s most powerful voices, AURORA tells the incredible story of our first voyage beyond the solar system.
', 480, null, 2015, 372879, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Bluest Eye', 'Toni Morrison', '8440647182', 'https://assets.hardcover.app/external_data/42437748/6778e56629eaa4a607d61573f5792ccc0f4671b1.jpeg', '"So that she will be beautiful, so that people will look at her, so that her world will be different. This is the story of the nightmare at the heart of her yearning, and the tragedy of its fulfillment."-- Provided by Amazon', 205, null, 1970, 373323, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Vampire Lestat', 'Anne Rice', '8878182761', 'https://assets.hardcover.app/edition/29787630/1538b18f355d0331ce6c0a76eae2bc2567642441.jpeg', 'The vampire hero of Anne Rice’s enthralling novel is a creature of the darkest and richest imagination. Once an aristocrat in the heady days of pre-revolutionary France, now a rock star in the demonic, shimmering 1980s, he rushes through the centuries in search of others like him, seeking answers to the mystery of his eternal, terrifying existence. His is a mesmerizing story—passionate, complex, and thrilling.', 513, null, 1985, 373748, (select id from series where hardcover_id = 4718), '2') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Godfather', 'Mario Puzo', '158788772X', 'https://assets.hardcover.app/edition/9396774/e96c6707ecc4dd4371457a4af71d72eb255b2d16.jpeg', 'The Godfather is the Mafia leader Vito Corleone, a benevolent despot who stops at nothing to gain and hold power. Set in Long Island, Hollywood and Sicily, this is a story of a feudal society within society which does not hesitate to consolidate its power.', 479, null, 1961, 373776, (select id from series where hardcover_id = 5808), '1') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Accelerando', 'Charles Stross', '1841493899', 'https://assets.hardcover.app/external_data/292818/82e571247936046b6889f7b6aa63f2df35eab452.jpeg', 'The Singularity. It is the era of the posthuman. Artificial intelligences have surpassed the limits of human intellect. Biotechnological beings have rendered people all but extinct. Molecular nanotechnology runs rampant, replicating and reprogramming at will. Contact with extraterrestrial life grows more imminent with each new day.

Struggling to survive and thrive in this accelerated world are three generations of the Macx clan: Manfred, an entrepreneur dealing in intelligence amplification technology whose mind is divided between his physical environment and the Internet; his daughter, Amber, on the run from her domineering mother, seeking her fortune in the outer system as an indentured astronaut; and Sirhan, Amber''s son, who finds his destiny linked to the fate of all of humanity.

For something is systemically dismantling the nine planets of the solar system. Something beyond human comprehension. Something that has no use for biological life in any form.', 415, null, 2005, 374578, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Shadow of the Wind', 'Carlos Ruiz Zafón, Lucia Graves', '8408095595', 'https://assets.hardcover.app/book_mappings/7332507/488f5702a797385ab4e5532825d2e11aebde45da.jpeg', 'Barcelona, 1945: A city slowly heals in the aftermath of the Spanish Civil War, and Daniel, an antiquarian book dealer’s son who mourns the loss of his mother, finds solace in a mysterious book entitled The Shadow of the Wind, by one Julián Carax. But when he sets out to find the author’s other works, he makes a shocking discovery: someone has been systematically destroying every copy of every book Carax has written. In fact, Daniel may have the last of Carax’s books in existence. Soon Daniel’s seemingly innocent quest opens a door into one of Barcelona’s darkest secrets—an epic story of murder, madness, and doomed love.

____
Un amanecer de 1945, un muchacho es conducido por su padre a un misterioso lugar oculto en el corazón de la ciudad vieja: el Cementerio de los Libros Olvidados. Allí, Daniel Sempere encuentra un libro maldito que cambia el rumbo de su vida y le arrastra a un laberinto de intrigas y secretos enterrados en el alma oscura de la ciudad. La Sombra del Viento es un misterio literario ambientado en la Barcelona de la primera mitad del siglo xx, desde los últimos esplendores del Modernismo hasta las tinieblas de la posguerra.

Aunando las técnicas del relato de intriga y suspense, la novela histórica y la comedia de costumbres, La Sombra del Viento es sobre todo una trágica historia de amor cuyo eco se proyecta a través del tiempo. Con gran fuerza narrativa, el autor entrelaza tramas y enigmas a modo de muñecas rusas en un inolvidable relato sobre los secretos del corazón y el embrujo de los libros cuya intriga se mantiene hasta la última página.

Todavía recuerdo aquel amanecer en que mi padre me llevó por primera vez a visitar El Cementerio de los Libros Olvidados.', 487, null, 2001, 375470, (select id from series where hardcover_id = 101029), '1') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Brief Wondrous Life of Oscar Wao', 'Junot Díaz', '0606147810', 'https://assets.hardcover.app/edition/30402348/28cf993080cf5d0e4ab0a120bbe3050168565da6.jpeg', 'Oscar is a sweet but disastrously overweight ghetto nerd who—from the New Jersey home he shares with his old-world mother and rebellious sister—dreams of becoming the Dominican J.R.R. Tolkien and, most of all, finding love. But Oscar may never get what he wants. Blame the fukú—a curse that has haunted Oscar’s family for generations, following them on their epic journey from Santo Domingo to the USA. Encapsulating Dominican-American history, The Brief Wondrous Life of Oscar Wao opens our eyes to an astonishing vision of the contemporary American experience and explores the endless human capacity to persevere—and risk it all—in the name of love.', 339, null, 2007, 375620, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Invisible Library', 'Genevieve Cogman', '807390571X', 'https://assets.hardcover.app/external_data/28471679/a46647fec94bdf9fdf6ba636c35153d2b667f745.jpeg', 'Irene is a professional spy for the mysterious Library, a shadowy organization that collects important works of fiction from all the different realities. Most recently, she and her enigmatic assistant, Kai, have been sent to an alternate London. Their mission: Retrieve a particularly dangerous book. The problem: By the time they arrive, it''s already been stolen.

London''s underground factions are prepared to fight to the death to find the tome before Irene and Kai do, a problem compounded by the fact that this world is chaos infested--the laws of nature bent to allow supernatural creatures and unpredictable magic to run rampant. To make matters worse, Kai is hiding something--secrets that could be just as volatile as the chaos-filled world itself.

Now Irene is caught in a puzzling web of deadly danger, conflicting clues, and sinister secret societies. And failure is not an option--because it isn''t just Irene''s reputation at stake; it''s the nature of reality itself...', 337, null, 2005, 375700, (select id from series where hardcover_id = 1703), '1') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Tommyknockers', 'Stephen King', '0399133143', 'https://assets.hardcover.app/edition/23729165/9536f5e437cc3e7a76c9cfb97c8fa47d77e9c78a.jpeg', 'The Tommyknockers is a 1987 science fiction novel by Stephen King. While maintaining a horror style, the novel is an excursion into the realm of science fiction for King, as the residents of the Maine town of Haven gradually fall under the influence of a mysterious object buried in the woods.


----------
See also:

 - [The Tommyknockers: 1/3](https://openlibrary.org/works/OL8002000W/The_Tommyknockers._1_3)', 979, null, 1987, 376972, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Paradise Lost', 'John Milton, John      Leonard', '9629546671', 'https://assets.hardcover.app/editions/3757554/1919948996411096.jpg', 'It tells the story of the Fall of Man, a tale of immense drama and excitement, of rebellion and treachery, of innocence pitted against corruption, in which God and Satan fight a bitter battle for control of mankind''s destiny. 

The struggle rages across three worlds - heaven, hell, and earth - as Satan and his band of rebel angels plot their revenge against God. At the center of the conflict are Adam and Eve, who are motivated by all too human temptations but whose ultimate downfall is unyielding love.

Marked by Milton''s characteristic erudition, Paradise Lost is a work epic both in scale and, notoriously, in ambition. For nearly 350 years, it has held generation upon generation of audiences in rapt attention, and its profound influence can be seen in almost every corner of Western culture.', 512, null, 1667, 377089, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Yiddish Policemen''s Union', 'Michael Chabon', '0062640860', 'https://assets.hardcover.app/edition/16675217/c2b0345bf230a58555c5342ff425efc54cd5d7af.jpeg', 'For sixty years Jewish refugees and their descendants have prospered in the Federal District of Sitka, a "temporary" safe haven created in the wake of the Holocaust and the shocking 1948 collapse of the fledgling state of Israel. The Jews of the Sitka District have created their own little world in the Alaskan panhandle, a vibrant and complex frontier city that moves to the music of Yiddish. But now the District is set to revert to Alaskan control, and their dream is coming to an end.

Homicide detective Meyer Landsman of the District Police has enough problems without worrying about the upcoming Reversion. His life is a shambles, his marriage a wreck, his career a disaster. And in the cheap hotel where Landsman has washed up, someone has just committed a murder—right under his nose. When he begins to investigate the killing of his neighbor, a former chess prodigy, word comes down from on high that the case is to be dropped immediately, and Landsman finds himself contending with all the powerful forces of faith, obsession, evil, and salvation that are his heritage.

At once a gripping whodunit, a love story, and an exploration of the mysteries of exile and redemption, The Yiddish Policemen''s Union is a novel only Michael Chabon could have written.', 414, null, 2006, 377099, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Ilium', 'Dan Simmons', '8417347356', 'https://assets.hardcover.app/editions/3655318/233436944657315-3973.jpg', 'From the author of the Hyperion Cantos -- one of the most acclaimed popular series in contemporary science fiction -- comes a powerful epic of high-tech gods, human heroes, total war, and the extraordinary transcendence of ordinary beings. The first book in a two-part epic. "I am in awe of Dan Simmons." -- Stephen King. From the towering heights of Olympos Mons on Mars, the mighty Zeus and his immortal family of gods, goddesses, and demigods look down upon a momentous battle, observing -- and often influencing -- the legendary exploits of Paris, Achilles, Hector, Odysseus, and the clashing armies of Greece and Troy. Thomas Hockenberry, former twenty-first-century professor and Iliad scholar, watches as well. It is Hockenberry''s duty to observe and report on the Trojan War''s progress to the so-called deities who saw fit to return him from the dead. But the muse he serves has a new assignment for the wary scholic, one dictated by Aphrodite herself. With the help of fortieth-century technology, Hockenberry is to infiltrate Olympos, spy on its divine inhabitants ... and ultimately destroy Aphrodite''s sister and rival, the goddess Pallas Athena. On an Earth profoundly changed since the departure of the Post-Humans centuries earlier, the great events on the bloody plains of Ilium serve as mere entertainment. Its scenes of unrivaled heroics and unequaled carnage add excitement to human lives devoid of courage, strife, labor, and purpose. But this eloi-like existence is not enough for Harman, a man in the last year of his last Twenty. That rarest of post-postmodern men -- an "adventurer" -- he intends to explore far beyond the boundaries of his world before his allotted time expires, in search of a lost past, a devastating truth, and an escape from his own inevitable "final fax." Meanwhile, from the radiation-swept reaches of Jovian space, four sentient machines race to investigate -- and, perhaps, terminate -- the potentially catastrophic emissions of unexplained quantum-flux emanating from a mountaintop miles above the terraformed surface of Mars ... The first book in a remarkable two-part epic to be concluded in the upcoming Olympos, Dan Simmons''s Ilium is a breathtaking adventure, enormous in scope and imagination, sweeping across time and space to connect three seemingly disparate stories in fresh, thrilling, and totally unexpected ways. A truly masterful work of speculative fiction, it is quite possibly Simmons''s finest achievement to date in an already storied literary career.', 752, null, 2003, 377360, (select id from series where hardcover_id = 994), '1') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Gentleman''s Guide to Vice and Virtue', 'Mackenzi Lee, Christian Coulson', '1538439131', 'https://assets.hardcover.app/book_mappings/7333121/7f5c13bff3752434507524971d8b1bc41517b43d.jpeg', 'Henry "Monty" Montague was born and bred to be a gentleman, but he was never one to be tamed. The finest boarding schools in England and the constant disapproval of his father haven''t been able to curb any of his roguish passions--not for gambling halls, late nights spent with a bottle of spirits, or waking up in the arms of women or men.

But as Monty embarks on his Grand Tour of Europe, his quest for a life filled with pleasure and vice is in danger of coming to an end. Not only does his father expect him to take over the family''s estate upon his return, but Monty is also nursing an impossible crush on his best friend and traveling companion, Percy.

Still, it isn''t in Monty''s nature to give up. Even with his younger sister, Felicity, in tow, he vows to make this yearlong escapade one last hedonistic hurrah and flirt with Percy from Paris to Rome. But when one of Monty''s reckless decisions turns their trip abroad into a harrowing manhunt that spans across Europe, it calls into question everything he knows, including his relationship with the boy he adores.

This description comes from the publisher.', null, null, 2017, 377475, (select id from series where hardcover_id = 1797), '1') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Digital Fortress', 'Dan Brown', '1593973594', 'https://assets.hardcover.app/edition/22081967/89d70876-40e2-4826-9095-d5568746f4b5.jpg', 'When the NSA''s invincible code-breaking machine encounters a mysterious code it cannot break, the agency calls its head cryptographer, Susan Fletcher, a brilliant and beautiful mathematician. What she uncovers sends shock waves through the corridors of power. The NSA is being held hostage...not by guns or bombs, but by a code so ingeniously complex that if released it would cripple U.S. intelligence.

Caught in an accelerating tempest of secrecy and lies, Susan Fletcher battles to save the agency she believes in. Betrayed on all sides, she finds herself fighting not only for her country but for her life, and in the end, for the life of the man she loves.

From the underground hallways of power to the skyscrapers of Tokyo to the towering cathedrals of Spain, a desperate race unfolds. It is a battle for survival--a crucial bid to destroy a creation of inconceivable genius...an impregnable code-writing formula that threatens to obliterate the post-cold war balance of power. Forever.', 384, null, 1998, 379753, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Tenth of December', 'George Saunders', '152660714X', 'https://assets.hardcover.app/external_data/2775176/5c502197cfb55db38d8e810e272de014ac6b7b21.jpeg', 'One of the most important and blazingly original writers of his generation, George Saunders is an undisputed master of the short story, and Tenth of December is his most honest, accessible, and moving collection yet.
 
In the taut opener, “Victory Lap,” a boy witnesses the attempted abduction of the girl next door and is faced with a harrowing choice: Does he ignore what he sees, or override years of smothering advice from his parents and act? In “Home,” a combat-damaged soldier moves back in with his mother and struggles to reconcile the world he left with the one to which he has returned. And in the title story, a stunning meditation on imagination, memory, and loss, a middle-aged cancer patient walks into the woods to commit suicide, only to encounter a troubled young boy who, over the course of a fateful morning, gives the dying man a final chance to recall who he really is. A hapless, deluded owner of an antiques store; two mothers struggling to do the right thing; a teenage girl whose idealism is challenged by a brutal brush with reality; a man tormented by a series of pharmaceutical experiments that force him to lust, to love, to kill—the unforgettable characters that populate the pages of Tenth of December are vividly and lovingly infused with Saunders’s signature blend of exuberant prose, deep humanity, and stylistic innovation.
 
Writing brilliantly and profoundly about class, sex, love, loss, work, despair, and war, Saunders cuts to the core of the contemporary experience. These stories take on the big questions and explore the fault lines of our own morality, delving into the questions of what makes us good and what makes us human.
 
Unsettling, insightful, and hilarious, the stories in Tenth of December—through their manic energy, their focus on what is redeemable in human beings, and their generosity of spirit—not only entertain and delight; they fulfill Chekhov’s dictum that art should “prepare us for tenderness.”', null, null, 2012, 380493, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Congo', 'Michael Crichton', '0613100557', 'https://assets.hardcover.app/external_data/38927365/fb6d189c319436680385a03d8013bf9cdf4216c0.jpeg', 'Deep in the African rain forest, near the legendary ruins of the Lost City of Zinj, an expedition of eight American geologists is mysteriously and brutally killed in a matter of minutes.

Ten thousand miles away, Karen Ross, the Congo Project Supervisor, watches a gruesome video transmission of the aftermath: a camp destroyed, tents crushed and torn, equipment scattered in the mud alongside dead bodies — all motionless except for one moving image — a grainy, dark, man-shaped blur.

In San Francisco, primatologist Peter Elliot works with Amy, a gorilla with an extraordinary vocabulary of 620 “signs,” the most ever learned by a primate, and she likes to fingerpaint. But recently, her behavior has been erratic and her drawings match, with stunning accuracy, the brittle pages of a Portuguese print dating back to 1642 . . . a drawing of an ancient lost city. A new expedition — along with Amy — is sent into the Congo where they enter a secret world, and the only way out may be through a horrifying death …', 466, null, 1980, 380571, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Wasp Factory', 'Iain Banks', '859454006X', 'https://assets.hardcover.app/edition/6503291/48b7933e8c6010722a63c9d9444f01a234bb4e27.jpeg', 'Frank, no ordinary sixteen-year-old, lives with his father outsIde a remote Scottish village. Their life is, to say the least, unconventional. Frank''s mother abandoned them years ago: his elder brother Eric is confined to a psychiatric hospital; and his father measures out his eccentricities on an imperial scale. Frank has turned to strange acts of violence to vent his frustrations. In the bizarre daily rituals there is some solace. But when news comes of Eric''s escape from the hospital Frank has to prepare the ground for his brother''s inevitable return - an event that explodes the mysteries of the past and changes Frank utterly. Iain Banks'' celebrated first novel is a work of extraordinary originality, imagination and horrifying compulsion: horrifying, because it enters a mind whose realities are not our own, whose values of life and death are alien to our society; and compulsive, because the humour and compassion of that mind reach out to us all.', 244, null, 1984, 380645, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Dreamcatcher', 'Stephen King', '3453437330', 'https://assets.hardcover.app/edition/31519073/e9ac858f660cfd0782b5da026988dfc686f9f897.jpeg', 'Dreamcatcher is a 2001 science fiction horror novel by American writer Stephen King, featuring elements of body horror, suspense and alien invasion.', 694, null, 2001, 381512, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Woken Furies', 'Richard K. Morgan', '1615458212', 'https://assets.hardcover.app/external_data/4235196/f7097817cb30fe84a09a232c5a2b73787482dc9a.jpeg', 'Richard K. Morgan has received widespread praise for his astounding twenty-fifth-century novels featuring Takeshi Kovacs, and has established a growing legion of fans. Mixing classic noir sensibilities with a searing futuristic vision of an age when death is nearly meaningless, Morgan returns to his saga of betrayal, mystery, and revenge, as Takeshi Kovacs, in one fatal moment, joins forces with a mysterious woman who may have the power to shatter Harlan''s World forever.Once a gang member, then a marine, then a galaxy-hopping Envoy trained to wreak slaughter and suppression across the stars, a bleeding, wounded Kovacs was chilling out in a New Hokkaido bar when some so-called holy men descended on a slim beauty with tangled, hyperwired hair. An act of quixotic chivalry later and Kovacs was in deep: mixed up with a woman with two names, many powers, and one explosive history.In a world where the real and virtual are one and the same and the dead can come back to life, the damsel in distress may be none other than the infamous Quellcrist Falconer, the vaporized symbol of a freedom now gone from Harlan''s World. Kovacs can deal with the madness of AI. He can do his part in a battle against biomachines gone wild, search for a three-centuries-old missing weapons system, and live with a blood feud with the yakuza, and even with the betrayal of people he once trusted. But when his relationship with "the" Falconer brings him an enemy specially designed to destroy him, he knows it''s time to be afraid. After all, the guy sent to kill him is himself: but younger, stronger, and straight out of hell.Wild, provocative, and riveting, Woken Furies is a full-bore science fiction spectacular of the highest order--from one of the most original and spellbinding storytellers at work today.From the Hardcover edition.', 667, null, 2005, 381729, (select id from series where hardcover_id = 5569), '3') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Quicksilver', 'Neal Stephenson', '7770940559', 'https://assets.hardcover.app/edition/30402693/76f2c82d4db56619e654ca66b5128dc65608da95.jpeg', 'Quicksilver is the story of Daniel Waterhouse, fearless thinker and conflicted Puritan, pursuing knowledge in the company of the greatest minds of Baroque-era Europe, in a chaotic world where reason wars with the bloody ambitions of the mighty, and where catastrophe, natural or otherwise, can alter the political landscape overnight.

It is a chronicle of the breathtaking exploits of "Half-Cocked Jack" Shaftoe--London street urchin turned swashbuckling adventurer and legendary King of the Vagabonds--risking life and limb for fortune and love while slowly maddening from the pox.

And it is the tale of Eliza, rescued by Jack from a Turkish harem to become spy, confidante, and pawn of royals in order to reinvent Europe through the newborn power of finance.

A gloriously rich, entertaining, and endlessly inventive novel that brings a remarkable age and its momentous events to vivid life, Quicksilver is an extraordinary achievement from one of the most original and important literary talents of our time.

And it''s just the beginning...

(back cover)', 917, null, 2003, 382132, (select id from series where hardcover_id = 6918), '1') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Lost Colony', 'Eoin Colfer', '0545007992', 'https://assets.hardcover.app/edition/6858211/9fc72f0f-8105-4b6c-a523-487cd7149482.jpg', 'Thousands of years ago, fairies and humans fought a great battle for the magical island of Ireland.  When it became clear that they could not win, all of the fairies moved belowground -- except for the 8th Family, the demons.  Rather than surrender, they used a magical time spell to take their colony out of time and into Limbo.  There they have lived for decades, preparing to exact their violent revenge onto humans. 

Now the time spell is unraveling, and demons are beginning to materialize without warning on Earth.  If humans were to find out about them, all fairies would be exposed.  To protect themselves, the fairies must predict when the next demon will materialize.  But in order to do so, they will have to decipher temporal equations so complicated, even a great brain like Foaly can''t understand them. But he knows someone who can: Artemis Fowl.

So when a very confused demon imp appears in a Sicilian theater, Artemis is there to meet him.  But he is not alone.  There is someone else who has unlocked the secrets of the fairy world and managed to solve the complex mathematical problems as only a genius could.  And she is just twelve years old...', 385, null, 2001, 382832, (select id from series where hardcover_id = 1374), '5') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Long Dark Tea-Time of the Soul', 'Douglas Adams', '1529084717', 'https://assets.hardcover.app/edition/30767243/a36a1a0f2299a418c6c8922a55b15b933ffa79a1.jpeg', 'When a passenger check-in desk at Terminal Two, Heathrow Airport, shot up through the roof engulfed in a ball of orange flame, the usual people tried to claim responsibility. First the IRA, then the PLO and the Gas Board. Even British Nuclear Fuels rushed out a statement to the effect that the situation was completely under control, that it was a one in a million chance, that there was hardly any radioactive leakage at all and that the site of the explosion would make a nice location for a day out with the kids and a picnic, before finally having to admit that it wasn''t actually anything to do with them at all.

No rational cause could be found for the explosion – it was simply designated an act of God. But, thinks Dirk Gently, which God? And why? What God would be hanging around Terminal Two of Heathrow Airport trying to catch the 15:37 to Oslo?', 288, null, 1988, 383324, (select id from series where hardcover_id = 2795), '2') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Wonder', 'R. J. Palacio', '8496735745', 'https://assets.hardcover.app/edition/13191538/06ce4dae00f9ab1c5799cd4199a1fbd42af87eed.jpeg', 'August Pullman was born with a facial difference that, up until now, has prevented him from going to a mainstream school. Starting 5th grade at Beecher Prep, he wants nothing more than to be treated as an ordinary kid—but his new classmates can’t get past Auggie’s extraordinary face. Beginning from Auggie’s point of view and expanding to include his classmates, his sister, her boyfriend, and others, the perspectives converge to form a portrait of one community’s struggle with empathy, compassion, and acceptance. In a world where bullying among young people is an epidemic, this is a refreshing new narrative full of heart and hope.', 315, null, 2012, 384730, (select id from series where hardcover_id = 1462), '1') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Unseen Academicals', 'Terry Pratchett', '0552153370', 'https://assets.hardcover.app/edition/31519394/f701a2bff20002afc762c53a43414f29bf96b6b6.jpeg', 'The wizards at Ankh-Morpork''s Unseen University are renowned for many things--wisdom, magic, teatime--but athletics, not so much. When Lord Vetinari, the city''s benevolent tyrant, strongly suggests to Archchancellor Mustrum Ridcully that the university revive its sports program and field a football team composed of faculty, students, and staff--or lose the funding that pays for their nine daily meals--the wizards of UU find themselves in a quandary. First, they have to understand what makes foot-the-ball so popular with Ankh-Morporkians. Then they have to learn how to play it--and win--without using magic.

Of course, the thing about football is that it is never just about football.', 544, null, 2009, 384969, (select id from series where hardcover_id = 1018), '37') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Historian', 'Elizabeth Kostova, Justine Eyre, Paul Michael', '0316070637', 'https://assets.hardcover.app/external_data/60874881/d699769c224896cc1914ed4bd1062c0e5caf7e14.jpeg', 'To you, perceptive reader, I bequeath my history....Late one night, exploring her father''s library, a young woman finds an ancient book and a cache of yellowing letters. The letters are all addressed to "My dear and unfortunate successor," and they plunge her into a world she never dreamed of-a labyrinth where the secrets of her father''s past and her mother''s mysterious fate connect to an inconceivable evil hidden in the depths of history.

The letters provide links to one of the darkest powers that humanity has ever known-and to a centuries-long quest to find the source of that darkness and wipe it out. It is a quest for the truth about Vlad the Impaler, the medieval ruler whose barbarous reign formed the basis of the legend of Dracula. Generations of historians have risked their reputations, their sanity, and even their lives to learn the truth about Vlad the Impaler and Dracula. Now one young woman must decide whether to take up this quest herself-to follow her father in a hunt that nearly brought him to ruin years ago, when he was a vibrant young scholar and her mother was still alive. What does the legend of Vlad the Impaler have to do with the modern world? Is it possible that the Dracula of myth truly existed-and that he has lived on, century after century, pursuing his own unknowable ends?

The answers to these questions cross time and borders, as first the father and then the daughter search for clues, from dusty Ivy League libraries to Istanbul, Budapest, and the depths of Eastern Europe. In city after city, in monasteries and archives, in letters and in secret conversations, the horrible truth emerges about Vlad the Impaler''s dark reign-and about a time-defying pact that may have kept his awful work alive down through the ages.Parsing obscure signs and hidden texts, reading codes worked into the fabric of medieval monastic traditions-and evading the unknown adversaries who will go to any lengths to conceal and protect Vlad''s ancient powers—one woman comes ever closer to the secret of her own past and a confrontation with the very definition of evil.

Elizabeth Kostova''s debut novel is an adventure of monumental proportions, a relentless tale that blends fact and fantasy, history and the present, with an assurance that is almost unbearably suspenseful—and utterly unforgettable.', null, null, 2005, 385010, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Year of the Flood', 'Margaret Atwood', '3827070260', 'https://assets.hardcover.app/editions/23949400/32dae847-7274-4edd-9c0a-b6fa465d0baf.jpg', 'The times and species have been changing at a rapid rate, and the social compact is wearing as thin as environmental stability. Adam One, the kindly leader of the God''s Gardeners-a religion devoted to the melding of science and religion, as well as the preservation of all plant and animal life-has long predicted a natural disaster that will alter Earth as we know it. Now it has occurred, obliterating most human life. Two women have survived:  Ren, a young trapeze dancer locked inside the high-end sex club Scales and Tails, and Toby, a God''s Gardener barricaded inside a luxurious spa where many of the treatments are edible. Have others survived? Ren''s bioartist friend Amanda? Zeb, her eco-fighter stepfather? Her onetime lover, Jimmy? Or the murderous Painballers, survivors of the mutual-elimination Painball prison? Not to mention the shadowy, corrupt policing force of the ruling powers. Meanwhile, gene-spliced life forms are proliferating:  the lion/lamb blends, the Mo''hair sheep with human hair, the pigs with human brain tissue. As Adam One and his intrepid hemp-clad band make their way through this strange new world, Ren and Toby will have to decide on their next move, but they can''t stay locked away. By turns dark, tender, violent, thoughtful, and uneasily hilarious, The Year of the Flood is Atwood at her most brilliant and inventive.', 434, null, 2009, 385012, (select id from series where hardcover_id = 1851), '2') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('A Dirty Job', 'Christopher Moore', '3442542251', 'https://assets.hardcover.app/edition/25874947/73e1b5ef643934352567d5f9dbea93130d51611d.jpeg', 'Charlie Asher is a pretty normal guy. A little hapless, somewhat neurotic, sort of a hypochondriac. He''s what''s known as a Beta Male: the kind of fellow who makes his way through life by being careful and constant -- you know, the one who''s always there to pick up the pieces when the girl gets dumped by the bigger/taller/stronger Alpha Male.But Charlie''s been lucky. He owns a building in the heart of San Francisco, and runs a secondhand store with the help of a couple of loyal, if marginally insane, employees. He''s married to a bright and pretty woman who actually loves him for his normalcy. And she, Rachel, is about to have their first child.Yes, Charlie''s doing okay for a Beta. That is, until the day his daughter, Sophie, is born. Just as Charlie -- exhausted from the birth -- turns to go home, he sees a strange man in mint-green golf wear at Rachel''s hospital bedside, a man who claims that no one should be able to see him. But see him Charlie does, and from here on out, things get really weird. . . .People start dropping dead around him, giant ravens perch on his building, and it seems that everywhere he goes, a dark presence whispers to him from under the streets. Strange names start appearing on his nightstand notepad, and before he knows it, those people end up dead, too. Yup, it seems that Charlie Asher has been recruited for a new job, an unpleasant but utterly necessary one: Death. It''s a dirty job. But hey, somebody''s gotta do it.Christopher Moore, the man whose Lamb served up Jesus'' "missing years" (with the funny parts left in), and whose Fluke found the deep humor in whale researchers'' lives, now shines his comic light on the undiscovered country we all eventually explore -- death and dying -- and the results are hilarious, heartwarming, and a hell of a lot of fun.', 404, null, 2006, 385824, (select id from series where hardcover_id = 5830), '1') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Golden Fool', 'Robin Hobb', '0007160380', 'https://assets.hardcover.app/external_data/1285139/61b7710f75cb2c1cf14f888b9cd303d38d48b3ff.jpeg', 'This is the second in a new fantasy series from Robin Hobb, author of the bestselling Assassin trilogy. Fitz has succeeded in rescuing Prince Dutiful from the clutches of the Piebals rebels, and has returned with him to Buckkeep castle.', 632, null, 1982, 386715, (select id from series where hardcover_id = 6035), '2') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Elric of Melniboné and Other Stories', 'Michael Moorcock, Alan Moore', '0809562731', 'https://assets.hardcover.app/edition/30471163/e488cc028ade4407eae71fecba0a6373dad5155c.jpeg', '**Elric of Melniboné** is a 1972 fantasy novel by **Michael Moorcock**. It is the first original full-length novel to feature **Elric**, the last emperor of the stagnating island civilisation of Melniboné who wields the cursed, soul-drinking sword **Stormbringer**.', 384, null, 1972, 427343, (select id from series where hardcover_id = 1045), '1') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Shadow Puppets', 'Orson Scott Card', '141761806X', 'https://assets.hardcover.app/edition/17379372/c54f16508055dec3cac1a7b672522b25133fc120.jpeg', 'Bestselling author Orson Scott Card brings to life a new chapter in the saga of Ender''s Earth and The Shadow Series.

Earth and its society have been changed irrevocably in the aftermath of Ender Wiggin''s victory over the Formics. The unity forced upon the warring nations by an alien enemy has shattered. Nations are rising again, seeking territory and influence, and most of all, seeking to control the skills and loyalty of the children from the Battle School.

But one person has a better idea. Peter Wiggin, Ender''s older, more ruthless, brother, sees that any hope for the future of Earth lies in restoring a sense of unity and purpose. And he has an irresistible call on the loyalty of Earth''s young warriors. With Bean at his side, the two will reshape our future.

Shadow Puppets is the continuing story of Bean and Petra, and the rest of Ender''s Dragon Army, as they take their places in the new government of Earth.', 375, null, 2002, 427351, (select id from series where hardcover_id = 1051), '3') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Shards of Honour', 'Lois McMaster Bujold', '9731248382', 'https://assets.hardcover.app/edition/28243049/25575ae460b6b44fa2a4ee97d44683cc8cf5b3aa.jpeg', 'Relive the adventures of Miles and Mark in the first of The Vorkosigan Series. "Bujold has created two of the most engaging, interesting, complicated protagonists in science fiction . . . readers will enjoy this book". VOYA.', 253, null, 1986, 427370, (select id from series where hardcover_id = 5834), '1') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Kushiel''s Dart', 'Jacqueline Carey', '0312872380', 'https://assets.hardcover.app/edition/30559787/aa29447b-4978-47ef-be86-cdba563a00e2.jpg', 'The first book in the Kushiel''s Legacy series is a novel of grandeur, luxuriance, sacrifice, betrayal, and deeply laid conspiracies. A world of cunning poets, deadly courtiers, deposed rulers and a besieged Queen, a warrior-priest, the Prince of Travelers, barbarian warlords, heroic traitors, and a truly Machiavellian villainess...all seen through the unflinching eyes of an unforgettable heroine.

A nation born of angels, vast and intricate and surrounded by danger... a woman born to servitude, unknowingly given access to the secrets of the realm...

Born with a scarlet mote in her left eye, Phédre nó Delaunay is sold into indentured servitude as a child. When her bond is purchased by an enigmatic nobleman, she is trained in history, theology, politics, foreign languages, the arts of pleasure. And above all, the ability to observe, remember, and analyze. Exquisite courtesan, talented spy...and unlikely heroine. But when Phédre stumbles upon a plot that threatens her homeland, Terre d''Ange, she has no choice.

Betrayed into captivity in the barbarous northland of Skaldia and accompanied only by a disdainful young warrior-priest, Phédre makes a harrowing escape and an even more harrowing journey to return to her people and deliver a warning of the impending invasion. And that proves only the first step in a quest that will take her to the edge of despair and beyond.

Phédre nó Delaunay is the woman who holds the keys to her realm''s deadly secrets, and whose courage will decide the very future of her world.', 704, null, 2001, 427397, (select id from series where hardcover_id = 175895), '1') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Galápagos', 'Kurt Vonnegut', '951306994X', 'https://assets.hardcover.app/external_data/4234250/f2969e809887b9ce232512a44abfb8fd7832a156.jpeg', '“A madcap genealogical adventure . . . Vonnegut is a postmodern Mark Twain.”—The New York Times Book Review Galápagos takes the reader back one million years, to A.D. 1986. A simple vacation cruise suddenly becomes an evolutionary journey. Thanks to an apocalypse, a small group of survivors stranded on the Galápagos Islands are about to become the progenitors of a brave, new, and totally different human race. In this inimitable novel, America’ s master satirist looks at our world and shows us all that is sadly, madly awry–and all that is worth saving. Praise for Galápagos “The best Vonnegut novel yet!”—John Irving “Beautiful . . . provocative, arresting reading.”—USA Today “A satire in the classic tradition . . . a dark vision, a heartfelt warning.”—The Detroit Free Press “Interesting, engaging, sad and yet very funny . . . Vonnegut is still in top form. If he has no prescription for alleviating the pain of the human condition, at least he is a first-rate diagnostician.”—Susan Isaacs, Newsday “Dark . . . original and funny.”—People “A triumph of style, originality and warped yet consistent logic . . . a condensation, an evolution of Vonnegut’s entire career, including all the issues and questions he has pursued relentlessly for four decades.”—The Philadelphia Inquirer “Wild details, wry humor, outrageous characters . . . Galápagos is a comic lament, a sadly ironic vison.”—St. Louis Post-Dispatch “A work of high comedy, sadness and imagination.”—The Denver Post “Wacky wit and irreverent imagination . . . and the full range of technical innovations have made [Vonnegut] America’s preeminent experimental novelist.”—The Minneapolis Star and Tribune', 338, null, 1985, 427410, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Rise and Fall of D.O.D.O.', 'Neal Stephenson, Nicole Galland', '0008132577', 'https://assets.hardcover.app/edition/4566001/125035a7b3b2e0c5819c52a96a16546f6b85b619.jpeg', 'From bestselling author Neal Stephenson and critically acclaimed historical and contemporary commercial novelist Nicole Galland comes a captivating and complex near-future thriller combining history, science, magic, mystery, intrigue, and adventure that questions the very foundations of the modern world.

When Melisande Stokes, an expert in linguistics and languages, accidently meets military intelligence operator Tristan Lyons in a hallway at Harvard University, it is the beginning of a chain of events that will alter their lives and human history itself. The young man from a shadowy government entity approaches Mel, a low-level faculty member, with an incredible offer. The only condition: she must sign a nondisclosure agreement in return for the rather large sum of money.

Tristan needs Mel to translate some very old documents, which, if authentic, are earth-shattering. They prove that magic actually existed and was practiced for centuries. But the arrival of the scientific revolution and the Age of Enlightenment weakened its power and endangered its practitioners. Magic stopped working altogether in 1851, at the time of the Great Exhibition at London’s Crystal Palace—the world’s fair celebrating the rise of industrial technology and commerce. Something about the modern world "jams" the "frequencies" used by magic, and it’s up to Tristan to find out why.

And so the Department of Diachronic Operations—D.O.D.O. —gets cracking on its real mission: to develop a device that can bring magic back, and send Diachronic Operatives back in time to keep it alive . . . and meddle with a little history at the same time. But while Tristan and his expanding operation master the science and build the technology, they overlook the mercurial—and treacherous—nature of the human heart.

Written with the genius, complexity, and innovation that characterize all of Neal Stephenson’s work and steeped with the down-to-earth warmth and humor of Nicole Galland’s storytelling style, this exciting and vividly realized work of science fiction will make you believe in the impossible, and take you to places—and times—beyond imagining.', 768, null, 2017, 427434, (select id from series where hardcover_id = 1104), '1') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Six Wakes', 'Mur Lafferty', '6049769753', 'https://assets.hardcover.app/edition/30405432/0aaa71df-a343-4e14-8b4f-271e292351ed.jpg', 'In this Hugo nominated science fiction thriller by Mur Lafferty, a crew of clones awakens aboard a space ship to find they''re being hunted-and any one of them could be the killer.

Maria Arena awakens in a cloning vat streaked with drying blood. She has no memory of how she died. This is new; before, when she had awakened as a new clone, her first memory was of how she died.

Maria''s vat is one of seven, each one holding the clone of a crew member of the starship Dormire, each clone waiting for its previous incarnation to die so it can awaken. And Maria isn''t the only one to die recently. . .

Unlock the bold new science fiction thriller that Corey Doctorow calls Mur''s "breakout book".', 400, null, 2017, 427471, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Mitosis: A Reckoners Story', 'Brandon Sanderson', '1409156680', 'https://assets.hardcover.app/edition/21718124/65f38218-0535-4a10-8941-52e388c567e5.jpg', 'Read the e-novella from the #1 New York Times bestselling Recokners series: Steelheart, Firefight, and Calamity! Brandon Sanderson, the #1 New York Times bestselling author of Words of Radiance, coauthor of Robert Jordan’s The Wheel of Time series, and creator of the internationally bestselling Mistborn trilogy, presents Mitosis, a short story set in the action-packed world of Steelheart, Firefight, and Calamity: the Reckoners series, exclusively available in the digital format. Epics still plague Newcago, but David and the Reckoners have vowed to fight back. Praise for the Reckoners Series: #1 New York Times Bestselling Series “Another win for Sanderson . . . he’s simply a brilliant writer. Period.” —Patrick Rothfuss, author of the New York Times and USA Today bestseller The Name of the Wind “Action-packed.” —EW.com “Compelling. . . . Sanderson uses plot twists that he teases enough for readers to pick up on to distract from the more dramatic reveals he has in store.” —The A.V. Club', 15, null, 2013, 427474, (select id from series where hardcover_id = 1038), '1.5') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Trigger Warning: Short Fictions and Disturbances', 'Neil Gaiman', '8804661763', 'https://assets.hardcover.app/edition/29740863/de3318e0ad127cfc8fb9317d67f8890b51257c2b.jpeg', 'From one of the most critically acclaimed and beloved storytellers of our time comes a major new collection of stories and verse "We each have our little triggers . . . things that wait for us in the dark corridors of our lives." So says Neil Gaiman in his introduction to Trigger Warning, a remarkable compendium of twenty-five stories and poems that explore the transformative power of imagination. In "Adventure Story"—a thematic companion to the #1 New York Times bestselling novel The Ocean at the End of the Lane—Gaiman ponders death and the ways in which people take their stories with them when they die. "A Calendar of Tales" is comprised of short pieces about the months of the year—stories of pirates and March winds, an igloo made of books, and a Mother''s Day card that portends disturbances in the universe. Gaiman offers his own ingenious spin on Sherlock Holmes in his award-nominated mystery tale "The Case of Death and Honey." Also included is "Nothing O''Clock," a very special Doctor Who story that was written for the beloved series in 2013, as well as the never-before-published "Black Dog," a haunting new tale that revisits the world of American Gods as Shadow Moon stops in at a village pub on his way back to America. Gaiman, a sophisticated writer whose creative genius is unparalleled, entrances with his literary alchemy and transports us deep into an undiscovered country where the fantastical becomes real and the everyday is incandescent. Replete with wonder and terror, surprises and amusements, Trigger Warning is a treasury of literary delights that engage the mind, stir the heart, and shake the soul.', 352, null, 2001, 427488, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Fold', 'Peter Clines, Ray Porter', '0553418297', 'https://assets.hardcover.app/external_data/59618966/47cfe3e06b5f74d959421e45d56bf553c5580447.jpeg', 'The folks in Mike Erikson’s small New England town would say he’s just your average, everyday guy. And that’s exactly how Mike likes it. Sure, the life he’s chosen isn’t much of a challenge to someone with his unique gifts, but he’s content with his quiet and peaceful existence.

That is, until an old friend presents him with an irresistible mystery, one that Mike is uniquely qualified to solve: far out in the California desert, a team of DARPA scientists has invented a device they affectionately call the Albuquerque Door. Using a cryptic computer equation and magnetic fields to “fold” dimensions, it shrinks distances so that a traveler can travel hundreds of feet with a single step.

The invention promises to make mankind’s dreams of teleportation a reality. And, the scientists insist, traveling through the Door is completely safe. Yet evidence is mounting that this miraculous machine isn’t quite what it seems—and that its creators are harboring a dangerous secret. As his investigations draw him deeper into the puzzle, Mike begins to fear there’s only one answer that makes sense. And if he’s right, it may only be a matter of time before the project destroys…everything.

A cunningly inventive mystery featuring a hero worthy of Sherlock Holmes and a terrifying final twist you’ll never see coming, The Fold is that rarest of things: a genuinely page-turning science-fiction thriller.', null, null, 1999, 427496, (select id from series where hardcover_id = 1058), '2') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Only Human', 'Sylvain Neuvel', '8328708981', 'https://assets.hardcover.app/edition/30404007/8a13daea-3483-4962-8cd2-289d0e21adcf.jpg', 'Brilliant scientist Rose Franklin has devoted her adult life to solving the mystery she accidentally stumbled upon as a child: a huge metal hand buried beneath the ground outside Deadwood, South Dakota. The discovery set in motion a cataclysmic chain of events with geopolitical ramifications. Rose and the Earth Defense Corps raced to master the enigmatic technology, as giant robots suddenly descended on Earth’s most populous cities, killing one hundred million people in the process. Though Rose and her team were able to fend off the attack, their victory was short-lived. The mysterious invaders retreated, disappearing from the shattered planet . . . but they took the scientist and her crew with them.
 
Now, after nearly ten years on another world, Rose returns to find a devastating new war—this time between humans. America and Russia are locked in combat, fighting to fill the power vacuum left behind after the invasion. Families are torn apart, friends become bitter enemies, and countries collapse in the wake of the battling superpowers. It appears the aliens left behind their titanic death machines so humankind will obliterate itself. Rose is determined to find a solution, whatever it takes. But will she become a pawn in a doomsday game no one can win?', 421, null, 2018, 427511, (select id from series where hardcover_id = 979), '3') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Waking Gods', 'Sylvain Neuvel', '8328708671', 'https://assets.hardcover.app/external_data/59522782/d35a5e31746e7ea9b603f5d0bd4592334731eda7.jpeg', '"What''s going on? Turn on the television. What channel? Any channel. An unknown vessel, not of this world, materializes in London. A colossal figure towering over the city, it makes no move. Is this a peaceful first contact or the prelude to an invasion? Every child has nightmares. But the only thing scarier than little Eva Reyes'' dreams - apocalyptic visions of death and destruction - is the habit they have of coming true . . . Scientist Dr Rose Franklin has no memory of the last few years. The strangers she works with say she died, and was brought back to life. The question is not just how . . . but why? Kara Resnik and Vincent Couture fell in love during war, and have found peace since. They are the thin line of defence against what is coming. But they do not know they have been living a lie. And a man who claims to have the answers has his own agenda. There are things he cannot say - and others he won''t. All pieces of an epic puzzle- one we have been trying to solve since the dawn of time . . ."', 320, null, 2017, 427550, (select id from series where hardcover_id = 979), '2') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Wayward Pines - Revolta', 'Blake Crouch', '9513186113', 'https://assets.hardcover.app/editions/4327569/9896909177226764.jpg', 'The second book of the smash-hit Wayward Pines trilogy, from the New York Times bestselling author of Dark Matter, Recursion, and Upgrade

It’s the perfect town . . . as long as you don’t try to leave.

Nestled amid picture-perfect mountains, the idyllic town of Wayward Pines is a modern-day Eden—at least at first glance.

Except that within its fences, the residents are told where to work, how to live, and who to marry. None of them know how they got here. Some believe they are dead. Others think they’re trapped in an unfathomable experiment. Everyone secretly dreams of leaving, but those who dare face a terrifying surprise.

As sheriff, Ethan Burke is tasked with enforcing the town’s laws, and he’s one of the few entrusted with the truth—even though, for all his knowledge, he’s as much a prisoner of Wayward Pines as anyone else.

But when a murder investigation draws him deeper into the town’s inner workings, Ethan learns that its past is darker than even he suspected—and finds himself faced with an impossible choice.

The second novel in Blake Crouch’s blockbuster trilogy, Wayward delves deeper into the irresistible mysteries and horrors of this perfect little town, even as it asks what it means to live with secrets—and what price we’ll pay for the truth.', 322, null, 2013, 427585, (select id from series where hardcover_id = 1125), '2') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Saga, Vol. 4', 'Fiona Staples, Brian K. Vaughan', '8361319670', 'https://assets.hardcover.app/edition/7639517/0a77b231f51ae6198c9403325c112ab264aa4e71.jpeg', '"Saga is the sweeping tale of one young family fighting to find their place in the universe. As they visit a strange new world and encounter even more adversaries, baby Hazel finally becomes a toddler, while her star-crossed parents Marko and Alana struggle to stay on their feet"--Back cover.', 144, null, 2014, 427610, (select id from series where hardcover_id = 5476), '4') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Paper Girls, Vol. 1', 'Brian K. Vaughan, Cliff Chiang', '1632156741', 'https://assets.hardcover.app/edition/30628203/cb30194cf6f6a3cd816e52cb5d7f84a690d2c29c.jpeg', 'In the early hours after Halloween on 1988, four 12-year-old newspaper delivery girls uncover the most important story of all time. Suburban drama and supernatural mysteries collide in this series about nostalgia, first jobs, and the last days of childhood.', 144, null, 2015, 427629, (select id from series where hardcover_id = 5842), '1') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Delirium', 'Lauren Oliver', '9510371580', 'https://assets.hardcover.app/external_data/26029415/afb5973f03b623fb0bcfac3468dcd04c9124062a.jpeg', '"Living with her aunt, uncle, and cousins in Portland, Maine, Lena Haloway is very much looking forward to being cured and living a safe, predictable life. She watched love destroy her mother and isn''t about to make the same mistake.

But with ninety-five days left until her treatment, Lena meets enigmatic Alex, a boy from the Wilds who lives under the government''s radar. What will happen if they do the unthinkable and fall in love?"-- Provided by Amazon', 480, null, 2011, 427645, (select id from series where hardcover_id = 3081), '1') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Head On', 'John Scalzi', '1432853236', 'https://assets.hardcover.app/external_data/61409982/afa99db4db0fdf69c12354eb056441e4fadd832b.jpeg', 'John Scalzi''s Head On, is a chilling near-future SF with the thrills of a gritty cop procedural. Head On brings Scalzi''s trademark snappy dialogue and technological speculation to the future world of sports. To some left with nothing, winning becomes everything . . . In a post-virus world, a daring sport is taking the US by storm. It’s frenetic, violent and involves teams attacking one another with swords and hammers. The aim: to obtain your opponent’s head and carry it through the goalposts. Impossible? Not if the players have Haden’s Syndrome. Unable to move, Haden’s sufferers use robot bodies, which they operate mentally. So in this sport anything goes, no one gets hurt – and crowds and competitors love it. Until a star athlete drops dead on the playing field. But is it an accident? FBI agents Chris Shane and Leslie Vann are determined to find out. In this game, fortunes can be made – or lost. And both players and owners will do whatever it takes to win, on and off the field.', 291, null, 2018, 427711, (select id from series where hardcover_id = 1120), '2') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Nexus', 'Ramez Naam', '8364030051', 'https://assets.hardcover.app/edition/30573290/8b96c504-3441-45f7-a4e1-4cf4e2374e66.jpg', 'Book 1 of the Nexus Trilogy - Continued in Book 2: Crux In the near future, the experimental nano-drug Nexus can link humans together, mind to mind. There are some who want to improve it. There are some who want to eradicate it. And there are others who just want to exploit it. When a young scientist is caught improving Nexus, he''s thrust over his head into a world of danger and international espionage - for there is far more at stake than anyone realizes. From the halls of academe to the halls of power, from the headquarters of an elite US agency in Washington DC to a secret lab beneath a top university in Shanghai, from the underground parties of San Francisco to the illegal biotech markets of Bangkok, from an international neuroscience conference to a remote monastery in the mountains of Thailand - Nexus is a thrill ride through a future on the brink of explosion. Shortlisted for the Arthur C Clarke Award Shortlisted for the Prometheus Award Shortlisted for the Kitschies Award An NPR Best Book of 2013! "Good. Scary good." - Wired "Provocative... A double-edged vision of the post-human."- The Wall Street Journal "A lightning bolt of a novel, with a sense of awe missing from a lot of current fiction."- Ars Technica "Starred Review. Naam turns in a stellar performance in his debut SF novel... What matters here is the remarkable scope and narrative power of the story."- Booklist "A superbly plotted high-tension technothriller ... full of delicious, thoughtful moral ambiguity ... a hell of a read."- Cory Doctorow "A gripping piece of near future speculation... all the grit and pace of the Bourne films."- Alastair Reynolds, author of Revelation Space "A sharp, chilling look at our likely future."- Charles Stross, author of Singularity Sky and Halting State "The most brilliant hard SF thriller I''ve read in years. Reminds me of Michael Crichton at his best."- Brenda Cooper, author of The Creative Fire "A rich cast of characters...the action scenes are crisp, the glimpses of future tech and culture are mesmerizing."- Publishers Weekly "Any old writer can take you on a roller coaster ride, but it takes a wizard like Ramez Naam to take you on the same ride while he builds the roller coaster a few feet in front of you."- John Barnes, author of Directive 51 "Michael Crichton-like."- SFX Magazine "An incredibly imaginative, action-packed intellectual romp!"- Dani Kollin, Prometheus Award-winning author of The Unincorporated Man "The only serious successor to Michael Crichton."- Scott Harrison, author of Archangel', 404, null, 2012, 427721, (select id from series where hardcover_id = 1165), '1') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Echo Wife', 'Sarah Gailey', '1432884131', 'https://assets.hardcover.app/external_data/37179942/61bbdff0ec8fde9c99e167cb1d1dfc11ab083e03.jpeg', 'Sarah Gailey''s The Echo Wife is a non-stop thrill ride of lies, betrayal, and identity, perfect for fans of Big Little Lies and Killing Eve. Evelyn Caldwell’s husband Nathan has been having an affair — with Evelyn Caldwell. Or, to be exact, with Martine, a genetically cloned replica made from Evelyn’s own award-winning research. But that wasn’t even the worst part. When they said all happy families are alike, I don’t think this is what they meant...', 256, null, 2021, 427729, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Grace Year', 'Kim Liggett', '658077505X', 'https://assets.hardcover.app/edition/28559992/9bc06cb5b60b0931adef2d9fb33e02747eb04aff.jpeg', 'In Garner County, girls are told they have the power to lure grown men from their beds, to drive women mad with jealousy. They believe their very skin emits a powerful aphrodisiac, the potent essence of youth, of a girl on the edge of womanhood. That’s why they’re banished for their sixteenth year, to release their magic into the wild so they can return purified and ready for marriage. But not all of them will make it home alive. Sixteen-year-old Tierney James dreams of a better life—a society that doesn’t pit friend against friend or woman against woman, but as her own grace year draws near, she quickly realizes that it’s not just the brutal elements they must fear. It’s not even the poachers in the woods, men who are waiting for a chance to grab one of the girls in order to make a fortune on the black market. Their greatest threat may very well be each other. With sharp prose and gritty realism, The Grace Year examines the complex and sometimes twisted relationships between girls, the women they eventually become, and the difficult decisions they make in-between.', 416, null, 2019, 427730, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Legion', 'Brandon Sanderson', '1250218330', 'https://assets.hardcover.app/external_data/61378089/014727d200f4299a540dc9cdf81e72bef6a8b0df.jpeg', 'Stephen Leeds is perfectly sane. It’s his hallucinations who are mad.

A genius of unrivaled aptitude, Stephen can learn any new skill, vocation, or art in a matter of hours. However, to contain all of this, his mind creates hallucinatory people—Stephen calls them aspects—to hold and manifest the information. Wherever he goes, he is joined by a team of imaginary experts to give advice, interpretation, and explanation. He uses them to solve problems…for a price.

His brain is getting a little crowded, however, and the aspects have a tendency of taking on lives of their own. When a company hires him to recover stolen property—a camera that can allegedly take pictures of the past—Stephen finds himself in an adventure crossing oceans and fighting terrorists. What he discovers may upend the foundation of three major world religions—and, perhaps, give him a vital clue into the true nature of his aspects.', 88, null, 2012, 427735, (select id from series where hardcover_id = 146798), '1') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Monstress, Vol. 1: Awakening', 'Marjorie M. Liu, Sana Takeda, Rus Wooton, Jennifer M. Smith', '1632157098', 'https://assets.hardcover.app/edition/30390454/063df9fd1167f69aa5d985b2e77eccb92cb67908.jpeg', 'Set in an alternate world of art deco beauty and steampunk horror, Monstress tells the epic story of Maika Halfwolf, a teenage survivor of a cataclysmic war between humans and their hated enemies, the Arcanics. In the face of oppression and terrible danger, Maika is both hunter and hunted, searching for answers about her mysterious past as those who seek to use her remain just one step behind ... and all the while, the monster within begins to awaken ...', 192, null, 2016, 427882, (select id from series where hardcover_id = 5587), '1') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Allomancer Jak and the Pits of Eltania', 'Brandon Sanderson', null, 'https://assets.hardcover.app/editions/30399318/9817416286201542.jpg', 'Allomancer Jak and the Pits of Eltania is a short story about an adventuring Allomancer named Jak, as told by him and edited by his Terrisman steward, Handerwym. Handerwym''s annotations imply that the narrator is unreliable (prone to exaggeration and ignorance), but we do find out some information about koloss society post-Catacendre.

It was originally published with the Mistborn Adventure Game''s extension Alloy of Law, later released in part on Sanderson''s website, and also included in Arcanum Unbounded.', 40, null, 2014, 427892, (select id from series where hardcover_id = 5452), '4.5') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Randomize', 'Andy Weir', '1978650817', 'https://assets.hardcover.app/edition/30390694/68181e9d-4277-42f1-9e8f-254edab64360.jpg', 'An IT whiz at the Babylon Casino is enlisted to upgrade security for the game of keno and its random-number generator. The new quantum computer system is foolproof. But someone on the inside is no fool. For once the odds may not favor the house—unless human ingenuity isn’t entirely a thing of the past.

Andy Weir’s Randomize is part of Forward, a collection of six stories of the near and far future from out-of-this-world authors. Each piece can be read or listened to in a single thought-provoking sitting.', 32, null, 2019, 427926, (select id from series where hardcover_id = 5493), '6') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Emergency Skin', 'N. K. Jemisin', '1542093570', 'https://assets.hardcover.app/editions/30399377/8298834229064254.jpg', 'An explorer returns to gather information from a climate-ravaged Earth that his ancestors, and others among the planet’s finest, fled centuries ago. The mission comes with a warning: a graveyard world awaits him. But so do those left behind—hopeless and unbeautiful wastes of humanity who should have died out eons ago. After all this time, there’s no telling how they’ve devolved. Steel yourself, soldier. Get in. Get out. And try not to stare.

N. K. Jemisin’s Emergency Skin is part of Forward, a collection of six stories of the near and far future from out-of-this-world authors. Each piece can be read or listened to in a single thought-provoking sitting.', 38, null, 2019, 427937, (select id from series where hardcover_id = 5493), '3') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Dispatcher', 'John Scalzi', '159606787X', 'https://assets.hardcover.app/edition/30405917/893b04b07b8d36ea7e4b25743d8ee56cc8972746.jpeg', 'One day, not long from now, it becomes almost impossible to murder anyone 999 times out of a thousand, anyone who is intentionally killed comes back. How? We don''t know. But it changes everything: war, crime, daily life. Tony  Valdez is a Dispatchera licensed, bonded professional whose job is to humanely dispatch those whose circumstances put them in death''s crosshairs, so they can have a second chance to avoid the reaper. But when a fellow Dispatcher and former friend is apparently kidnapped, Tony learns that there are some things that are worse than death, and that some people are ready to do almost anything to avenge what they see as a wrong. It''s a  race against time for Valdez to find his friend before it''s too late-- before not even a Dispatcher can save him.--Jacket flap.', 130, null, 2016, 427962, (select id from series where hardcover_id = 5204), '1') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Last Town', 'Blake Crouch', '1480599735', 'https://assets.hardcover.app/edition/13434364/54457c3c3120cf5414736a9cf5ea0703e7ef695f.jpeg', 'The final book of the smash-hit Wayward Pines trilogy from the New York Times bestselling author of Dark Matter, Recursion, and Upgrade

What’s inside was a nightmare. What’s outside is a thousand times worse.

Welcome to Wayward Pines, the last town.

Secret Service agent Ethan Burke arrived in Wayward Pines, Idaho, three weeks ago. In this town, people are told who to marry, where to live, where to work. No one is allowed to leave; even asking questions can get you killed.

But Ethan has discovered the astonishing secret of what lies beyond the electrified fence that surrounds Wayward Pines and protects it from the terrifying world beyond. And now that secret is about to come storming through the fence to wipe out this last, fragile remnant of humanity.

The Last Town at last pitches Ethan Burke and his fellow residents into all-out war against the forces outside the town’s gates—and in doing so delivers every bit the riotously horrific, breathlessly action-packed conclusion that the Wayward Pines trilogy deserves.', 285, null, 2014, 427987, (select id from series where hardcover_id = 1125), '3') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Magician''s Land', 'Lev Grossman', '1473518857', 'https://assets.hardcover.app/editions/30403843/1023313166311857.jpg', 'Quentin Coldwater has been cast out of Fillory, the secret magical land of his childhood dreams. With nothing left to lose he returns to where his story began, the Brakebills Preparatory College of Magic. But he can’t hide from his past, and it’s not long before it comes looking for him.
 
Along with Plum, a brilliant young undergraduate with a dark secret of her own, Quentin sets out on a crooked path through a magical demimonde of gray magic and desperate characters. But all roads lead back to Fillory, and his new life takes him to old haunts, like Antarctica, and to buried secrets and old friends he thought were lost forever. He uncovers the key to a sorcery masterwork, a spell that could create magical utopia, a new Fillory—but casting it will set in motion a chain of events that will bring Earth and Fillory crashing together. To save them he will have to risk sacrificing everything.
 
The Magician’s Land is an intricate thriller, a fantastical epic, and an epic of love and redemption that brings the Magicians trilogy to a magnificent conclusion, confirming it as one of the great achievements in modern fantasy. It’s the story of a boy becoming a man, an apprentice becoming a master, and a broken land finally becoming whole.', 864, null, 2014, 428035, (select id from series where hardcover_id = 1041), '3') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('MaddAddam', 'Margaret Atwood', '077100897X', 'https://assets.hardcover.app/external_data/24941087/9a78e530200ef31742dd964ee98d3528ef352f45.jpeg', '"Bringing together characters from Oryx and Crake and The Year of the Flood, this thrilling conclusion to Margaret Atwood''s speculative fiction trilogy confirms the ultimate endurance of humanity, community, and love. Months after the Waterless Flood pandemic has wiped out most of humanity, Toby and Ren have rescued their friend Amanda from the vicious Painballers. They return to the MaddAddamite cob house, which is being fortified against man and giant Pigoon alike. Accompanying them are the Crakers, the gentle, quasihuman species engineered by the brilliant but deceased Crake. While their reluctant prophet, Jimmy--Crake''s one-time friend--recovers from a debilitating fever, it''s left to Toby to narrate the Craker theology, with Crake as Creator. She must also deal with cultural misunderstandings, terrible coffee, and her jealousy over her lover, Zeb. Meanwhile, Zeb searches for Adam One, founder of the God''s Gardeners, the pacifist green religion from which Zeb broke years ago to lead the MaddAddamites in active resistance against the destructive CorpSeCorps. Now, under threat of an imminent Painballer attack, the MaddAddamites must fight back with the aid of their newfound allies, some of whom have four trotters. At the center is the extraordinary story of Zeb''s past, which involves a lost brother, a hidden murder, a bear, and a bizarre act of revenge. Combining adventure, humor, romance, superb storytelling, and an imagination that is at once dazzlingly inventive and grounded in a recognizable world, MaddAddam is vintage Margaret Atwood, and a moving and dramatic conclusion to her internationally celebrated dystopian trilogy"--', 416, null, 2013, 428217, (select id from series where hardcover_id = 1851), '3') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Hollow City', 'Ransom Riggs', '9722529692', 'https://assets.hardcover.app/external_data/35466351/396f9e836751e00ec2ca7966df4d3a810387625b.jpeg', 'September 3, 1940. Ten peculiar children flee an army of deadly monsters. And only one person can help them - but she''s trapped in the body of a bird. The extraordinary journey that began in "Miss Peregrine''s Home for Peculiar Children" continues as Jacob Portman and his newfound friends journey to London, the peculiar capital of the world. There, they hope to find a cure for their beloved headmistress, Miss Peregrine.

But in this war-torn city, hideous surprises lurk around every corner. And before Jacob can deliver the peculiar children to safety, he must make an important decision about his love for Emma Bloom.', 399, null, 2014, 428421, (select id from series where hardcover_id = 5477), '2') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Gods of Jade and Shadow', 'Silvia Moreno-Garcia', '6070796667', 'https://assets.hardcover.app/edition/30400901/e8e1e229-74b4-42bb-a854-00b8ed9a30d2.jpg', 'The Jazz Age is in full swing, but Casiopea Tun is too busy cleaning the floors of her wealthy grandfather’s house to listen to any fast tunes. Nevertheless, she dreams of a life far from her dusty small town in southern Mexico. A life she can call her own. 

Yet this new life seems as distant as the stars, until the day she finds a curious wooden box in her grandfather’s room. She opens it—and accidentally frees the spirit of the Mayan god of death, who requests her help in recovering his throne from his treacherous brother. Failure will mean Casiopea’s demise, but success could make her dreams come true.

In the company of the strangely alluring god and armed with her wits, Casiopea begins an adventure that will take her on a cross-country odyssey from the jungles of Yucatán to the bright lights of Mexico City—and deep into the darkness of the Mayan underworld.', 352, null, 2019, 428523, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Earthlings', 'Sayaka Murata, Ginny Tapley Takemori', '109418912X', 'https://assets.hardcover.app/edition/30402962/0f377dc504f355a32c1669d8fbae415a241b4c25.jpeg', 'PLEASE NOTE THE CONTENT WARNINGS FOR THIS BOOK

As a child, Natsuki doesn’t fit into her family. Her parents favor her sister, and her best friend is a plush toy hedgehog named Piyyut who has explained to her that he has come from the planet Popinpobopia on a special quest to help her save the Earth. Each summer, Natsuki counts down the days until her family drives into the mountains of Nagano to visit her grandparents in their wooden house in the forest, a place that couldn’t be more different from her grey commuter town. One summer, her cousin Yuu confides to Natsuki that he is an extraterrestrial and that every night he searches the sky for the spaceship that might take him back to his home planet. Natsuki wonders if she might be an alien too. Back in her city home, Natsuki is scolded or ignored and even preyed upon by a young teacher at her cram school. As she grows up in a hostile, violent world, she consoles herself with memories of her time with Yuu and discovers a surprisingly potent inner power. Natsuki seems forced to fit into a society she deems a “baby factory” but even as a married woman she wonders if there is more to this world than the mundane reality everyone else seems to accept. The answers are out there, and Natsuki has the power to find them.

Dreamlike, sometimes shocking, and always strange and wonderful, Earthlings asks what it means to be happy in a stifling world, and cements Sayaka Murata’s status as a master chronicler of the outsider experience and our own uncanny universe.', 247, null, 1983, 428541, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Inheritance Games', 'Jennifer Lynn Barnes', '1549133527', 'https://assets.hardcover.app/editions/12972012/261130687709961-91oB1gHuiIL._SL1500_.jpg', '"But her fortunes change in an instant when billionaire Tobias Hawthorne dies and leaves Avery virtually his entire fortune. The catch? Avery has no idea why—or even who Tobias Hawthorne is.

To receive her inheritance, Avery must move into sprawling, secret passage-filled Hawthorne House, where every room bears the old man''s touch—and his love of puzzles, riddles, and codes. Unfortunately for Avery, Hawthorne House is also occupied by the family that Tobias Hawthorne just dispossessed. 

This includes the four Hawthorne grandsons: dangerous, magnetic, brilliant boys who grew up with every expectation that one day, they would inherit billions. Heir apparent Grayson Hawthorne is convinced that Avery must be a conwoman, and he''s determined to take her down. His brother, Jameson, views her as their grandfather''s last hurrah: a twisted riddle, a puzzle to be solved. Caught in a world of wealth and privilege with danger around every turn, Avery will have to play the game herself just to survive."-- Provided by Amazon', 384, null, 2019, 428546, (select id from series where hardcover_id = 5593), '1') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Library of the Unwritten', 'A.J. Hackwith', '1984806378', 'https://assets.hardcover.app/book_mappings/7333433/04c5757b964ad1315e3e7b34abeef7227326f412.jpeg', 'In the first book in a brilliant new fantasy series, books that aren''t finished by their authors reside in the Library of the Unwritten in Hell, and it is up to the Librarian to track down any restless characters who emerge from those unfinished stories.

Many years ago, Claire was named Head Librarian of the Unwritten Wing-- a neutral space in Hell where all the stories unfinished by their authors reside. Her job consists mainly of repairing and organizing books, but also of keeping an eye on restless stories that risk materializing as characters and escaping the library. When a Hero escapes from his book and goes in search of his author, Claire must track and capture him with the help of former muse and current assistant Brevity and nervous demon courier Leto.

But what should have been a simple retrieval goes horrifyingly wrong when the terrifyingly angelic Ramiel attacks them, convinced that they hold the Devil''s Bible. The text of the Devil''s Bible is a powerful weapon in the power struggle between Heaven and Hell, so it falls to the librarians to find a book with the power to reshape the boundaries between Heaven, Hell….and Earth.
', 384, null, 2019, 428550, (select id from series where hardcover_id = 1686), '1') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Saga, Vol. 3', 'Brian K. Vaughan, Fiona Staples', '836131959X', 'https://assets.hardcover.app/edition/30680339/6c946b0873560f73245a73f502af38b849930129.jpeg', 'Collects SAGA #13-18

The Eisner, Harvey, and Hugo Award-winning phenomenon continues, as new parents Marko and Alana travel to an alien world to visit their hero, while the family''s pursuers finally close in on their targets.', 144, null, 2013, 428579, (select id from series where hardcover_id = 5476), '3') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('City of Heavenly Fire', 'Cassandra Clare', '140635581X', 'https://assets.hardcover.app/edition/30930563/d127e5f3200ac6bde280f819cbaa446290c78a6c.jpeg', 'Sebastian Morgenstern is on the move, systematically turning Shadowhunter against Shadowhunter. Bearing the Infernal Cup, he transforms Shadowhunters into creatures out of nightmare, tearing apart families and lovers as the ranks of his Endarkened army swell.

The embattled Shadowhunters withdraw to Idris - but not even the famed demon towers of Alicante can keep Sebastian at bay. And with the Nephilim trapped in Idris, who will guard the world against demons?

When one of the greatest betrayals the Nephilim have ever known is revealed, Clary, Jace, Isabelle, Simon, and Alec must flee - even if their journey takes them deep into the demon realms, where no Shadowhunter has set foot before, and from which no human being has ever returned...

Love will be sacrificed and lives lost in the terrible battle for the fate of the word in the thrilling final installment of the classic urban fantasy series The Mortal Instruments!', 768, null, 2014, 428618, (select id from series where hardcover_id = 5473), '6') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Dance of Thieves', 'Mary E. Pearson', '1250159024', 'https://assets.hardcover.app/edition/16155026/17d5ce40ab2d19998980528ce87e4ad5d2190340.jpeg', 'When the patriarch of the Ballenger empire dies, his son, Jase, becomes its new leader. Even nearby kingdoms bow to the strength of this outlaw family, who have always governed by their own rules. But a new era looms on the horizon, set in motion by a young queen, which makes her the target of the dynasty''s resentment and anger.', 512, null, 2018, 428642, (select id from series where hardcover_id = 6383), '1') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Midnight Sun', 'Stephenie Meyer', '9780349003627', 'https://assets.hardcover.app/external_data/49621560/94b0fe82d98ddfe84108444d3bf7bbc5d2d1cbf0.jpeg', 'When Edward Cullen and Bella Swan met in Twilight, an iconic love story was born. But until now, fans have heard only Bella''s side of the story. At last, readers can experience Edward''s version in the long-awaited companion novel, Midnight Sun.

This unforgettable tale as told through Edward''s eyes takes on a new and decidedly dark twist. Meeting Bella is both the most unnerving and intriguing event he has experienced in all his years as a vampire. As we learn more fascinating details about Edward''s past and the complexity of his inner thoughts, we understand why this is the defining struggle of his life. How can he justify following his heart if it means leading Bella into danger?

In Midnight Sun, Stephenie Meyer transports us back to a world that has captivated millions of readers and brings us an epic novel about the profound pleasures and devastating consequences of immortal love.', 833, null, 2008, 428662, (select id from series where hardcover_id = 5451), '5') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Winter''s Orbit', 'Everina Maxwell', '1250758858', 'https://assets.hardcover.app/edition/4095460/60699da1ecea1337c17d26aa0fa37f84f256190e.jpeg', 'While the Iskat Empire has long dominated the system through treaties and political alliances, several planets, including Thea, have begun to chafe under Iskat''s rule. When tragedy befalls Imperial Prince Taam, his Thean widower, Jainan, is rushed into an arranged marriage with Taam''s cousin, the disreputable Kiem, in a bid to keep the rising hostilities between the two worlds under control.

But when it comes to light that Prince Taam''s death may not have been an accident, and that Jainan himself may be a suspect, the unlikely pair must overcome their misgivings and learn to trust one another as they navigate the perils of the Iskat court, try to solve a murder, and prevent an interplanetary war… all while dealing with their growing feelings for each other.', 352, null, 2021, 428672, (select id from series where hardcover_id = 34162), '1') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Aurora Rising', 'Amie Kaufman, Jay Kristoff', '3732456668', 'https://assets.hardcover.app/edition/14856672/c11d4dfc24d6771398c6c74a1649503f5db035f8.jpeg', 'The year is 2380, and the graduating cadets of Aurora Academy are being assigned their first missions. Star pupil Tyler Jones is ready to recruit the squad of his dreams, but his own boneheaded heroism sees him stuck with the dregs nobody else in the Academy would touch . . . 
A cocky diplomat with a black belt in sarcasm 
A sociopath scientist with a fondness for shooting her bunkmates 
A smart-ass tech whiz with the galaxy''s biggest chip on his shoulder 
An alien warrior with anger-management issues 
A tomboy pilot who''s totally not into him, in case you were wondering 

And Ty''s squad isn''t even his biggest problem--that''d be Aurora Jie-Lin O''Malley, the girl he''s just rescued from interdimensional space. Trapped in cryo-sleep for two centuries, Auri is a girl out of time and out of her depth. But she could be the catalyst that starts a war millions of years in the making, and Tyler''s squad of losers, discipline cases, and misfits might just be the last hope for the entire galaxy. NOBODY PANIC.', 472, null, 2013, 428688, (select id from series where hardcover_id = 3347), '1') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Sleeping Beauties', 'Stephen King, Owen King', '1473665191', 'https://assets.hardcover.app/book/428695/1dd73673-4be1-4a2c-90be-faa791261a0b.jpg', 'In a future so real and near it might be now, something happens when women go to sleep: they become shrouded in a cocoon-like gauze. If they are awakened, if the gauze wrapping their bodies is disturbed or violated, the women become feral and spectacularly violent. And while they sleep they go to another place, a better place, where harmony prevails and conflict is rare. One woman, the mysterious “Eve Black,” is immune to the blessing or curse of the sleeping disease. Is Eve a medical anomaly to be studied? Or is she a demon who must be slain?

Abandoned, left to their increasingly primal urges, the men divide into warring factions, some wanted to kill Eve, some to save her. Others exploit the chaos to wreak their own vengeance on new enemies. All turn to violence in a suddenly all-male world. Set in a small Appalachian town whose primary employer is a woman’s prison, Sleeping Beauties is a wildly provocative, gloriously dramatic father-son collaboration that feels particularly urgent and relevant today.', 717, null, 2017, 428695, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('King''s Cage', 'Victoria Aveyard', '9176457516', 'https://assets.hardcover.app/external_data/40706221/bea511a980804202ff09cec489911c63f0215892.jpeg', 'In this breathless third installment to Victoria Aveyard’s #1 New York Times bestselling Red Queen series, rebellion is rising and allegiances will be tested on every side.

Mare Barrow is a prisoner, powerless without her lightning, tormented by her lethal mistakes. She lives at the mercy of a boy she once loved, a boy made of lies and betrayal. Now a king, Maven Calore continues weaving his dead mother’s web in an attempt to maintain control over his country-and his prisoner.

As Mare bears the weight of Silent Stone in the palace, her once-ragtag band of newbloods and Reds continue organizing, training, and expanding. They prepare for war, no longer able to linger in the shadows. And Cal, the exiled prince with his own claim on Mare’s heart, will stop at nothing to bring her back.

When blood turns on blood, and ability on ability, there may be no one left to put out the fire-leaving Norta as Mare knows it to burn all the way down.

Perfect for fans of George R.R. Martin’s Game of Thrones series, King’s Cage is the third high-stakes installment in the #1 New York Times bestselling Red Queen series.', 520, null, 2017, 428751, (select id from series where hardcover_id = 1204), '3') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Hunger of the Gods', 'John Gwynne', '8445014900', 'https://assets.hardcover.app/editions/30399960/4281951718120310.jpg', 'Lik-Rifa, the dragon god of legend, has been freed from her eternal prison. Now she plots a new age of blood and conquest. 

As Orka continues the hunt for her missing son, the Bloodsworn sweep south in a desperate race to save one of their own–and Varg takes the first steps on the path of vengeance. 

Elvar has sworn to fulfil her blood oath and rescue a prisoner from the clutches of Lik-Rifa and her dragonborn followers, but first she must persuade the Battle-Grim to follow her. Yet even the might of the Bloodsworn and Battle-Grim cannot stand alone against a dragon god. 

Their only hope lies within the mad writings of a chained god. A book of forbidden magic with the power to raise the wolf god Ulfrir from the dead…and bring about a battle that will shake the foundations of the earth.', 656, null, 2022, 428827, (select id from series where hardcover_id = 5874), '2') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Neon Gods', 'Katee Robert', '6069557131', 'https://assets.hardcover.app/external_data/61878738/1dcee7296b1c772326d22949dee5a699ce0f1f14.jpeg', 'Society darling Persephone Dimitriou plans to flee the ultra-modern city of Olympus and start over far from the backstabbing politics of the Thirteen Houses. But all that’s ripped away when her mother ambushes her with an engagement to Zeus, the dangerous power behind their glittering city’s dark facade.

With no options left, Persephone flees to the forbidden undercity and makes a devil’s bargain with a man she once believed a myth... a man who awakens her to a world she never knew existed.

Hades has spent his life in the shadows, and he has no intention of stepping into the light. But when he finds that Persephone can offer a little slice of the revenge he’s spent years craving, it’s all the excuse he needs to help her—for a price. Yet every breathless night spent tangled together has given Hades a taste for Persephone, and he’ll go to war with Olympus itself to keep her close…

A modern retelling of Hades and Persephone that’s as sinful as it is sweet.', 378, null, 2021, 428863, (select id from series where hardcover_id = 1246), '1') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Prison Healer', 'Lynette Noni', '2017240400', 'https://assets.hardcover.app/edition/31484641/11824866-bbf6-4341-a5a6-9cad5b4db355.jpg', 'When the Rebel Queen is captured, Kiva is charged with keeping the terminally ill woman alive long enough for her to undergo the Trial by Ordeal: a series of elemental challenges against the torments of air, fire, water, and earth, assigned to only the most dangerous of criminals.

Then a coded message from Kiva’s family arrives, containing a single order: “Don’t let her die. We are coming.” Aware that the Trials will kill the sickly queen, Kiva risks her own life to volunteer in her place. If she succeeds, both she and the queen will be granted their freedom.

But no one has ever survived.

With an incurable plague sweeping Zalindov, a mysterious new inmate fighting for Kiva’s heart, and a prison rebellion brewing, Kiva can’t escape the terrible feeling that her trials have only just begun.', 416, null, 2021, 428976, (select id from series where hardcover_id = 1208), '1') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Unbroken', 'C.L. Clark', '0316542679', 'https://assets.hardcover.app/external_data/28473285/e4b7e2b601ed697083f535175361565af1353669.jpeg', 'On the far outreaches of a crumbling desert empire, two women--a princess and a soldier--will haggle over the price of a nation in this richly imagined, breath-taking sapphic epic fantasy filled with rebellion, espionage, and assassinations.

Touraine is a soldier. Stolen as a child and raised to kill and die for the empire, her only loyalty is to her fellow conscripts. But now, her company has been sent back to her homeland to stop a rebellion, and the ties of blood may be stronger than she thought.

Luca needs a turncoat. Someone desperate enough to tiptoe the bayonet''s edge between treason and orders. Someone who can sway the rebels toward peace, while Luca focuses on what really matters: getting her uncle off her throne.

Through assassinations and massacres, in bedrooms and war rooms, Touraine and Luca will haggle over the price of a nation. But some things aren''t for sale.

"A perfect military fantasy: brutal, complex, human and impossible to put down." - Tasha Suri, author of Empire of Sand', 486, null, 2021, 428981, (select id from series where hardcover_id = 2173), '1') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('A Kingdom of Flesh and Fire', 'Jennifer L. Armentrout', '9791259850812', 'https://assets.hardcover.app/external_data/521567/4ea5f0a17847ecb38d507954715a23221f13111d.jpeg', 'From #1 New York Times bestselling author Jennifer L. Armentrout comes a new novel in her Blood and Ash series…

A Betrayal…

Everything Poppy has ever believed in is a lie, including the man she was falling in love with. Thrust among those who see her as a symbol of a monstrous kingdom, she barely knows who she is without the veil of the Maiden. But what she does know is that nothing is as dangerous to her as him. The Dark One. The Prince of Atlantia. He wants her to fight him, and that’s one order she’s more than happy to obey. He may have taken her, but he will never have her.

A Choice….

Casteel Da’Neer is known by many names and many faces. His lies are as seductive as his touch. His truths as sensual as his bite. Poppy knows better than to trust him. He needs her alive, healthy, and whole to achieve his goals. But he’s the only way for her to get what she wants—to find her brother Ian and see for herself if he has become a soulless Ascended. Working with Casteel instead of against him presents its own risks. He still tempts her with every breath, offering up all she’s ever wanted. Casteel has plans for her. Ones that could expose her to unimaginable pleasure and unfathomable pain. Plans that will force her to look beyond everything she thought she knew about herself—about him. Plans that could bind their lives together in unexpected ways that neither kingdom is prepared for. And she’s far too reckless, too hungry, to resist the temptation.

A Secret…

But unrest has grown in Atlantia as they await the return of their Prince. Whispers of war have become stronger, and Poppy is at the very heart of it all. The King wants to use her to send a message. The Descenters want her dead. The wolven are growing more unpredictable. And as her abilities to feel pain and emotion begin to grow and strengthen, the Atlantians start to fear her. Dark secrets are at play, ones steeped in the blood-drenched sins of two kingdoms that would do anything to keep the truth hidden. But when the earth begins to shake, and the skies start to bleed, it may already be too late.', 626, null, 2020, 429005, (select id from series where hardcover_id = 1217), '2') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Hawthorne Legacy', 'Jennifer Lynn Barnes', '6555670576', 'https://assets.hardcover.app/editions/30401187/2712087599578475-91Y0MgtvzZL._SL1500_.jpg', 'The Inheritance Games ended with a bombshell, and now heiress Avery Grambs has to pick up the pieces and find the man who might hold the answers to all of her questions—including why Tobias Hawthorne left his entire fortune to Avery, a virtual stranger, rather than to his own daughters or grandsons. 

Thanks to a DNA test, Avery knows she’s not a Hawthorne by blood, but clues pile up hinting at a deeper connection to the family than she had ever imagined. As the mystery grows and the plot thickens, Grayson and Jameson, two of the enigmatic and magnetic Hawthorne grandsons, continue to pull Avery in different directions. And there are threats lurking around every corner, as adversaries emerge who will stop at nothing to see Avery out of the picture—by any means necessary. 

With nonstop action, aspirational jet-setting, Knives Out-like family intrigue, swoonworthy romance, and billions of dollars hanging in the balance, The Hawthorne Legacy will thrill Jennifer Lynn Barnes fans and new readers alike.', 354, null, 2021, 429100, (select id from series where hardcover_id = 5593), '2') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Egg', 'Andy Weir', null, 'https://assets.hardcover.app/editions/30402760/6954991505317569.jpg', '"You were on your way home when you died. It was a car accident. Nothing particularly remarkable, but fatal nonetheless. You left behind a wife and two children. It was a painless death. ... And that’s when you met me."

The Egg is a short story written by Andy Weir, his most popular, and follows a nameless 48-year-old man who discovers the "meaning of life" after he dies. The story is about "you" (in the second person), and God, who is "me" (in the first person). God says that you have been reincarnated many times before, and that you are soon to be reincarnated once more, leading to quite a few existential questions.

Andy Weir (1972-) built a career as a software engineer until the success of his first published novel, The Martian (2011), allowed him to live out his dream of writing fulltime. He is a lifelong space nerd and a devoted hobbyist of subjects such as relativistic physics, orbital mechanics, and the history of manned spaceflight. He also mixes a mean cocktail.', 3, null, 2009, 429406, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Crying of Lot 49', 'Thomas Pynchon', '0397004184', 'https://assets.hardcover.app/edition/3464110/f6830673d71b3c2bf0784f80966bd1f32d608d8e.jpeg', 'When her ex-lover, wealthy real-estate tycoon Pierce Inverarity, dies and designates her the coexecutor of his estate, California housewife Oedipa Maas is thrust into a paranoid mystery of metaphors, symbols, and the United States Postal Service. Traveling across Southern California, she meets some extremely interesting characters, and attains a not inconsiderable amount of self-knowledge.', 152, null, 1965, 429610, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Dog Stars', 'Peter Heller', '0449013146', 'https://assets.hardcover.app/edition/32872959/d974e982-9069-4220-bce8-d136c9b0cfc4.jpg', 'Hig somehow survived the flu pandemic that killed everyone he knows. Now his wife is gone, his friends are dead, and he lives in the hangar of a small abandoned airport with his dog, Jasper, and a mercurial, gun-toting misanthrope named Bangley.

But when a random transmission beams through the radio of his 1956 Cessna, the voice ignites a hope deep inside him that a better life exists outside their tightly controlled perimeter. Risking everything, he flies past his point of no return and follows its static-broken trail, only to find something that is both better and worse than anything he could ever hope for.', 322, null, 2012, 430173, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Think Again: The Power of Knowing What You Don''t Know', 'Adam M. Grant', '6177933092', 'https://assets.hardcover.app/external_data/30192578/789d29d1bc64b2e5ce18332edf17eeeb445860a7.jpeg', '#1 New York Times Bestseller “THIS. This is the right book for right now. Yes, learning requires focus. But, unlearning and relearning requires much more—it requires choosing courage over comfort. In Think Again, Adam Grant weaves together research and storytelling to help us build the intellectual and emotional muscle we need to stay curious enough about the world to actually change it. I’ve never felt so hopeful about what I don’t know.” —Brené Brown, Ph.D., #1 New York Times bestselling author of Dare to Lead The bestselling author of Give and Take and Originals examines the critical art of rethinking: learning to question your opinions and open other people''s minds, which can position you for excellence at work and wisdom in life Intelligence is usually seen as the ability to think and learn, but in a rapidly changing world, there''s another set of cognitive skills that might matter more: the ability to rethink and unlearn. In our daily lives, too many of us favor the comfort of conviction over the discomfort of doubt. We listen to opinions that make us feel good, instead of ideas that make us think hard. We see disagreement as a threat to our egos, rather than an opportunity to learn. We surround ourselves with people who agree with our conclusions, when we should be gravitating toward those who challenge our thought process. The result is that our beliefs get brittle long before our bones. We think too much like preachers defending our sacred beliefs, prosecutors proving the other side wrong, and politicians campaigning for approval--and too little like scientists searching for truth. Intelligence is no cure, and it can even be a curse: being good at thinking can make us worse at rethinking. The brighter we are, the blinder to our own limitations we can become. Organizational psychologist Adam Grant is an expert on opening other people''s minds--and our own. As Wharton''s top-rated professor and the bestselling author of Originals and Give and Take, he makes it one of his guiding principles to argue like he''s right but listen like he''s wrong. With bold ideas and rigorous evidence, he investigates how we can embrace the joy of being wrong, bring nuance to charged conversations, and build schools, workplaces, and communities of lifelong learners. You''ll learn how an international debate champion wins arguments, a Black musician persuades white supremacists to abandon hate, a vaccine whisperer convinces concerned parents to immunize their children, and Adam has coaxed Yankees fans to root for the Red Sox. Think Again reveals that we don''t have to believe everything we think or internalize everything we feel. It''s an invitation to let go of views that are no longer serving us well and prize mental flexibility over foolish consistency. If knowledge is power, knowing what we don''t know is wisdom.', 320, null, 2021, 430368, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Later', 'Stephen King', '8401027128', 'https://assets.hardcover.app/edition/30400316/9d91f1d8-f70c-4df8-8034-13c50d372607.jpg', 'SOMETIMES GROWING UP

MEANS FACING YOUR DEMONS

The son of a struggling single mother, Jamie Conklin just wants an ordinary childhood. But Jamie is no ordinary child. Born with an unnatural ability his mom urges him to keep secret, Jamie can see what no one else can see and learn what no one else can learn. But the cost of using this ability is higher than Jamie can imagine – as he discovers when an NYPD detective draws him into the pursuit of a killer who has threatened to strike from beyond the grave.

LATER is Stephen King at his finest, a terrifying and touching story of innocence lost and the trials that test our sense of right and wrong. With echoes of King’s classic novel It, LATER is a powerful, haunting, unforgettable exploration of what it takes to stand up to evil in all the faces it wears.', 248, null, 2021, 430445, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Gilded Ones', 'Namina Forna', '8427220219', 'https://assets.hardcover.app/external_data/507561/c04ecb25f0d9518081c70b92c64b3b7a61c565dd.jpeg', '"Already different from everyone else because of her unnatural intuition, Deka prays for red blood so she can finally feel like she belongs.

But on the day of the ceremony, her blood runs gold, the color of impurity–and Deka knows she will face a consequence worse than death.

Then a mysterious woman comes to her with a choice: stay in the village and submit to her fate, or leave to fight for the emperor in an army of girls just like her. They are called alaki–near-immortals with rare gifts. And they are the only ones who can stop the empire''s greatest threat.

Knowing the dangers that lie ahead yet yearning for acceptance, Deka decides to leave the only life she''s ever known. But as she journeys to the capital to train for the biggest battle of her life, she will discover that the great walled city holds many surprises. Nothing and no one are quite what they seem to be–not even Deka herself."-- Provided by Amazon', 434, null, 2014, 430555, (select id from series where hardcover_id = 3340), '1') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('A Deepness in the Sky', 'Vernor Vinge', '0613214234', 'https://assets.hardcover.app/external_data/28442166/39136df4425f7ec91ec859ecdd743cde1c331958.jpeg', 'The prequel to A Fire Upon The Deep, this is the story of Pham Nuwen, a small cog in the interstellar trading fleet of the Queng Ho. The Queng Ho and the Emergents are orbiting the dormant planet Arachna, which is about to wake up to technology, but the Emergents'' plans are sinister.', 775, null, 1999, 430652, (select id from series where hardcover_id = 1134), '2') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Permutation City', 'Greg Egan', '1922240087', 'https://assets.hardcover.app/editions/27728606/3a5c7d0e-02b9-49af-8eb7-23680e16e864-permutation.jpg', 'The story of a man with a vision - immortality : for those who can afford it is found in cyberspace. PERMUTATION CITY is the tale of a man with a vision - how to create immortality - and how that vision becomes something way beyond his control. Encompassing the lives and struggles of an artificial life junkie desperate to save her dying mother, a billionaire banker scarred by a terrible crime, the lovers for whom, in their timeless virtual world, love is not enough - and much more - PERMUTATION CITY is filled with the sense of wonder.', 310, null, 1994, 430706, (select id from series where hardcover_id = 6416), '2') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Down Among the Sticks and Bones', 'Seanan McGuire', '0765392038', 'https://assets.hardcover.app/external_data/23198528/ca0a0b60dfefbb2acdf9784d61790ae6684da090.jpeg', 'Seanan McGuire returns to her popular Wayward Children series with Down Among the Sticks and Bones—a truly standalone story suitable for adult and young adult readers of urban fantasy, and the follow-up to the Alex, Hugo, Nebula, and Locus Award-winning, World Fantasy Award finalist, Tiptree Honor List book Every Heart a Doorway

Twin sisters Jack and Jill were seventeen when they found their way home and were packed off to Eleanor West’s Home for Wayward Children.

This is the story of what happened first…

Jacqueline was her mother’s perfect daughter—polite and quiet, always dressed as a princess. If her mother was sometimes a little strict, it’s because crafting the perfect daughter takes discipline.

Jillian was her father’s perfect daughter—adventurous, thrill-seeking, and a bit of a tom-boy. He really would have preferred a son, but you work with what you''ve got.

They were five when they learned that grown-ups can’t be trusted.

They were twelve when they walked down the impossible staircase and discovered that the pretense of love can never be enough to prepare you a life filled with magic in a land filled with mad scientists and death and choices.', 192, null, 2017, 430942, (select id from series where hardcover_id = 1638), '2') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Auberon', 'James S. A. Corey', '1549170090', 'https://assets.hardcover.app/edition/30448357/e8cc89c4-a7e6-45f7-af38-3d9a1d4308c6.jpg', 'Auberon explores a new and alien world and the age-old dangers that humanity has carried with it to the stars. Now a Prime Original series. This story will be available in the complete Expanse story collection, Memory’s Legion. Hugo Award Winner for Best Series.

Auberon is one of the first and most important colony worlds in humanity''s reach, and the new conquering faction has come to claim it. Governor Rittenaur has come to bring civilization and order to the far outpost and guarantee the wealth and power of the Empire. But Auberon already has its own history, a complex culture, and a criminal kingpin named Erich with very different plans. In a world of deceit, violence, and corruption, the greatest danger Rittenaur faces is love.', 75, null, 2019, 430999, (select id from series where hardcover_id = 1026), '7.5') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('If on a Winter''s Night a Traveler', 'Italo Calvino', '0919630456', 'https://assets.hardcover.app/external_data/28442196/dcaa1fdb6320477cbcf916791394256e6b63f2ec.jpeg', 'Introduction by Peter Washington; Translation by William Weaver Italo Calvino’s masterpiece combines a love story and a detective story into an exhilarating allegory of reading, in which the reader of the book becomes the book’s central character. Based on a witty analogy between the reader’s desire to finish the story and the lover’s desire to consummate his or her passion, IF ON A WINTER’S NIGHT A TRAVELER is the tale of two bemused readers whose attempts to reach the end of the same book—IF ON A WINTER’S NIGHT A TRAVELER, by Italo Calvino, of course—are constantly and comically frustrated. In between chasing missing chapters of the book, the hapless readers tangle with an international conspiracy, a rogue translator, an elusive novelist, a disintegrating publishing house, and several oppressive governments. The result is a literary labyrinth of storylines that interrupt one another—an Arabian Nights of the postmodern age.', 272, null, 1979, 431145, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The House of the Spirits', 'Isabel Allende', '8447306615', 'https://assets.hardcover.app/external_data/45044277/b73ead53002f98144d363439af732ff4623e7e3f.jpeg', 'The astonishing debut of a gifted storyteller, The House of the Spirits is both a symbolic family saga and the story of an unnamed Latin American country’s turbulent history. Isabel Allende constructs a spirit-ridden world and fills it with colorful and all-too-human inhabitants including Esteban, the patriarch, a volatile and proud man whose lust for land is legendary and who is haunted by tyrannical passion for the wife he can never completely posses; Clara, the matriarch, elusive and mysterious, who foretells family tragedy and shapes the fortunes of the house and the Truebas; Blanca, their daughter, soft-spoken yet rebellious, whose shocking love for the son of her father’s foreman fuels Esteban’s everlasting contempt, even as it produces the grandchild he adores; and Alba, the fruit of Blanca’s forbidden love, a luminous beauty and a fiery and willful woman.

The Trueba family’s passions, struggles, and secrets span three generations and a century of violent change, culminating in a crisis that brings the proud and tyrannical patriarch and his beloved granddaughter to opposite sides of the barricades. Against a backdrop of revolution and counterrevolution, Allende brings to life a family whose private bonds of love and hatred are more complex and enduring than the political allegiances that set them at odds.', 481, null, 1982, 431234, (select id from series where hardcover_id = 5906), '3') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Bone Clocks', 'David Mitchell', '0676979319', 'https://assets.hardcover.app/edition/30381755/37c0eac7-0910-4e9d-a468-aaf901fcd218.jpg', 'Following a scalding row with her mother, fifteen-year-old Holly Sykes slams the door on her old life. But Holly is no typical teenage runaway: a sensitive child once contacted by voices she knew only as “the radio people,” Holly is a lightning rod for psychic phenomena. Now, as she wanders deeper into the English countryside, visions and coincidences reorder her reality until they assume the aura of a nightmare brought to life.

For Holly has caught the attention of a cabal of dangerous mystics—and their enemies. But her lost weekend is merely the prelude to a shocking disappearance that leaves her family irrevocably scarred. This unsolved mystery will echo through every decade of Holly’s life, affecting all the people Holly loves—even the ones who are not yet born.

A Cambridge scholarship boy grooming himself for wealth and influence, a conflicted father who feels alive only while reporting from occupied Iraq, a middle-aged writer mourning his exile from the bestseller list—all have a part to play in this surreal, invisible war on the margins of our world. From the medieval Swiss Alps to the nineteenth-century Australian bush, from a hotel in Shanghai to a Manhattan townhouse in the near future, their stories come together in moments of everyday grace and extraordinary wonder.', 595, null, 2014, 431399, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('A Torch Against the Night', 'Sabaa Tahir', '8075771028', 'https://assets.hardcover.app/edition/30447774/e4b2ef4ceaef75c14b9070882c14341b1bf11ede.jpeg', 'This time it takes readers into the heart of the Empire as Laia and Elias fight their way north to liberate Laia’s brother from the horrors of Kauf Prison. Hunted by Empire soldiers, manipulated by the Commandant, and haunted by their pasts, Laia and Elias must outfox their enemies and confront the treacherousness of their own hearts.

In the city of Serra, Helene Aquilla finds herself bound to the will of the Empire’s twisted new leader, Marcus. When her loyalty is questioned, Helene finds herself taking on a mission to prove herself—a mission that might destroy her, instead.', 496, null, 2016, 432212, (select id from series where hardcover_id = 1795), '2') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Colorless Tsukuru Tazaki and His Years of Pilgrimage', 'Haruki Murakami, Philip Gabriel', '9724622673', 'https://assets.hardcover.app/editions/30402895/5694944181588459.jpg', 'Tsukuru Tazaki had four best friends at school. By chance all of their names contained a colour. The two boys were called Akamatsu, meaning ‘red pine’, and Oumi, ‘blue sea’, while the girls’ names were Shirane, ‘white root’, and Kurono, ‘black field’. Tazaki was the only last name with no colour in it.

One day Tsukuru Tazaki’s friends announced that they didn''t want to see him, or talk to him, ever again.

Since that day Tsukuru has been floating through life, unable to form intimate connections with anyone. But then he meets Sara, who tells him that the time has come to find out what happened all those years ago.', 336, null, 2013, 432492, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Last House on Needless Street', 'Catriona Ward', '1788168488', 'https://assets.hardcover.app/external_data/50292102/41f6f8404e2e4c3010bb93acb43f4fcb408f2d2d.jpeg', 'In a boarded-up house on a dead-end street at the edge of the wild Washington woods lives a family of three.

A teenage girl who isn’t allowed outside, not after last time.
A man who drinks alone in front of his TV, trying to ignore the gaps in his memory.
And a house cat who loves napping and reading the Bible.

An unspeakable secret binds them together, but when a new neighbor moves in next door, what is buried out among the birch trees may come back to haunt them all.', 342, null, 2021, 432642, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Home Before Dark', 'Riley Sager', '1524745189', 'https://assets.hardcover.app/edition/8248273/51c682711c7d7729505fc82c15e0dc02a8f5199e.jpeg', 'Twenty-five years ago, Maggie Holt and her parents moved into Baneberry Hall, a rambling Victorian estate in the Vermont woods. Three weeks later they fled in the dead of night, an ordeal her father recounted in a memoir called House of Horrors. His story of supernatural happenings and malevolent spirits became a worldwide phenomenon, rivaling The Amityville Horror in popularity—and skepticism.

Maggie was too young to remember any of the horrific events that supposedly took place, and as an adult she doesn’t believe a word of her father’s claims. Ghosts, after all, don’t exist. When she inherits Baneberry Hall after his death and returns to renovate the place and sell it, her homecoming is anything but warm. The locals aren’t thrilled that their small town has been made infamous, and human characters with starring roles in House of Horrors are waiting in the shadows.
 
Even more unnerving is Baneberry Hall itself—a place where unsettling whispers of the past lurk around every corner. And as Maggie starts to experience strange occurrences ripped from the pages of her father’s book, the truth she uncovers about the house’s dark history will challenge everything she believes.', 413, null, 2020, 432651, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Exit West', 'Mohsin Hamid', '0241290082', 'https://assets.hardcover.app/external_data/59710262/054dd78cf9c9b824bc52473eff37e04da3dfd722.jpeg', '"In a country teetering on the brink of civil war, two young people meet-- sensual, fiercely independent Nadia and gentle, restrained Saeed.  They embark on a furtive love affair, and are soon cloistered in a premature intimacy by the unrest roiling their city.  When it explodes, turning familiar streets into a patchwork of checkpoints and bomb blasts, they begin to hear whispers about doors-- doors that can whisk people far away, if perilously and for a price.  As the violence escalates, Nadia and Saeed decide that they no longer have a choice.  Leaving their homeland and their old lives behind, they find a door and step through.  [This book] follows the couple as they emerge into an alien and uncertain future, struggling to hold on to each other, to their past, to the very sense of who they are."--From regular print book.', 242, null, 2017, 433132, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Fifty Shades of Grey', 'E.L. James', '1780891261', 'https://assets.hardcover.app/edition/15439076/402718fa15330d230303147a6a288b339056e762.jpeg', 'When literature student Anastasia Steele goes to interview young entrepreneur Christian Grey, she encounters a man who is beautiful, brilliant, and intimidating. The unworldly, innocent Ana is startled to realize she wants this man and, despite his enigmatic reserve, finds she is desperate to get close to him. Unable to resist Ana’s quiet beauty, wit, and independent spirit, Grey admits he wants her, too—but on his own terms.
 
Shocked yet thrilled by Grey’s singular erotic tastes, Ana hesitates. For all the trappings of success—his multinational businesses, his vast wealth, his loving family—Grey is a man tormented by demons and consumed by the need to control. When the couple embarks on a daring, passionately physical affair, Ana discovers Christian Grey’s secrets and explores her own dark desires.

Erotic, amusing, and deeply moving, the Fifty Shades Trilogy is a tale that will obsess you, possess you, and stay with you forever.

This book is intended for mature audiences.', 514, null, 2010, 433359, (select id from series where hardcover_id = 5919), '1') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Termination Shock', 'Neal Stephenson', '0063028050', 'https://assets.hardcover.app/editions/30401934/2393757528188909.jpg', 'One man—visionary billionaire restaurant chain magnate T. R. Schmidt, Ph.D.—has a Big Idea for reversing global warming, a master plan perhaps best described as “elemental.” But will it work? And just as important, what are the consequences for the planet and all of humanity should it be applied?

Ranging from the Texas heartland to the Dutch royal palace in the Hague, from the snow-capped peaks of the Himalayas to the sunbaked Chihuahuan Desert, Termination Shock brings together a disparate group of characters from different cultures and continents who grapple with the real-life repercussions of global warming. Ultimately, it asks the question: Might the cure be worse than the disease?', 720, null, 2021, 433528, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Soulsmith', 'Will Wight', '1943363358', 'https://assets.hardcover.app/external_data/44491408/e7e471c66bd3c7a748fa8c773095dd7519956219.jpeg', 'Lindon has taken his first step on the road to power, but the sacred artists of the world outside his homeland are still far beyond him.

To advance, he turns to the arcane skills of the Soulsmiths, who craft weapons from the stuff of souls. With new powers come new enemies, but also new allies, including a mysterious mentor who seems interested in Lindon for his own purposes.

Even with new training and new help, Lindon is still only a Copper, and he soon finds himself facing down and entire sect of enemy Golds.', 384, null, 2016, 433541, (select id from series where hardcover_id = 4968), '2') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Cemetery Boys', 'Aiden Thomas', '1432889265', 'https://assets.hardcover.app/book_mappings/7333126/1dee7d9569aacf19863223a1b0996648ed043307.jpeg', 'Yadriel has summoned a ghost, and now he can''t get rid of him.

When his traditional Latinx family has problems accepting his true gender, Yadriel becomes determined to prove himself a real brujo. With the help of his cousin and best friend Maritza, he performs the ritual himself, and then sets out to find the ghost of his murdered cousin and set it free.

However, the ghost he summons is actually Julian Diaz, the school''s resident bad boy, and Julian is not about to go quietly into death. He''s determined to find out what happened and tie off some loose ends before he leaves. Left with no choice, Yadriel agrees to help Julian, so that they can both get what they want. But the longer Yadriel spends with Julian, the less he wants to let him leave.', 344, null, 2020, 433616, (select id from series where hardcover_id = 29229), '1') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('My Heart Is a Chainsaw', 'Stephen Graham Jones', '1789098092', 'https://assets.hardcover.app/external_data/29351106/3352f302eeebf378d289a6a5cc6e6036baf6f8f2.jpeg', 'In her quickly gentrifying rural lake town Jade sees recent events only her encyclopedic knowledge of horror films could have prepared her for in this latest chilling novel that “will give you nightmares. The good kind, of course” (BuzzFeed) from the Jordan Peele of horror literature, Stephen Graham Jones.

“Some girls just don’t know how to die…”

Shirley Jackson meets Friday the 13th in My Heart Is a Chainsaw, written by the New York Times bestselling author of The Only Good Indians Stephen Graham Jones, called “a literary master” by National Book Award winner Tananarive Due and “one of our most talented living writers” by Tommy Orange.

Alma Katsu calls My Heart Is a Chainsaw “a homage to slasher films that also manages to defy and transcend genre.” On the surface is a story of murder in small-town America. But beneath is its beating heart: a biting critique of American colonialism, Indigenous displacement, and gentrification, and a heartbreaking portrait of a broken young girl who uses horror movies to cope with the horror of her own life.

Jade Daniels is an angry, half-Indian outcast with an abusive father, an absent mother, and an entire town that wants nothing to do with her. She lives in her own world, a world in which protection comes from an unusual source: horror movies…especially the ones where a masked killer seeks revenge on a world that wronged them. And Jade narrates the quirky history of Proofrock as if it is one of those movies. But when blood actually starts to spill into the waters of Indian Lake, she pulls us into her dizzying, encyclopedic mind of blood and masked murderers, and predicts exactly how the plot will unfold.

Yet, even as Jade drags us into her dark fever dream, a surprising and intimate portrait emerges…a portrait of the scared and traumatized little girl beneath the Jason Voorhees mask: angry, yes, but also a girl who easily cries, fiercely loves, and desperately wants a home. A girl whose feelings are too big for her body. My Heart Is a Chainsaw is her story, her homage to horror and revenge and triumph.', 416, null, 2021, 433665, (select id from series where hardcover_id = 45801), '1') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Ex Hex', 'Erin Sterling', '3453321855', 'https://assets.hardcover.app/external_data/61264448/cf2d233192ae67be6a9f7664892ee6fbcd6ab36c.jpeg', 'New York Times bestselling author Rachel Hawkins, writing as Erin Sterling, casts a spell with a spine-tingling romance full of wishes, witches, and hexes gone wrong.

Nine years ago, Vivienne Jones nursed her broken heart like any young witch would: vodka, weepy music, bubble baths…and a curse on the horrible boyfriend. Sure, Vivi knows she shouldn’t use her magic this way, but with only an “orchard hayride” scented candle on hand, she isn’t worried it will cause him anything more than a bad hair day or two.

That is until Rhys Penhallow, descendent of the town’s ancestors, breaker of hearts, and annoyingly just as gorgeous as he always was, returns to Graves Glen, Georgia. What should be a quick trip to recharge the town’s ley lines and make an appearance at the annual fall festival turns disastrously wrong. With one calamity after another striking Rhys, Vivi realizes her silly little Ex Hex may not have been so harmless after all.

Suddenly, Graves Glen is under attack from murderous wind-up toys, a pissed off ghost, and a talking cat with some interesting things to say. Vivi and Rhys have to ignore their off the charts chemistry to work together to save the town and find a way to break the break-up curse before it’s too late.', 308, null, 2021, 433773, (select id from series where hardcover_id = 110893), '1') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Fall or, Dodge in Hell', 'Neal Stephenson', '0062887467', 'https://assets.hardcover.app/edition/30403253/6c762156acff0294f31cf547adb5a55d8c9e8ecb.jpeg', '"In his youth, Richard "Dodge" Forthrast founded Corporation 9592, a gaming company that made him a multibillionaire. Now in his middle years, Dodge appreciates his comfortable, unencumbered life, managing his myriad business interests, and spending time with his beloved niece Zula and her young daughter, Sophia. One beautiful autumn day, while he undergoes a routine medical procedure, something goes irrevocably wrong. Dodge is pronounced brain dead and put on life support, leaving his stunned family and close friends with difficult decisions. Long ago, when a much younger Dodge drew up his will, he directed that his body be given to a cryonics company now owned by enigmatic tech entrepreneur Elmo Shepherd. Legally bound to follow the directive despite their misgivings, Dodge''s family has his brain scanned and its data structures uploaded and stored in the cloud, until it can eventually be revived. In the coming years, technology allows Dodge''s brain to be turned back on. It is an achievement that is nothing less than the disruption of death itself. An eternal afterlife--the Bitworld--is created, in which humans continue to exist as digital souls. But this brave new immortal world is not the Utopia it might first seem... Fall, or Dodge in Hell is pure, unadulterated fun: a grand drama of analog and digital, man and machine, angels and demons, gods and followers, the finite and the eternal. In this exhilarating epic, Neal Stephenson raises profound existential questions and touches on the revolutionary breakthroughs that are transforming our future. Combining the technological, philosophical, and spiritual in one grand myth, he delivers a mind-blowing speculative literary saga for the modern age."--provided by publisher.', 896, null, 2018, 434196, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('ReDawn', 'Brandon Sanderson, Janci Patterson', '9781399602198', 'https://assets.hardcover.app/editions/30402232/1464335802248948.jpeg', 'From #1 bestselling author Brandon Sanderson and Janci Patterson comes the second of three Skyward series novellas, each told from the perspective of a different member of the team back on Detritus. Read Alanik''s story between Starsight and Cytonic. “Don’t trust their lies. Don’t trust their false peace.” That is the warning that Alanik of the planet ReDawn gave the human pilot Spensa after Alanik’s ship crash-landed on Detritus. While accepting an invitation to meet with her people’s enemy, the Galactic Superiority, Alanik heard Spensa’s cry for help across the vastness of space, and she used her cytonic powers to hyperjump her ship to the source of that cry. What she found there was a shock—a whole planet of free humans fighting against the Superiority. Were they the allies her people desperately needed? When she recovered from her injuries and met the friendly humans Jorgen and FM of Skyward Flight, she found that her warning to Spensa had gone unheeded by the government of Detritus, and they were considering a peace overture from the Superiority. Now having returned to ReDawn, Alanik is dismayed to learn that her own people are falling into the exact same trap. The faction in ReDawn’s government that wants to appease the Superiority has gained the upper hand. With Alanik’s mentor, Renakin captured, she has no one to turn to but Jorgen, FM, and their friend Rig. An ancient technology may have the power to save both of their planets from disaster, but can they discover its secrets before it’s too late? Praise for Skyward An Instant New York Times Bestseller A Kirkus Reviews Best Book of the Year • "Startling revelations and stakes-raising implications . . . Sanderson plainly had a ball with this nonstop, highflying opener, and readers will too." —Kirkus Reviews, starred review • "With this action-packed trilogy opener, Sanderson offers up a resourceful, fearless heroine and a memorable cast." —Publishers Weekly, starred review • "It is impossible to turn the pages fast enough." —Booklist', 229, null, 2021, 434356, (select id from series where hardcover_id = 12088), '2') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Sunreach', 'Brandon Sanderson, Janci Patterson, Suzy Jackson', '1399602187', 'https://assets.hardcover.app/editions/30402233/2565165103698544.jpg', 'From #1 bestselling author Brandon Sanderson and Janci Patterson comes the first of three Skyward series novellas, each told from the perspective of a different member of the team back on Detritus. Read FM''s story between Starsight and Cytonic.

When a planet-destroying Delver suddenly appears in the sky of Detritus and vanishes just as suddenly, FM knows that the last free human society got lucky. Her Skyward Flight companion, Spensa, figured out how to draw this Delver away, but it won’t be so easy next time.

The forces of the Galactic Superiority will be back—and if the Defiant Defense Force can’t figure out a way to escape the planet, humanity’s destruction is only a matter of time. Spensa’s mission to infiltrate the Superiority unveiled the secret to their hyperdrives—a cytonic slug species called the Taynix. Now FM’s flightleader, Jorgen, has found a large group of Taynix hiding in the caverns far below Detritus’s surface.

FM and Jorgen must work together with the engineer Rig to awaken the mysterious alien Alanik and unlock the powers of the Taynix, or humanity will be trapped. With Spensa’s friend Minister Cuna of the Superiority stranded at the outpost of Sunreach, they need to figure out how to rescue her—or the Superiority government will be in the sole clutches of those who want to wipe out Detritus once and for all.', 208, null, 2021, 434357, (select id from series where hardcover_id = 12088), '1') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Evershore', 'Brandon Sanderson, Janci Patterson', '1399602225', 'https://assets.hardcover.app/external_data/61115323/cdc6041de2e4e107d7de1c2f82bd7c164fb1b635.jpeg', 'From #1 bestselling author Brandon Sanderson and Janci Patterson comes the final of three Skyward series novellas, each told from the perspective of a different member of the team back on Detritus. Listen to Jorgen''s story along with Cytonic.

With the government of Detritus in disarray because of Superiority treachery, and with Spensa still away on her mission in the Nowhere, Jorgen must work together with the alien Alanik to pick up the pieces. They intercept a strange transmission from the planet Evershore and its Kitsen inhabitants, who say they have some of Jorgen’s people and want to return them—but can the Kitsen be trusted? And can Jorgen learn to master his increasingly erratic cytonic powers before they spiral out of control and destroy all hope of forming an alliance against the Superiority?', 208, null, 2021, 434359, (select id from series where hardcover_id = 12088), '3') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('A Tale for the Time Being', 'Ruth Ozeki', '904142234X', 'https://assets.hardcover.app/edition/31455984/34e83853e93311eec8fc17dfe179a882c349bfe0.jpeg', 'A brilliant, unforgettable, and long-awaited novel from bestselling author Ruth Ozeki "A time being is someone who lives in time, and that means you, and me, and every one of us who is, or was, or ever will be." In Tokyo, sixteen-year-old Nao has decided there''s only one escape from her aching loneliness and her classmates'' bullying. But before she ends it all, Nao plans to document the life of her great-grandmother, a Buddhist nun who''s lived more than a century. A diary is Nao''s only solace--and will touch lives in a ways she can scarcely imagine. Across the Pacific, we meet Ruth, a novelist living on a remote island who discovers a collection of artifacts washed ashore in a Hello Kitty lunchbox--possibly debris from the devastating 2011 tsunami. As the mystery of its contents unfolds, Ruth is pulled into the past, into Nao''s drama and her unknown fate, and forward into her own future. Full of Ozeki''s signature humour and deeply engaged with the relationship between writer and reader, past and present, fact and fiction, quantum physics, history, and myth, A Tale for the Time Being is a brilliantly inventive, beguiling story of our shared humanity and the search for home.', 432, null, 2013, 434887, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Beartown', 'Fredrik Backman, Neil Smith', '1501160788', 'https://assets.hardcover.app/edition/30402545/788ac1cb1b32f4eebe528af5432f52241232c6a3.jpeg', 'A dazzling, profound novel about a small town with a big dream—and the price required to make it come true.

People say Beartown is finished. A tiny community nestled deep in the forest, it is slowly losing ground to the ever encroaching trees. But down by the lake stands an old ice rink, built generations ago by the working men who founded this town. And in that ice rink is the reason people in Beartown believe tomorrow will be better than today. Their junior ice hockey team is about to compete in the national semi-finals, and they actually have a shot at winning. All the hopes and dreams of this place now rest on the shoulders of a handful of teenage boys.

Being responsible for the hopes of an entire town is a heavy burden, and the semi-final match is the catalyst for a violent act that will leave a young girl traumatized and a town in turmoil. Accusations are made and, like ripples on a pond, they travel through all of Beartown, leaving no resident unaffected.

Beartown explores the hopes that bring a small community together, the secrets that tear it apart, and the courage it takes for an individual to go against the grain. In this story of a small forest town, Fredrik Backman has found the entire world', 418, null, 2014, 434983, (select id from series where hardcover_id = 1494), '1') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Firekeeper''s Daughter', 'Angeline Boulley', '3641264898', 'https://assets.hardcover.app/external_data/59588240/450f1b864acbf2a39a370c7d37978e7295c8a1c4.jpeg', 'With four starred reviews, Angeline Boulley''s debut novel, Firekeeper''s Daughter, is a groundbreaking YA thriller about a Native teen who must root out the corruption in her community, perfect for readers of Angie Thomas and Tommy Orange.

Eighteen-year-old Daunis Fontaine has never quite fit in, both in her hometown and on the nearby Ojibwe reservation. She dreams of a fresh start at college, but when family tragedy strikes, Daunis puts her future on hold to look after her fragile mother. The only bright spot is meeting Jamie, the charming new recruit on her brother Levi’s hockey team.

Yet even as Daunis falls for Jamie, she senses the dashing hockey star is hiding something. Everything comes to light when Daunis witnesses a shocking murder, thrusting her into an FBI investigation of a lethal new drug.

Reluctantly, Daunis agrees to go undercover, drawing on her knowledge of chemistry and Ojibwe traditional medicine to track down the source. But the search for truth is more complicated than Daunis imagined, exposing secrets and old scars. At the same time, she grows concerned with an investigation that seems more focused on punishing the offenders than protecting the victims.

Now, as the deceptions—and deaths—keep growing, Daunis must learn what it means to be a strong Anishinaabe kwe (Ojibwe woman) and how far she’ll go for her community, even if it tears apart the only world she’s ever known.', 352, null, 2021, 435091, (select id from series where hardcover_id = 174236), '1') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('American War', 'Omar El Akkad', '0771009399', 'https://assets.hardcover.app/external_data/594061/e246956519d1e25d5757a1394b03fd4cb8ffbab3.jpeg', 'NATIONAL BESTSELLER • A second American Civil War, a devastating plague, and one family caught deep in the middle—this gripping debut novel asks what might happen if America were to turn its most devastating policies and deadly weapons upon itself. From the author of What Strange Paradise "Powerful ... as haunting a postapocalyptic universe as Cormac McCarthy [created] in The Road." —The New York Times Sarat Chestnut, born in Louisiana, is only six when the Second American Civil War breaks out in 2074. But even she knows that oil is outlawed, that Louisiana is half underwater, and that unmanned drones fill the sky. When her father is killed and her family is forced into Camp Patience for displaced persons, she begins to grow up shaped by her particular time and place. But not everyone at Camp Patience is who they claim to be. Eventually Sarat is befriended by a mysterious functionary, under whose influence she is turned into a deadly instrument of war. The decisions that she makes will have tremendous consequences not just for Sarat but for her family and her country, rippling through generations of strangers and kin alike.', 352, null, 2017, 435299, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Steppenwolf', 'Hermann Hesse, Basil Creighton', '9023423097', 'https://assets.hardcover.app/editions/3512145/d062403f-cedf-45b3-a03d-0e666b9291ce.jpg', 'A story that focuses on the loneliness and suffering of the protagonist, Harry Haller, who feels that he has no place in a world filled with meaningless frivolity. Having decided to take his own life a chance encounter causes him to change his views and he begins to learn ways to enjoy life. One of the most misunderstood of his novels the book is, according to Hesse, about the possibilities of transcendence and healing.', 256, null, 1927, 435859, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Quantum Thief', 'Hannu Rajaniemi', '2352946271', 'https://assets.hardcover.app/edition/542963/10f7d407-a85d-4607-b94c-b4befe70113d.jpg', 'Jean le Flambeur is a post-human criminal, mind burglar, confidence artist and trickster. His origins are shrouded in mystery, but his exploits are known throughout the Heterarchy - from breaking into the vast Zeusbrains of the Inner System to steal their thoughts, to stealing rare Earth antiques from the aristocrats of the Moving Cities of Mars. Except that Jean made one mistake. Now he is condemned to play endless variations of a game-theoretic riddle in the vast virtual jail of the Axelrod Archons - the Dilemma Prison - against countless copies of himself. Jean''s routine of death, defection and cooperation is upset by the arrival of Mieli and her spidership, Perhonen. She offers him a chance to win back his freedom and the powers of his old self - in exchange for finishing the one heist he never quite managed . . . The Quantum Thief is a dazzling hard SF novel set in the solar system of the far future - a heist novel peopled by bizarre post-humans but powered by very human motives of betrayal, revenge and jealousy. It is a stunning debut.', 330, null, 2010, 435978, (select id from series where hardcover_id = 1707), '1') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Let the Right One In', 'John Ajvide Lindqvist', '9170363862', 'https://assets.hardcover.app/edition/30641176/c809c83ecd007dd3823ffc09ffae48ee812d604a.jpeg', 'John Ajvide Lindqvist’s international bestseller Let the Right One In is “a brilliant take on the vampire myth, and a roaring good story” (New York Times bestselling author Kelley Armstrong), the basis for the multi-film festival award-winning Swedish film, the U.S. adaptation Let Me In directed by Matt Reeves (The Batman), and the Showtime TV series. It is autumn 1981 when inconceivable horror comes to Blackeberg, a suburb in Sweden. The body of a teenager is found, emptied of blood, the murder rumored to be part of a ritual killing. Twelve-year-old Oskar is personally hoping that revenge has come at long last—revenge for the bullying he endures at school, day after day. But the murder is not the most important thing on his mind. A new girl has moved in next door—a girl who has never seen a Rubik’s Cube before, but who can solve it at once. There is something wrong with her, though, something odd. And she only comes out at night. . .', 513, null, 2004, 436291, (select id from series where hardcover_id = 5945), '1') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('14', 'Peter Clines, Jean-Pierre Pugi', '2290097748', 'https://assets.hardcover.app/external_data/1155836/4047c185a9825c3b3195b7cbf1d3f80aaaa9d17d.jpeg', 'There are some odd things about Nate’s new apartment.

Of course, he has other things on his mind. He hates his job. He has no money in the bank. No girlfriend. No plans for the future. So while his new home isn’t perfect, it’s livable. The rent is low, the property managers are friendly, and the odd little mysteries don’t nag at him too much.

At least, not until he meets Mandy, his neighbour across the hall, and notices something unusual about her apartment. And Xela’s apartment. And Tim’s. And Veek’s. Because every room in this old Los Angeles brownstone has a mystery or two. Mysteries that stretch back over a hundred years. Some of them are in plain sight. Some are behind locked doors. And all together these mysteries could mean the end of Nate and his friends.

Or the end of everything...', 469, null, 1990, 436894, (select id from series where hardcover_id = 1058), '1') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Wanderers', 'Chuck Wendig', '0399182101', 'https://assets.hardcover.app/book/436912/e2b00e13-ffdd-46d6-b7c5-78443e96ff8b.jpeg', 'Shana wakes up one morning to discover her little sister in the grip of a strange malady. She appears to be sleepwalking. She cannot talk and cannot be woken up. And she is heading with inexorable determination to a destination that only she knows. But Shana and her sister are not alone. Soon they are joined by a flock of sleepwalkers from across America, on the same mysterious journey. And like Shana, there are other “shepherds” who follow the flock to protect their friends and family on the long dark road ahead.

For as the sleepwalking phenomenon awakens terror and violence in America, the real danger may not be the epidemic but the fear of it. With society collapsing all around them—and an ultraviolent militia threatening to exterminate them—the fate of the sleepwalkers depends on unraveling the mystery behind the epidemic. The terrifying secret will either tear the nation apart—or bring the survivors together to remake a shattered world.', 775, null, 2018, 436912, (select id from series where hardcover_id = 5606), '1') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Billy Summers', 'Stephen King', '8892741977', 'https://assets.hardcover.app/edition/31937930/e3f816ee-9d80-426b-81d6-27c7af882d5f.jpg', 'Billy Summers is a man in a room with a gun. He’s a killer for hire and the best in the business. But he’ll do the job only if the target is a truly bad guy. And now Billy wants out. But first there is one last hit. Billy is among the best snipers in the world, a decorated Iraq war vet, a Houdini when it comes to vanishing after the job is done. So what could possibly go wrong?

How about everything...', 433, null, 2021, 437349, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Heir of Novron', 'Michael J. Sullivan', '1464048576', 'https://assets.hardcover.app/edition/30544626/5c6fea96-69e5-41cd-8617-55ce07291262.jpg', 'VICTORY IS FOR THE TAKING The New Empire intends to celebrate its victory over the Nationalists with a day that will never be forgotten. On the high holiday of Wintertide, the empress will be married, and Degan Gaunt and the Witch of Melengar will be publically executed. Once the empress suffers a fatal accident, everything will be perfect. There is only one problem - Royce and Hadrian have finally found the Heir of Novron. ''This epic fantasy showcases the arrival of a master storyteller'' Library Journal on Theft of Swords The Riyria Revelations THEFT OF SWORDS RISE OF EMPIRE HEIR OF NOVRON The Riyria Chronicles THE CROWN TOWER THE ROSE AND THE THORN', 946, null, 2012, 437919, (select id from series where hardcover_id = 5843), '3') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Remote Control', 'Nnedi Okorafor, Adjoa Andoh', '125077280X', 'https://assets.hardcover.app/edition/30405012/e158d1fd-5b64-4bc9-ab82-3380560d18e1.jpg', 'An alien artifact turns a young girl into Death''s adopted daughter in Remote Control, a thrilling sci-fi tale of community and female empowerment from Nebula and Hugo Award-winner Nnedi Okorafor “She’s the adopted daughter of the Angel of Death. Beware of her. Mind her. Death guards her like one of its own.” The day Fatima forgot her name, Death paid a visit. From hereon in she would be known as Sankofa—a name that meant nothing to anyone but her, the only tie to her family and her past. Her touch is death, and with a glance a town can fall. And she walks—alone, except for her fox companion—searching for the object that came from the sky and gave itself to her when the meteors fell and when she was yet unchanged; searching for answers. But is there a greater purpose for Sankofa, now that Death is her constant companion? At the Publisher''s request, this title is being sold without Digital Rights Management Software (DRM) applied.', 156, null, 2021, 438306, (select id from series where hardcover_id = 5537), null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Redemption of Time', 'Baoshu, Ken Liu', '8417347372', 'https://assets.hardcover.app/editions/1151602/4873472810566009-36262251.jpg', 'Set in the universe of Cixin Liu''s Three-Body Problem trilogy, and continuing the saga. This original story by Baoshu-published with Liu''s blessing-charts the aftermath of the conflict between humanity and the extraterrestrial Trisolarans', 400, null, 2011, 438839, (select id from series where hardcover_id = 1584), '4') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Robots and Empire', 'Isaac Asimov', '8576573199', 'https://assets.hardcover.app/edition/30109168/d7396bce53709e2c63285a5549bbc92abd0bb11b.jpeg', 'Long ago, Gladia''s robots Daneel and Giskard played a vital role in opening the worlds beyond the Solar system to Settlers from Earth. Now the conscience-stricken robots are faced with an even greater challenge. Either the sacred Three Laws of Robotics are in ruins - or a new, superior Law must be established to bring peace to the galaxy. With Madam Gladia and D.G. Baley - the captain of the Settler traders and a descendant of the robots'' friend Elijah Baley - Daneel and Giskard travel to the robot stronghold of Solaria...where they uncover a sinister Spacer plot to destroy Earth itself.', 436, null, 1985, 439485, (select id from series where hardcover_id = 1044), '4') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Rule of Wolves', 'Leigh Bardugo', '8025353036', 'https://assets.hardcover.app/external_data/24971313/a36ebc61a1799fad468cacddac37c9ee57060883.jpeg', 'The Demon King. As Fjerda''s massive army prepares to invade, Nikolai Lantsov will summon every bit of his ingenuity and charm - and even the monster within - to win this fight. But a dark threat looms that cannot be defeated by a young king''s gift for the impossible. The Stormwitch. Zoya Nazyalensky has lost too much to war. She saw her mentor die and her worst enemy resurrected, and she refuses to bury another friend. Now duty demands she embrace her powers to become the weapon her country needs. No matter the cost. The Queen of Mourning. Deep undercover, Nina Zenik risks discovery and death as she wages war on Fjerda from inside its capital. But her desire for revenge may cost her country its chance at freedom and Nina the chance to heal her grieving heart. King. General. Spy. Together they must find a way to forge a future in the darkness. Or watch a nation fall.', 592, null, 2021, 439556, (select id from series where hardcover_id = 5591), '2') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Tehanu', 'Ursula K. Le Guin', '7539966637', 'https://assets.hardcover.app/external_data/31639296/1752389ea6e19b42c4f5fb807a8603f66a15bc60.jpeg', 'When Sparrowhawk, the Archmage of Earthsea, returns from the dark land stripped of his magic powers, he finds refuge with the aging widow Tenar and a crippled girl child who carries an unknown destiny.', 320, null, 1990, 439834, (select id from series where hardcover_id = 1170), '4') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Ninth Rain', 'Jen Williams', '1472245334', 'https://assets.hardcover.app/edition/30404852/f7e6086d23f950914876e431a615629d5d383a27.jpeg', 'The great city of Ebora once glittered with gold. Now its streets are stalked by wolves. Tormalin the Oathless has no taste for sitting around waiting to die while the realm of his storied ancestors falls to pieces - talk about a guilt trip. Better to be amongst the living, where there are taverns full of women and wine.

When eccentric explorer, Lady Vincenza ''Vintage'' de Grazon, offers him employment, he sees an easy way out. Even when they are joined by a fugitive witch with a tendency to set things on fire, the prospect of facing down monsters and retrieving ancient artefacts is preferable to the abomination he left behind.

But not everyone is willing to let the Eboran empire collapse, and the adventurers are quickly drawn into a tangled conspiracy of magic and war. For the Jure''lia are coming, and the Ninth Rain must fall...', 544, null, 2017, 440142, (select id from series where hardcover_id = 1664), '1') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Truly Devious', 'Maureen Johnson', '1538501244', 'https://assets.hardcover.app/edition/30406226/ffd5c893c7fa8c451b220081d64c6f48d73d1e02.jpeg', 'Ellingham Academy is a famous private school in Vermont for the brightest thinkers, inventors, and artists.
It was founded by Albert Ellingham, an early twentieth century tycoon, who wanted to make a wonderful place full of riddles, twisting pathways, and gardens. “A place,” he said, “where learning is a game.”

Shortly after the school opened, his wife and daughter were kidnapped. The only real clue was a mocking riddle listing methods of murder, signed with the frightening pseudonym “Truly, Devious.” It became one of the great unsolved crimes of American history.

True-crime aficionado Stevie Bell is set to begin her first year at Ellingham Academy, and she has an ambitious plan: She will solve this cold case. That is, she will solve the case when she gets a grip on her demanding new school life and her housemates: the inventor, the novelist, the actor, the artist, and the jokester. But something strange is happening. Truly Devious makes a surprise return, and death revisits Ellingham Academy. The past has crawled out of its grave. Someone has gotten away with murder.', 432, null, 2018, 440165, (select id from series where hardcover_id = 5960), '1') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Crippled God', 'Steven Erikson', '8834431235', 'https://assets.hardcover.app/editions/30512982/3206217430019012.jpg', 'The Bonehunters march for Kolanse, led by Adjunct Tavore. This woman with no gifts of magic, deemed plain, unprepossessing, displaying nothing to instill loyalty or confidence, will challenge the gods - if her own mutinous troops don''t kill her first.

Her enemy, the Forkrul Assail, seek to cleanse the world, to annihilate everything. In the realm of Kurald Galain, home to the long lost city of Kharkanas, a refugees commanded by Yedan Derryg, the Watch, await the breaching of Lightfall, and the coming of the Tiste Liosan. In this war they cannot win, they will die in the name of an empty city and a queen with no subjects.

Elsewhere, the three Elder Gods, Kilmandaros, Errastas and Sechul Lath, work to shatter the chains binding Korabas, the Otataral Dragon. Against her force of utter devastation, no mortal can stand. At the Gates of Starvald Demelain, the Azath House sealing the portal is dying. Soon will come the Eleint, dragons, and a final cataclysm.', 930, null, 2011, 440991, (select id from series where hardcover_id = 1167), '10') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Shadow & Claw', 'Gene Wolfe', '1429966270', 'https://assets.hardcover.app/edition/2187369/09b92c653d98ceef03d594f4d620753ed6f83f44.jpeg', 'Shadow & Claw brings together the first two books of the tetralogy in one volume:

The Shadow of the Torturer is the tale of young Severian, an apprentice in the Guild of Torturers on the world called Urth, exiled for committing the ultimate sin of his profession -- showing mercy toward his victim.

The Claw of the Conciliator continues the saga of Severian, banished from his home, as he undertakes a mythic quest to discover the awesome power of an ancient relic, and learn the truth about his hidden destiny.', 418, null, 1994, 441054, (select id from series where hardcover_id = 1172), '1') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Shorefall', 'Robert Jackson Bennett', '9579447829', 'https://assets.hardcover.app/external_data/4106473/1bfbef590457c99c7ae896e33b8162db6648d67f.jpeg', 'As a magical revolution remakes a city, an ancient evil is awakened in a brilliant novel from the Hugo-nominated author of Foundryside and the Divine Cities trilogy. “An absolutely wild ride . . . Foundryside blew me away, and this is a perfect sequel.”—Amal El-Mohtar, The New York Times Book Review A few years ago, Sancia Grado would’ve happily watched Tevanne burn. Now, she’s hoping to transform her city into something new. Something better. Together with allies Orso, Gregor, and Berenice, she’s about to strike a deadly blow against Tevanne’s cruel robber-baron rulers and wrest power from their hands for the first time in decades. But then comes a terrifying warning: Crasedes Magnus himself, the first of the legendary hierophants, is about to be reborn. And if he returns, Tevanne will be just the first place to feel his wrath. Thousands of years ago, Crasedes was an ordinary man who did the impossible: Using the magic of scriving—the art of imbuing objects with sentience—he convinced reality that he was something more than human. Wielding powers beyond comprehension, he strode the world like a god for centuries, meting out justice and razing empires single-handedly, cleansing the world through fire and destruction—and even defeating death itself. Like it or not, it’s up to Sancia to stop him. But to have a chance in the battle to come, she’ll have to call upon a god of her own—and unlock the door to a scriving technology that could change what it means to be human. And no matter who wins, nothing will ever be the same. The awe-inspiring second installment of the Founders Trilogy, Shorefall returns us to the world Robert Jackson Bennett created in his acclaimed Foundryside . . . and forges it anew.', 496, null, 2020, 441073, (select id from series where hardcover_id = 4975), '2') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Human Division', 'John Scalzi', '1250359546', 'https://assets.hardcover.app/external_data/870512/614808498233a6cb13f2aed49605720c99f861b7.jpeg', 'The people of Earth now know that the human Colonial Union has kept them ignorant of the dangerous universe around them. For generations the CU had defended humanity against hostile aliens, deliberately keeping Earth an ignorant backwater and a source of military recruits. Now the CU''s secrets are known to all. Other alien races have come on the scene and formed a new alliance—an alliance against the Colonial Union. And they''ve invited the people of Earth to join them. For a shaken and betrayed Earth, the choice isn''t obvious or easy.

Against such possibilities, managing the survival of the Colonial Union won''t be easy, either. It will take diplomatic finesse, political cunning…and a brilliant "B Team," centered on the resourceful Lieutenant Harry Wilson, that can be deployed to deal with the unpredictable and unexpected things the universe throws at you when you''re struggling to preserve the unity of the human race.', 433, null, 2013, 441230, (select id from series where hardcover_id = 1048), '5') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Diaspora', 'Greg Egan', '3453161815', 'https://assets.hardcover.app/edition/15602641/ed1b3fec070043a1cd159dbf55829272cadf22fa.jpeg', 'In 2975, the orphan Yatima is grown from a randomly mutated digital mind seed in the conceptory of Konishi polis. Yatima explores the Coalition of Polises, the network of computers where most life in the solar system now resides, and joins a friend, Inoshiro, to borrow an abandoned robot body and meet a thriving community of “fleshers” in the enclave of Atlanta. Twenty-one years later, news arrives from a lunar observatory: gravitational waves from Lac G-1, a nearby pair of neutron stars, show that the Earth is about to be bathed in a gamma-ray flash created by the stars’ collision — an event that was not expected to take place for seven million years. Yatima and Inoshiro return to Atlanta to try to warn the fleshers, but meet suspicion and disbelief. Some lives are saved, but the Earth is ravaged. In the aftermath of the disaster, the survivors resolve to discover the cause of the neutron stars’ premature collision, and they launch a thousand polises into interstellar space in search of answers. This diaspora eventually reaches a planet subtly transformed to encode a message from an older group of travellers: a greater danger than Lac G-1 is imminent, and the only escape route leads beyond the visible universe.', 295, null, 1997, 441710, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Word for World Is Forest', 'Ursula K. Le Guin', '1501257978', 'https://assets.hardcover.app/external_data/48546240/46c68f77957c1d44b63ac4417be290cfad35d207.jpeg', 'When the inhabitants of a peaceful world are conquered by the bloodthirsty yumens, their existence is irrevocably altered. Forced into servitude, the Athsheans find themselves at the mercy of their brutal masters.

Desperation causes the Athsheans, led by Selver, to retaliate against their captors, abandoning their strictures against violence. But in defending their lives, they have endangered the very foundations of their society. For every blow against the invaders is a blow to the humanity of the Athsheans. And once the killing starts, there is no turning back.', 189, null, 1972, 441886, (select id from series where hardcover_id = 1123), '5') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Employees', 'Olga Ravn, Martin Aitken', '9146240926', 'https://assets.hardcover.app/edition/32358205/95c151b56c73ab29aa37acf62dbefc259969f8a2.jpeg', 'Shortlisted for the International Booker prize, The Employees reshuffles a sci-fi voyage into a riotously original existential nightmare.

Funny and doom-drenched, The Employees chronicles the fate of the Six-Thousand Ship. The human and humanoid crew members complain about their daily tasks in a series of staff reports and memos. When the ship takes on a number of strange objects from the planet New Discovery, the crew becomes strangely and deeply attached to them, even as tensions boil toward mutiny, especially among the humanoids.

Olga Ravn’s prose is chilling, crackling, exhilarating, and foreboding. The Employees probes into what makes us human, while delivering a hilariously stinging critique of life governed by the logic of productivity.', 144, null, 2004, 443866, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Warcross', 'Marie Lu', '9877473429', 'https://assets.hardcover.app/edition/16276877/ac3756a98da21ba940faad6beb26d795f38f994d.jpeg', 'From #1 New York Times bestselling author Marie Lu—when a game called Warcross takes the world by storm, one girl hacks her way into its dangerous depths. For the millions who log in every day, Warcross isn’t just a game—it’s a way of life. The obsession started ten years ago and its fan base now spans the globe, some eager to escape from reality and others hoping to make a profit. Struggling to make ends meet, teenage hacker Emika Chen works as a bounty hunter, tracking down Warcross players who bet on the game illegally. But the bounty-hunting world is a competitive one, and survival has not been easy. To make some quick cash, Emika takes a risk and hacks into the opening game of the international Warcross Championships—only to accidentally glitch herself into the action and become an overnight sensation. Convinced she’s going to be arrested, Emika is shocked when instead she gets a call from the game’s creator, the elusive young billionaire Hideo Tanaka, with an irresistible offer. He needs a spy on the inside of this year’s tournament in order to uncover a security problem . . . and he wants Emika for the job. With no time to lose, Emika’s whisked off to Tokyo and thrust into a world of fame and fortune that she’s only dreamed of. But soon her investigation uncovers a sinister plot, with major consequences for the entire Warcross empire. In this sci-fi thriller, #1 New York Times bestselling author Marie Lu conjures an immersive, exhilarating world where choosing who to trust may be the biggest gamble of all.', 370, null, 2017, 444070, (select id from series where hardcover_id = 1716), '1') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('A Tree Grows in Brooklyn', 'Betty Smith', '0060801263', 'https://assets.hardcover.app/book_mappings/7333021/0b43734baa588dec6c20c5f4e1dbb367405b913c.jpeg', 'The beloved American classic about a young girl''s coming-of-age at the turn of the century, Betty Smith''s A Tree Grows in Brooklyn is a poignant and moving tale filled with compassion and cruelty, laughter and heartache, crowded with life and people and incident. The story of young, sensitive, and idealistic Francie Nolan and her bittersweet formative years in the slums of Williamsburg has enchanted and inspired millions of readers for more than sixty years. By turns overwhelming, sublime, heartbreaking, and uplifting, the daily experiences of the unforgettable Nolans are raw with honesty and tenderly threaded with family connectedness -- in a work of literary art that brilliantly captures a unique time and place as well as incredibly rich moments of universal experience.', 509, null, 1943, 444413, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Sophie''s World', 'Jostein Gaarder, Paulette Møller', '1858815304', 'https://assets.hardcover.app/edition/1496515/29a79c02e8e60bdfcbc92cfef7467cad7f7432e1.jpeg', 'The international bestseller about life, the universe and everything. ''A simply wonderful, irresistible book'' DAILY TELEGRAPH ''A terrifically entertaining and imaginative story wrapped round its tough, thought-provoking philosophical heart'' DAILY MAIL ''Remarkable ... an extraordinary achievement'' SUNDAY TIMES When 14-year-old Sophie encounters a mysterious mentor who introduces her to philosophy, mysteries deepen in her own life. Why does she keep getting postcards addressed to another girl? Who is the other girl? And who, for that matter, is Sophie herself? To solve the riddle, she uses her new knowledge of philosophy, but the truth is far stranger than she could have imagined. An addictive blend of mystery, philosophy and fantasy, Sophie''s World is an international phenomenon which has been translated into 60 languages and sold more than 40 million copies.', 435, null, 1905, 444952, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Her Body and Other Parties', 'Carmen Maria Machado', '3608115293', 'https://assets.hardcover.app/external_data/60032229/7efc4be73aa99c3b63587614afb4ff34a1150e19.jpeg', 'In Her Body and Other Parties, Carmen Maria Machado blithely demolishes the arbitrary borders between psychological realism and science fiction, comedy and horror, fantasy and fabulism. While her work has earned her comparisons to Karen Russell and Kelly Link, she has a voice that is all her own. In this electric and provocative debut, Machado bends genre to shape startling narratives that map the realities of women’s lives and the violence visited upon their bodies.

A wife refuses her husband’s entreaties to remove the green ribbon from around her neck. A woman recounts her sexual encounters as a plague slowly consumes humanity. A salesclerk in a mall makes a horrifying discovery within the seams of the store’s prom dresses. One woman’s surgery-induced weight loss results in an unwanted houseguest. And in the bravura novella “Especially Heinous,” Machado reimagines every episode of Law & Order: Special Victims Unit, a show we naïvely assumed had shown it all, generating a phantasmagoric police procedural full of doppelgängers, ghosts, and girls with bells for eyes.

Earthy and otherworldly, antic and sexy, queer and caustic, comic and deadly serious, Her Body and Other Parties swings from horrific violence to the most exquisite sentiment. In their explosive originality, these stories enlarge the possibilities of contemporary fiction.', 245, null, 2017, 445010, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('When We Cease to Understand the World', 'Benjamín Labatut, Adrian Nathan West', '1782278672', 'https://assets.hardcover.app/external_data/59508430/ada95f71e07752b30ae3ffc5c41025355ae56d90.jpeg', 'SELECTED FOR BARACK OBAMA’S SUMMER READING LIST ‘A monstrous and brilliant book’ Philip Pullman ‘Wholly mesmerising and revelatory... Completely fascinating’ William Boyd Sometimes discovery brings destruction When We Cease to Understand the World shows us great minds striking out into dangerous, uncharted terrain. Fritz Haber, Alexander Grothendieck, Werner Heisenberg, Erwin Schrödinger: these are among the luminaries into whose troubled lives we are thrust as they grapple with the most profound questions of existence. They have strokes of unparalleled genius, they alienate friends and lovers, they descend into isolated states of madness. Some of their discoveries revolutionise our world for the better; others pave the way to chaos and unimaginable suffering. The lines are never clear. With breakneck pace and wondrous detail, Benjamín Labatut uses the imaginative resources of fiction to break open the stories of scientists and mathematicians who expanded our notions of the possible.', 192, null, 2019, 445032, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('2010: Odyssey Two', 'Arthur C. Clarke', '7208073996', 'https://assets.hardcover.app/edition/27439238/cb69cfa97041db7ac9f40484c1dc1e10c4b353ee.jpeg', 'Nine years after the disastrous Discovery mission to Jupiter in 2001, a joint U.S.-Soviet expedition sets out to rendezvous with the derelict spacecraft—to search the memory banks of the mutinous computer HAL 9000 for clues to what went wrong…and what became of Commander Dave Bowman.

Without warning, a Chinese expedition targets the same objective, turning the recovery mission into a frenzied race for the precious information Discovery may hold about the enigmatic monolith that orbits Jupiter.

Meanwhile, the being that was once Dave Bowman—the only human to unlock the mystery of the monolith—streaks toward Earth on a vital mission of its own . . . ', 320, null, 1982, 445066, (select id from series where hardcover_id = 1095), '2') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The End of All Things', 'John Scalzi', '0765376105', 'https://assets.hardcover.app/edition/7761996/10317952-L.jpg', 'Humans expanded into space...only to find a universe populated with multiple alien species bent on their destruction. 

Thus was the Colonial Union formed, to help protect us from a hostile universe. The Colonial Union used the Earth and its excess population for colonists and soldiers. It was a good arrangement...for the Colonial Union. Then the Earth said: no more. Now the Colonial Union is living on borrowed time-a couple of decades at most, before the ranks of the Colonial Defense Forces are depleted and the struggling human colonies are vulnerable to the alien species who have been waiting for the first sign of weakness, to drive humanity to ruin. And there''s another problem: A group, lurking in the darkness of space, playing human and alien against each other-and against their own kind -for their own unknown reasons. 

In this collapsing universe, CDF Lieutenant Harry Wilson and the Colonial Union diplomats he works with race against the clock to discover who is behind attacks on the Union and on alien races, to seek peace with a suspicious, angry Earth, and keep humanity''s union intact...or else risk oblivion, and extinction-and the end of all things.', 388, null, 2015, 445089, (select id from series where hardcover_id = 1048), '6') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Yellow Wallpaper', 'Charlotte Perkins Gilman', '3488013383', 'https://assets.hardcover.app/external_data/1883579/e1db42aaa41391d3f0d3ed0fd9a252cd38523c46.jpeg', 'The Yellow Wallpaper (original title: "The Yellow Wall-paper. A Story") is a 6,000-word short story by the American writer Charlotte Perkins Gilman, first published in January 1892 in The New England Magazine. It is regarded as an important early work of American feminist literature, illustrating attitudes in the 19th century toward women''s health, both physical and mental.

Presented in the first person, the story is a collection of journal entries written by a woman whose physician husband (John) has rented an old mansion for the summer. The entries display a spiral into psychosis as the writer tried to solve the mystery of the yellow wallpaper.', 24, null, 1892, 445491, (select id from series where hardcover_id = 142108), '42') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Redwall', 'Brian Jacques, Gary Chalk', '0399247947', 'https://assets.hardcover.app/external_data/59527612/8b4856fb55491a634a59b660268a023cbc634e73.jpeg', 'A quest to recover a legendary lost weapon by bumbling young apprentice monk, mouse Matthias.

Redwall Abbey, tranquil home to a community of peace-loving mice, is threatened by Cluny the Scourge savage bilge rat warlord and his battle-hardened horde. But the Redwall mice and their loyal woodland friends combine their courage and strength.', 351, null, 1986, 445501, (select id from series where hardcover_id = 5759), '1') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Gone', 'Michael Grant', '850140487X', 'https://assets.hardcover.app/edition/29020461/c94a154c900eaa03a47afaad07e378c30c5c8b13.jpeg', 'Cut off from the outside world, those that are left are trapped, and there’s no help on the way. 

Sam Temple and his friends must do all they can to survive. Chaos rules the streets. Gangs begin to form. Sides are chosen – strong or weak. Cruel or humane. 

And then there are those who begin to develop powers… ', 576, null, 2008, 445506, (select id from series where hardcover_id = 8751), '1') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Bone Ships', 'RJ Barker', '1405543604', 'https://assets.hardcover.app/external_data/46795709/794c23b0d9ae3f6cf0675c3f8a359dcc04ec1924.jpeg', 'A brilliantly imagined saga of honor, glory, and warfare, The Bone Ships is the epic launch of a new fantasy from David Gemmell Award-nominated RJ Barker. Two nations at war. One prize beyond compare. For generations, the Hundred Isles have built their ships from the bones of ancient dragons to fight an endless war. The dragons disappeared, but the battles for supremacy persisted. Now the first dragon in centuries has been spotted in far-off waters, and both sides see a chance to shift the balance of power in their favour. Because whoever catches it will win not only glory, but the war. Praise for The Bone Ships: "A vividly realized high-seas epic that pulls you deep into its world and keeps you tangled there until the very last word." --Evan Winter, author of The Rage of Dragons "The Bone Ships is excellent. Aside from the standout writing, it''s one of the most interesting and original fantasy worlds I''ve seen in years." --Adrian Tchaikovsky, Arthur C. Clarke Award-winning author The Tide Child TrilogyThe Bone Ships For more from RJ Barker, check out: The Wounded KingdomAge of AssassinsBlood of AssassinsKing of Assassins', 512, null, 2019, 445515, (select id from series where hardcover_id = 2833), '1') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Sufficiently Advanced Magic', 'Andrew Rowe', '1772303321', 'https://assets.hardcover.app/edition/28680284/5df1f2f6806ffda2ab3f5b3c14dc56cca086ef21.jpeg', 'Five years ago, Corin Cadence’s brother entered the Serpent Spire — a colossal tower with ever-shifting rooms, traps, and monsters. Those who survive the spire’s trials return home with an attunement: a mark granting the bearer magical powers. According to legend, those few who reach the top of the tower will be granted a boon by the spire’s goddess.

He never returned.

Now, it’s Corin’s turn. He’s headed to the top floor, on a mission to meet the goddess.

If he can survive the trials, Corin will earn an attunement, but that won’t be sufficient to survive the dangers on the upper levels. For that, he’s going to need training, allies, and a lot of ingenuity.

The journey won’t be easy, but Corin won’t stop until he gets his brother back.', 623, null, 2017, 445659, (select id from series where hardcover_id = 5985), '1') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Last Command', 'Timothy Zahn', '5041752672', 'https://assets.hardcover.app/edition/31792709/df3091b27a28a50caad851e1781df410449933ae.jpeg', 'The conclusion to the epic adventure begun in the number one New York Times bestselling Heir to the.Empire and continued in Dark Force Rising, this final volume spans a galaxy in flames, as the Empire threatens to engulf the New Republic and its brave defenders.

THE LAST COMMAND
The embattled Republic reels from the attacks of Grand Admiral Thrawn, who has marshaled the remnants of the Imperial forces and driven the Rebels back with an abominable technology recovered from the Emperor''s secret fortress: clone soldiers. As Thrawn'' mounts his final siege, Han and Chewbacca struggle to form a coalition of smugglers for a last-ditch attack against the Empire, while Leia holds the Alliance together and prepares for the birth of her Jedi twins. Overwhelmed by the ships and clones at Thrawn''s command, the Republic has one last hope -- sending a small force, led by Luke Skywalker, into the very stronghold that houses Thrawn''s terrible cloning machines.

There a final danger awaits, as the Dark Jedi C''baoth directs the battle against the Rebels and builds his strength to finish what he had already started: the destruction of Luke Skywalker.', 496, null, 1993, 445807, (select id from series where hardcover_id = 1110), '3') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Lions of Al-Rassan', 'Guy Gavriel Kay', '8498004640', 'https://assets.hardcover.app/edition/16437269/33339-L.jpg', 'The ruling Asharites have come from the desert sands, worshipping the stars, their warrior blood fierce and pure. But over centuries, seduced by the sensuous pleasures of their new land, that stern piety has eroded. The Asharies empire has splintered into decadent city-states lead by warring petty kinds.

King Almalik of Cartada is on the ascendancy, adding city after city to his realm, even though Cartada is threatened by forces both within and without. Almalik is aided by his friend and advisor, the notorious Ammar ibn Khairan -- poet, diplomat, soldier -- until a summer afternoon of savage brutality changes their relationship forever.

Meanwhile, in the north, the Jaddite’s most celebrated -- and feared -- military leader, Rodrigo Belmonte, is driven into exile in the wake of events following the death of the king he loved. Rodrigo leads his mercenary company south, to the dangerous lands of Al-Rassan.

In the exquisite lakeside city of Ragosa, Rodrigo Belmonte and Ammar ibn Kharian meet and serve -- for a time -- the same master. Sharing the interwoven fate of these two men from different worlds -- and increasingly torn in her feelings -- is Jehane, the beautiful, accomplished court physician, whose own skills play an increasing role as Al-Rassan is swept to the brink of holy war, and beyond.', 530, null, 1995, 445946, (select id from series where hardcover_id = 218981), '4') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Silverthorn', 'Raymond E. Feist', '0007552017', 'https://assets.hardcover.app/edition/30457709/5ef6c0c7d97d25ceebe6d29832cbf509b484e601.jpeg', 'With the Kingdom of the Isles at peace, Prince Arutha can at last look forward to marrying the Princess Anita in the city of Krondor.

But the capital in the west harbours many shadows. When Jimmy the Hand, a young thief in the Guild of Mockers, upsets an assassination attempt on Arutha, a sinister plot is uncovered.

As the dead rise and assassins stalk the darkness, Arutha must rally the Kingdom forces swiftly if he is to save his beautiful princess felled by a poisoned arrow on her wedding day, and prevent a madman from destroying Midkemia.', 352, null, 1985, 445980, (select id from series where hardcover_id = 1060), '2') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Mad Ship', 'Robin Hobb', '3442249228', 'https://assets.hardcover.app/external_data/603051/3ed42ac2f6a637add6c137eb99772a6f17187c46.jpeg', 'However, Vivacia has been captured by the pirate, ‘King’ Kennit, and is acquiring a keen bloodlust.

Bingtown becomes embroiled in a violent political upheaval against the corrupt Jamaillian leader, while the fading fortunes of the Vestrit family lead Malta deeper into the magical secrets of the mysterious Rain Wilds Traders.

Beyond Bingtown, enigmatic wood-carver Amber dreams of re-launching the Paragon, The Mad Ship, despite the history of death and despair that surrounds him.

Secrets will be revealed – secrets forgotten by sea serpents, hidden by the disfigured Wild Rain Traders, buried deep in wizardwood coffins – secrets with startling, dramatic consequences.', 906, null, 1998, 446127, (select id from series where hardcover_id = 5991), '2') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Exile', 'R. A. Salvatore', '0786931264', 'https://assets.hardcover.app/edition/20930101/ffe71627b120a208f7aea65af8419137e7314b30.jpeg', 'As I became a creature of the empty tunnels, survival became easier and more difficult all at once. I gained in the physical skills and experience necessary to live on. I could defeat almost anything that wandered into my chosen domain. It did not take me long, however, to discover one nemesis that I could neither defeat nor flee. It followed me wherever I went--indeed, the farther I ran, the more it closed in around me. My enemy was solitude, the interminable, incessant silence of hushed corridors.--Drizzt Do''UrdenFrom the Paperback edition.

----------


**This book is in the following series:**
 
 - Forgotten Realms
 - The Legend Of Drizzt | Book 2
 -  Dark Elf trilogy | Book 2', 343, null, 1990, 446224, (select id from series where hardcover_id = 5806), '2') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Chasm City', 'Alastair Reynolds', '0441010644', 'https://assets.hardcover.app/external_data/29346967/47f03d16d04f1c573ca2e595c1d96e638e378002.jpeg', 'Tanner Mirabel ventures through the dark underside of Chasm City, a once utopian city overrun by a vicious virus known as the Melding Plague, in pursuit of a lowlife postmortal and comes face to face with a centuries-old atrocity that everyone would do anything to keep hidden. Reprint.', 694, null, 2001, 446283, (select id from series where hardcover_id = 5563), '0.5') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('I Shall Wear Midnight', 'Terry Pratchett', '0061433047', 'https://assets.hardcover.app/edition/31705970/88dde0b2915e44f8a794644b46cb2af158e78de5.jpeg', 'As the witch of the Chalk, Tiffany Aching performs the distinctly unglamorous work of caring for the needy. But someone – or something – is inciting fear, generating dark thoughts and angry murmurs against witches.

Tiffany must find the source of unrest and defeat the evil at its root. Aided by the tiny-but-tough Wee Free Men, Tiffany faces a dire challenge, for if she falls, the whole Chalk falls with her . . .', 416, null, 2010, 446288, (select id from series where hardcover_id = 1018), '38') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Matter', 'Iain M. Banks', '1841494194', 'https://assets.hardcover.app/external_data/27598148/07283a76322b7ed8fd91bf65ad85f692d64f9d1a.jpeg', 'In a world renowned even within a galaxy full of wonders, a crime within a war. For one brother it means a desperate flight, and a search for the one - maybe two - people who could clear his name. For his brother it means a life lived under constant threat of treachery and murder. And for their sister, even without knowing the full truth, it means returning to a place she''d thought abandoned forever. Only the sister is not what she once was; Djan Seriy Anaplian has changed almost beyond recognition to become an agent of the Culture''s Special Circumstances section, charged with high-level interference in civilisations throughout the greater galaxy. Concealing her new identity - and her particular set of abilities - might be a dangerous strategy, however. In the world to which Anaplian returns, nothing is quite as it seems; and determining the appropriate level of interference in someone else''s war is never a simple matter. MATTER is a novel of dazzling wit and serious purpose. An extraordinary feat of storytelling and breathtaking invention on a grand scale, it is a tour de force from a writer who has turned science fiction on its head.', 593, null, 2008, 446312, (select id from series where hardcover_id = 1102), '8') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Snuff', 'Terry Pratchett', '0062011847', 'https://assets.hardcover.app/edition/32195811/761a7441bfb256053c11aa0b742350b3b200f8d6.jpeg', 'It is a truth universally acknowledged that a policeman taking a holiday would barely have had time to open his suitcase before he finds his first corpse.

Commander Sam Vimes of the Ankh-Morpork City Watch is on holiday in the pleasant and innocent countryside, but not for him a mere body in the wardrobe. There are many, many bodies - and an ancient crime more terrible than murder.

He is out of his jurisdiction, out of his depth, out of bacon sandwiches; and out of his mind. But never out of guile. Where there is a crime there must be a punishment.

They say that in the end all sins are forgiven.

Vimes is about to uncover the exception. ', 480, null, 2011, 446319, (select id from series where hardcover_id = 1018), '39') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('A Hat Full of Sky', 'Terry Pratchett, Paul Kidby', '1787620573', 'https://assets.hardcover.app/edition/31705912/7f80c80512dfbb992450f6f907ff687697b91eed.jpeg', 'Something is coming after Tiffany ...Tiffany Aching is ready to begin her apprenticeship in magic. She expects spells and magic -- not chores and ill-tempered nanny goats! Surely there must be more to witchcraft than this!What Tiffany doesn''t know is that an insidious, disembodied creature is pursuing her. This time, neither Mistress Weatherwax (the greatest witch in the world) nor the fierce, six-inch-high Wee Free Men can protect her. In  the end, it will take all of Tiffany''s inner strength to save herself ... if it can be done at all.A Story of Discworld', 352, null, 2004, 446322, (select id from series where hardcover_id = 1018), '32') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Peace Talks', 'Jim Butcher', '1101991062', 'https://assets.hardcover.app/external_data/59738498/edb1be8d1015aeab2f7c04229b5878ba576e9fd7.jpeg', 'When the Supernatural nations of the world meet up to negotiate an end to ongoing hostilities, Harry Dresden, Chicago''s only professional wizard, joins the White Council''s security team to make sure the talks stay civil. But can he succeed, when dark political manipulations threaten the very existence of Chicago—and all he holds dear?', 455, null, 2020, 446523, (select id from series where hardcover_id = 990), '16') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Blackflame', 'Travis Baldree, Will Wight', '1943363412', 'https://assets.hardcover.app/external_data/23389364/ce2a5a67ae87ca5629bc50b79222c25d1bf92f3e.jpeg', 'Lindon has a year left.

When his time runs out, he’ll have to fight an opponent that no one believes he can beat. Unless he learns the magic of the sacred arts the right way, from scratch, he won’t have a chance to win…and even then, the odds are against him.

In the course of their training, Lindon and Yerin travel to the Blackflame Empire, where they struggle to master an ancient power. Success means a chance at life, but failure means death.

In the sacred arts, only those who risk the most can travel far.', 370, null, 2017, 446665, (select id from series where hardcover_id = 4968), '3') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Luminous Dead', 'Caitlin Starling', '1982625686', 'https://assets.hardcover.app/external_data/37181219/f27bb1b661928f6f4bbdcdf1651516255cb598ce.jpeg', 'When Gyre Price lied her way into this expedition, she thought she’d be mapping mineral deposits and that her biggest problems would be cave collapses and gear malfunctions. She also thought that the fat paycheck - enough to get her off-planet and on the trail of her mother - meant she’d get a skilled surface team, monitoring her suit and environment, keeping her safe. Keeping her sane.

Instead, she got Em.

Em sees nothing wrong with controlling Gyre’s body with drugs or withholding critical information to “ensure the smooth operation” of her expedition. Em knows all about Gyre’s falsified credentials and has no qualms using them as a leash - and a lash. And Em has secrets, too....

As Gyre descends, little inconsistencies - missing supplies, unexpected changes in the route, and worst of all, shifts in Em’s motivations - drive her out of her depths. Lost and disoriented, Gyre finds her sense of control giving way to paranoia and anger. On her own in this mysterious, deadly place, surrounded by darkness and the unknown, Gyre must overcome more than just the dangerous terrain and the Tunneler that calls underground its home if she wants to make it out alive - she must confront the ghosts in her own head.

But how come she can’t shake the feeling she’s being followed?', 432, null, 2019, 448080, (select id from series where hardcover_id = 134730), '1') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Half a Soul', 'Olivia Atwater', '6559814785', 'https://assets.hardcover.app/external_data/60186752/a6f84f5aaf4dbe8e0958b2a645ecf89d9b225e7f.jpeg', 'Ever since she was cursed by a faerie, Theodora Ettings has had no sense of fear or embarrassment - a condition which makes her prone to accidental scandal. Dora hopes to be a quiet, sensible wallflower during the London Season - but when the strange, handsome and utterly uncouth Lord Sorcier discovers her condition, she is instead drawn into dangerous and peculiar faerie affairs.

If Dora''s reputation can survive both her curse and her sudden connection with the least-liked man in all of high society, then she may yet reclaim her normal place in the world. . . but the longer Dora spends with Elias Wilder, the more she begins to suspect that one may indeed fall in love, even with only half a soul.

Bridgerton meets Howl''s Moving Castle in this enchanting historical fantasy, where the only thing more meddlesome than faeries is a marriage-minded mother.', 319, null, 2020, 450404, (select id from series where hardcover_id = 6687), '1') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Embassytown', 'China Miéville', '8419260207', 'https://assets.hardcover.app/edition/30469908/d28405471423f011a633066b16c9c821dd8d403f.jpeg', 'Winner of the Locus Award for Best Science Fiction Novel, China Miéville''s astonishing Embassytown is an intelligent and immersive exploration of language in an alien world. Embassytown: a city of contradictions on the outskirts of the universe. Avice is an immerser, a traveller on the immer, the sea of space and time below the everyday, now returned to her birth planet. Here on Arieka, humans are not the only intelligent life, and Avice has a rare bond with the natives, the enigmatic Hosts - who cannot lie. Only a tiny cadre of unique human Ambassadors can speak Language, and connect the two communities. But an unimaginable new arrival has come to Embassytown. And when this Ambassador speaks, everything changes. Catastrophe looms. Avice knows the only hope is for her to speak directly to the alien Hosts. And that is impossible.', 405, null, 2011, 451118, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Lost Apothecary', 'Sarah Penner', '1922626236', 'https://assets.hardcover.app/edition/21373583/56296d40afd83524667821387fc911ffb6d3c8b2.jpeg', 'Rule #1: The poison must never be used to harm another woman.
Rule #2: The names of the murderer and her victim must be recorded in the apothecary’s register.

One cold February evening in 1791, at the back of a dark London alley in a hidden apothecary shop, Nella awaits her newest customer. Once a respected healer, Nella now uses her knowledge for a darker purpose - selling well-disguised poisons to desperate women who would kill to be free of the men in their lives. But when her new patron turns out to be a precocious twelve-year-old named Eliza Fanning, an unexpected friendship sets in motion a string of events that jeopardizes Nella’s world and threatens to expose the many women whose names are written in her register.

In present-day London, aspiring historian Caroline Parcewell spends her tenth wedding anniversary alone, reeling from the discovery of her husband’s infidelity. When she finds an old apothecary vial near the river Thames, she can’t resist investigating, only to realize she’s found a link to the unsolved “apothecary murders” that haunted London over two centuries ago. As she deepens her search, Caroline’s life collides with Nella’s and Eliza’s in a stunning twist of fate - and not everyone will survive.', 320, null, 2021, 454061, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Daughter of Doctor Moreau', 'Silvia Moreno-Garcia, Gisela Chipe', '3809027626', 'https://assets.hardcover.app/external_data/59843024/7ff429482c2aa3ce9eaaf6cfb72674bc25795da1.jpeg', 'FINALIST FOR THE HUGO AWARD • ONE OF THE BEST BOOKS OF THE YEAR: The New York Times Book Review, Time, NPR, Polygon, Tordotcom, Paste, CrimeReads, Booklist

Carlota Moreau: A young woman growing up on a distant and luxuriant estate, safe from the conflict and strife of the Yucatán peninsula. The only daughter of a researcher who is either a genius or a madman.

Montgomery Laughton: A melancholic overseer with a tragic past and a propensity for alcohol. An outcast who assists Dr. Moreau with his experiments, which are financed by the Lizaldes, owners of magnificent haciendas and plentiful coffers.

The hybrids: The fruits of the doctor’s labor, destined to blindly obey their creator and remain in the shadows. A motley group of part human, part animal monstrosities.

All of them live in a perfectly balanced and static world, which is jolted by the abrupt arrival of Eduardo Lizalde, the charming and careless son of Dr. Moreau’s patron, who will unwittingly begin a dangerous chain reaction.

For Moreau keeps secrets, Carlota has questions, and, in the sweltering heat of the jungle, passions may ignite.

The Daughter of Doctor Moreau is both a dazzling historical novel and a daring science fiction journey.', null, null, 2022, 454797, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Hell Followed with Us', 'Andrew Joseph White', '1682634493', 'https://assets.hardcover.app/edition/30409320/3e3d4c96c566768098f30a7bdfdda99e12bf7c1f.jpeg', 'Sixteen-year-old trans boy Benji is on the run from the cult that raised him—the fundamentalist sect that unleashed Armageddon and decimated the world’s population. Desperately, he searches for a place where the cult can’t get their hands on him, or more importantly, on the bioweapon they infected him with.
 
But when cornered by monsters born from the destruction, Benji is rescued by a group of teens from the local Acheson LGBTQ+ Center, affectionately known as the ALC. The ALC’s leader, Nick, is gorgeous, autistic, and a deadly shot, and he knows Benji’s darkest secret: the cult’s bioweapon is mutating him into a monster deadly enough to wipe humanity from the earth once and for all.    
 
Still, Nick offers Benji shelter among his ragtag group of queer teens, as long as Benji can control the monster and use its power to defend the ALC. Eager to belong, Benji accepts Nick’s terms…until he discovers the ALC’s mysterious leader has a hidden agenda, and more than a few secrets of his own. Perfect for fans of Gideon the Ninth and Annihilation.', 416, null, 2022, 454825, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('This Woven Kingdom', 'Tahereh Mafi', '8419252034', 'https://assets.hardcover.app/edition/30640045/0bd052b9a3a40f4200ff09db2ca9965c6e3b68ac.jpeg', 'Instant #1 International bestseller! Clashing empires, forbidden romance, and a long-forgotten queen destined to save her people—Tahereh Mafi’s first in an epic, romantic trilogy inspired by Persian mythology.
To all the world, Alizeh is a disposable servant, not the long-lost heir to an ancient Jinn kingdom forced to hide in plain sight.

The crown prince, Kamran, has heard the prophecies foretelling the death of his king. But he could never have imagined that the servant girl with the strange eyes, the girl he can’t put out of his mind, would one day soon uproot his kingdom—and the world.

Perfect for fans of Leigh Bardugo, Tomi Adeyemi, and Sabaa Tahir, this is the explosive first book in a new fantasy trilogy from the New York Times bestselling and National Book Award-nominated author Tahereh Mafi.', 512, null, 2022, 455128, (select id from series where hardcover_id = 6007), '1') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Book of Night', 'Holly Black', '1250863678', 'https://assets.hardcover.app/external_data/61208377/c2752cd742d57caa2a18d092fcba1b4f106ea4ea.jpeg', 'Charlie Hall has never found a lock she couldn’t pick, a book she couldn’t steal, or a bad decision she wouldn’t make.

She''s spent half her life working for gloamists, magicians who manipulate shadows to peer into locked rooms, strangle people in their beds, or worse. Gloamists guard their secrets greedily, creating an underground economy of grimoires. And to rob their fellow magicians, they need Charlie Hall.

Now, she’s trying to distance herself from past mistakes, but getting out isn’t easy. Bartending at a dive, she’s still entirely too close to the corrupt underbelly of the Berkshires. Not to mention that her sister Posey is desperate for magic, and that Charlie''s shadowless, and possibly soulless, boyfriend has been hiding things from her. When a terrible figure from her past returns, Charlie descends into a maelstrom of murder and lies.

Determined to survive, she’s up against a cast of doppelgangers, mercurial billionaires, gloamists, and the people she loves best in the world―all trying to steal a secret that will give them vast and terrible power.', 320, null, 2022, 455632, (select id from series where hardcover_id = 180050), '1') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Girl Who Fell Beneath the Sea', 'Axie Oh', '8804756225', 'https://assets.hardcover.app/external_data/61124256/fc0f574dc2fc1c4e3ce3d98fbe0fa8438613a6fd.jpeg', 'Deadly storms have ravaged Mina’s homeland for generations. Floods sweep away entire villages, while bloody wars are waged over the few remaining resources. Her people believe the Sea God, once their protector, now curses them with death and despair. In an attempt to appease him, each year a beautiful maiden is thrown into the sea to serve as the Sea God’s bride, in the hopes that one day the “true bride” will be chosen and end the suffering.

Many believe that Shim Cheong, the most beautiful girl in the village—and the beloved of Mina’s older brother Joon—may be the legendary true bride. But on the night Cheong is to be sacrificed, Joon follows Cheong out to sea, even knowing that to interfere is a death sentence. To save her brother, Mina throws herself into the water in Cheong’s stead.

Swept away to the Spirit Realm, a magical city of lesser gods and mythical beasts, Mina seeks out the Sea God, only to find him caught in an enchanted sleep. With the help of a mysterious young man named Shin—as well as a motley crew of demons, gods and spirits—Mina sets out to wake the Sea God and bring an end to the killer storms once and for all.

But she doesn’t have much time: A human cannot live long in the land of the spirits. And there are those who would do anything to keep the Sea God from waking…', 336, null, 2022, 455793, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Fool''s Quest', 'Robin Hobb', '0007444249', 'https://assets.hardcover.app/external_data/4052652/133ecbfb15713011b9a92b8fb4d3dfa00f160da5.jpeg', '(Duplicate)', 753, null, 2015, 458644, (select id from series where hardcover_id = 6001), '2') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Swordheart', 'T. Kingfisher', '1614504636', 'https://assets.hardcover.app/edition/31659050/1930c501-3cdc-46a2-8d0c-656ed8cc919f.jpg', '"Unfortunately, she is also saddled with money-hungry relatives full of devious plans for how to wrest the inheritance away from her.

While locked in her bedroom, Halla inspects the ancient sword that''s been collecting dust on the wall since before she moved in. Out of desperation, she unsheathes it―and suddenly a man appears. His name is Sarkis, he tells her, and he is an immortal warrior trapped in a prison of enchanted steel.

Sarkis is sworn to protect whoever wields the sword, and for Halla―a most unusual wielder―he finds himself fending off not grand armies and deadly assassins but instead everything from kindly-seeming bandits to roving inquisitors to her own in-laws. But as Halla and Sarkis grow closer, they overlook the biggest threat of all―the sword itself."-- Provided by Amazon', 448, null, 2018, 459108, (select id from series where hardcover_id = 172694), '1') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('City of Dragons', 'Robin Hobb', '229015539X', 'https://assets.hardcover.app/edition/31809025/a4bbe27933ace32d6ffca02ad1bc6885af31e566.jpeg', 'New York Times bestselling author Robin Hobb returns to world of the Rain Wilds—called "one of the most gripping settings in modern fantasy" (Booklist)—in her epic fantasy adventure, City of Dragons. Continuing the enthralling journey she began in her acclaimed Dragon Keeper and Dragon Haven, Hobb rejoins a small group of weak, half-formed and unwanted dragons and their displaced human companions as they search for Kelsingra, a legendary sanctuary woven into the lore of the Elderlings. Now, as the misfit band approaches its final destination, dragons and keepers alike face a challenge so insurmountable that it threatens to render their long, difficult odyssey utterly meaningless. Touching, powerful, and dazzlingly inventive, Hobb’s City of Dragons is not to be missed—further proof that this author belongs alongside Raymond E. Feist, Terry Brooks, and Lois McMaster Bujold in the pantheon of fantasy fiction’s true greats.', 352, null, 2011, 459207, (select id from series where hardcover_id = 6193), '3') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Golden Enclaves', 'Naomi Novik', '0593158377', 'https://assets.hardcover.app/edition/30391820/3c95452c9fb481321be195ed313e5ecd0c3599cf.jpeg', 'The one thing you never talk about while you’re in the Scholomance is what you’ll do when you get out. Not even the richest enclaver would tempt fate that way. But it’s all we dream about: the hideously slim chance we’ll survive to make it out the gates and improbably find ourselves with a life ahead of us, a life outside the Scholomance halls.

And now the impossible dream has come true. I’m out, we’re all out—and I didn’t even have to turn into a monstrous dark witch to make it happen. So much for my great-grandmother’s prophecy of doom and destruction. I didn’t kill enclavers, I saved them. Me and Orion and our allies. Our graduation plan worked to perfection: We saved everyone and made the world safe for all wizards and brought peace and harmony to all the enclaves everywhere.

Ha, only joking! Actually, it’s gone all wrong. Someone else has picked up the project of destroying enclaves in my stead, and probably everyone we saved is about to get killed in the brewing enclave war. And the first thing I’ve got to do now, having miraculously gotten out of the Scholomance, is turn straight around and find a way back in.', 347, null, 2022, 459821, (select id from series where hardcover_id = 1031), '3') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Raising Steam', 'Terry Pratchett', '1448171199', 'https://assets.hardcover.app/edition/31582364/23583500013cb1119e70732c9bd85b8458c818a2.jpeg', 'As head of the Royal Bank and Post Office of Ankh-Morpork, he doesn''t really want or need another job. But when the Patrician, Lord Vetinari, gives you a task, you do it or suffer the consequences. In Moist''s case, death.

A brand-new invention has come to the city: a steam locomotive named Iron Girder, to be precise. With the railway''s introduction and rapid expansion, Vetinari enlists Moist to represent the government and keep things on track.

But as with all new technology, some people have objections, and Moist will have to use every trick in his arsenal to keep the trains running . . .

Raising Steam is the third and final book in the Industrial Revolution series, but the Discworld novels can be read in any order.', 480, null, 2013, 463511, (select id from series where hardcover_id = 1018), '40') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('A River Enchanted', 'Rebecca Ross', '6552260067', 'https://assets.hardcover.app/edition/30628386/12ebf132-a454-49e6-a03a-3b3bc1ebf612.jpg', 'Set on the magical isle of Cadence where two childhood enemies must team up to discover why girls are going missing from their clan. Jack Tamerlaine hasn’t stepped foot on Cadence in ten long years, content to study music at the mainland university. But when young girls start disappearing from the isle, Jack is summoned home to help find them. Enchantments run deep on Cadence: gossip is carried by the wind, plaid shawls can be as strong as armor, and the smallest cut of a knife can instill fathomless fear. The capricious spirits that rule the isle by fire, water, earth, and wind find mirth in the lives of the humans who call the land home. 

Adaira, heiress of the east and Jack’s childhood enemy, knows the spirits only answer to a bard’s music, and she hopes Jack can draw them forth by song, enticing them to return the missing girls. As Jack and Adaira reluctantly work together, they find they make better allies than rivals as their partnership turns into something more. But with each passing song, it becomes apparent the trouble with the spirits is far more sinister than they first expected, and an older, darker secret about Cadence lurks beneath the surface, threatening to undo them all. With unforgettable characters, a fast-paced plot, and compelling world building, A River Enchanted is a stirring story of duty, love, and the power of true partnership, and marks Rebecca Ross’s brilliant entry on the adult fantasy stage.', 496, null, 2022, 463698, (select id from series where hardcover_id = 1938), '1') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('When Women Were Dragons', 'Kelly Barnhill', '8408260316', 'https://assets.hardcover.app/external_data/944005/463bf37b4da21bc0d607bd2bbe6262a62597b369.jpeg', 'In the first adult novel by the New York Times bestselling author of The Ogress and The Orphans, Alex Green is a young girl in a world much like ours, except for its most seminal event: the Mass Dragoning of 1955, when hundreds of thousands of ordinary wives and mothers sprouted wings, scales, and talons; left a trail of fiery destruction in their path; and took to the skies. Was it their choice? What will become of those left behind? Why did Alex’s beloved aunt Marla transform but her mother did not? Alex doesn’t know. It’s taboo to speak of.
 
Forced into silence, Alex nevertheless must face the consequences of this astonishing event: a mother more protective than ever; an absentee father; the upsetting insistence that her aunt never even existed; and 
watching her beloved cousin Bea become dangerously obsessed with the forbidden.

In this timely and timeless speculative novel, award-winning author Kelly Barnhill boldly explores rage, memory, and the tyranny of forced limitations. When Women Were Dragons exposes a world that wants to keep women small—their lives and their prospects—and examines what happens when they rise en masse and take up the space they deserve.', 352, null, 2022, 465142, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Amazing Adventures of Kavalier & Clay', 'Michael Chabon', '0008229244', 'https://assets.hardcover.app/edition/30385746/96cdd59ef83ad016f0a468bf76f0049bc36ec5da.jpeg', 'A young escape artist and budding magician named Joe Kavalier arrives on the doorstep of his cousin, Sammy Clay. While the long shadow of Hitler falls across Europe, America is happily in thrall to the Golden Age of comic books, and in a distant corner of Brooklyn, Sammy is looking for a way to cash in on the craze. He finds the ideal partner in the aloof, artistically gifted Joe, and together they embark on an adventure that takes them deep into the heart of Manhattan, and the heart of old-fashioned American ambition. From the shared fears, dreams, and desires of two teenage boys, they spin comic book tales of the heroic, fascist-fighting Escapist and the beautiful, mysterious Luna Moth, otherworldly mistress of the night. Climbing from the streets of Brooklyn to the top of the Empire State Building, Joe and Sammy carve out lives, and careers, as vivid as cyan and magenta ink. Spanning continents and eras, this superb book by one of America’s finest writers remains one of the defining novels of our modern American age.', 706, null, 2000, 467910, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Cabin at the End of the World', 'Paul Tremblay', '8377313456', 'https://assets.hardcover.app/book/468176/804a56bb-e56a-4aa2-b0bb-24fa848af123.jpeg', 'Seven-year-old Wen and her parents, Eric and Andrew, are vacationing at a remote cabin on a quiet New Hampshire lake. Their closest neighbors are more than two miles in either direction along a rutted dirt road.

One afternoon, as Wen catches grasshoppers in the front yard, a stranger unexpectedly appears in the driveway. Leonard is the largest man Wen has ever seen but he is young, friendly, and he wins her over almost instantly. Leonard and Wen talk and play until Leonard abruptly apologizes and tells Wen, "None of what’s going to happen is your fault". Three more strangers then arrive at the cabin carrying unidentifiable, menacing objects. As Wen sprints inside to warn her parents, Leonard calls out: "Your dads won’t want to let us in, Wen. But they have to. We need your help to save the world."', 281, null, 2018, 468176, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Assassin''s Fate', 'Robin Hobb', '0553392956', 'https://assets.hardcover.app/edition/31755111/dfdb9dae76c4585404c263d57000affbbcd22463.jpeg', 'NEW YORK TIMES BESTSELLER • The stunning conclusion to Robin Hobb’s Fitz and the Fool trilogy, which began with Fool’s Assassin and Fool’s Quest “Every new Robin Hobb novel is a cause for celebration. Along with millions of her other fans, I delight in every visit to the Six Duchies, the Rain Wilds, and the Out Islands, and can’t wait to see where she’ll take me next.”—George R. R. Martin More than twenty years ago, the first epic fantasy novel featuring FitzChivalry Farseer and his mysterious, often maddening friend the Fool struck like a bolt of brilliant lightning. Now New York Times bestselling author Robin Hobb brings to a momentous close the third trilogy featuring these beloved characters in a novel of unsurpassed artistry that is sure to endure as one of the great masterworks of the genre. Fitz’s young daughter, Bee, has been kidnapped by the Servants, a secret society whose members not only dream of possible futures but use their prophecies to add to their wealth and influence. Bee plays a crucial part in these dreams—but just what part remains uncertain. As Bee is dragged by her sadistic captors across half the world, Fitz and the Fool, believing her dead, embark on a mission of revenge that will take them to the distant island where the Servants reside—a place the Fool once called home and later called prison. It was a hell the Fool escaped, maimed and blinded, swearing never to return. For all his injuries, however, the Fool is not as helpless as he seems. He is a dreamer too, able to shape the future. And though Fitz is no longer the peerless assassin of his youth, he remains a man to be reckoned with—deadly with blades and poison, and adept in Farseer magic. And their goal is simple: to make sure not a single Servant survives their scourge.', 993, null, 2017, 468291, (select id from series where hardcover_id = 6001), '3') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Ballad of Never After', 'Stephanie Garber', '965201527X', 'https://assets.hardcover.app/edition/30438743/22bd108742a5ba0427abf22de149ae644d3dd769.jpeg', 'After Jacks, the Prince of Hearts, betrays her, Evangeline Fox swears she''ll never trust him again. Now that she’s discovered her own magic, Evangeline believes she can use it to restore the chance at happily ever after that Jacks stole away.

But when a new terrifying curse is revealed, Evangeline finds herself entering into a tenuous partnership with the Prince of Hearts again. Only this time, the rules have changed. Jacks isn’t the only force Evangeline needs to be wary of. In fact, he might be the only one she can trust, despite her desire to despise him.

Instead of a love spell wreaking havoc on Evangeline’s life, a murderous spell has been cast. To break it, Evangeline and Jacks will have to do battle with old friends, new foes, and a magic that plays with heads and hearts. Evangeline has always trusted her heart, but this time she’s not sure she can. . . .

Stephanie Garber’s THE BALLAD OF NEVER AFTER is the jaw-dropping sequel to the ONCE UPON A BROKEN HEART, starring Evangeline Fox and the Prince of Hearts on a new journey of magic, mystery, and heartbreak', 403, null, 2022, 469263, (select id from series where hardcover_id = 1411), '2') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Six Crimson Cranes', 'Elizabeth Lim', '9786588343', 'https://assets.hardcover.app/external_data/59799401/9b0a61b1aa9c636152b51dc17ac8501b352a6cb5.jpeg', 'A princess in exile, a shapeshifting dragon, six enchanted cranes, and an unspeakable curse... Drawing from ''The Wild Swans'' and East Asian folklore, this breathtakingly original fantasy from the author of Spin the Dawn is perfect for fans of Leigh Bardugo or Tomi Adeyemi. Shiori''anma, the only princess of Kiata, has a secret. Forbidden magic runs through her veins. Normally she conceals it well, but on the morning of her betrothal ceremony, Shiori loses control. At first, her mistake seems like a stroke of luck, forestalling the wedding she never wanted. But it also catches the attention of Raikama, her stepmother. A sorceress in her own right, Raikama banishes the young princess, turning her brothers into cranes. She warns Shiori that she must speak of it to no one: for with every word that escapes her lips, one of her brothers will die. Penniless, voiceless, and alone, Shiori searches for her brothers, and uncovers a dark conspiracy to seize the throne. Only Shiori can set the kingdom to rights, but to do so she must place her trust in a paper bird, a mercurial dragon, and the very boy she fought so hard not to marry. And she must embrace the magic she''s been taught all her life to forswear--no matter what the cost.', 481, null, 2021, 469338, (select id from series where hardcover_id = 3213), '1') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Wind-Up Bird Chronicle', 'Haruki Murakami, Jay Rubin', '9520424911', 'https://assets.hardcover.app/editions/30387653/7f3a72c2-328a-494c-bfea-0c884f8fcf47.jpg', 'Japan''s most highly regarded novelist now vaults into the first ranks of international fiction writers with this heroically imaginative novel, which is at once a detective story, an account of a disintegrating marriage, and an excavation of the buried secrets of World War II.

In a Tokyo suburb a young man named Toru Okada searches for his wife''s missing cat. Soon he finds himself looking for his wife as well in a netherworld that lies beneath the placid surface of Tokyo. As these searches intersect, Okada encounters a bizarre group of allies and antagonists: a psychic prostitute; a malevolent yet mediagenic politician; a cheerfully morbid sixteen-year-old-girl; and an aging war veteran who has been permanently changed by the hideous things he witnessed during Japan''s forgotten campaign in Manchuria.

Gripping, prophetic, suffused with comedy and menace, The Wind-Up Bird Chronicle is a tour de force equal in scope to the masterpieces of Mishima and Pynchon.', 607, null, 1994, 469816, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Belladonna', 'Adalyn Grace', '6171709093', 'https://assets.hardcover.app/editions/31480077/4802298370070612.jpg', 'Orphaned as a baby, nineteen-year-old Signa has been raised by a string of guardians, each one more interested in her wealth than her well-being—and each has met an untimely end. Her remaining relatives are the elusive Hawthornes, an eccentric family living at Thorn Grove, an estate both glittering and gloomy. Its patriarch mourns his late wife through wild parties, while his son grapples for control of the family’s waning reputation, and his daughter suffers from a mysterious illness. But when their mother’s restless spirit appears claiming she was poisoned, Signa realizes that the family she depends on could be in grave danger and enlists the help of a surly stable boy to hunt down the killer.
 
However, Signa’s best chance of uncovering the murderer is an alliance with Death himself, a fascinating, dangerous shadow who has never been far from her side. Though he’s made her life a living hell, Death shows Signa that their growing connection may be more powerful—and more irresistible—than she ever dared imagine.', 416, null, 2022, 470922, (select id from series where hardcover_id = 3485), '1') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Maidens', 'Alex Michaelides', '125082754X', 'https://assets.hardcover.app/external_data/40674758/285064a5ee4ea66d200f1e35d336cc714aa85fad.jpeg', '"Alex Michaelides’s long-awaited next novel, ''The Maidens,'' is finally here...the premise is enticing and the elements irresistible."
—The New York Times

"A deliciously dark, elegant, utterly compulsive read—with a twist that blew my mind. I loved this even more than I loved The Silent Patient and that''s saying something!"
—Lucy Foley, New York Times bestselling author of The Guest List

From the #1 New York Times bestselling author of The Silent Patient comes a spellbinding tale of psychological suspense, weaving together Greek mythology, murder, and obsession, that further cements “Michaelides as a major player in the field” (Publishers Weekly).

Edward Fosca is a murderer. Of this Mariana is certain. But Fosca is untouchable. A handsome and charismatic Greek tragedy professor at Cambridge University, Fosca is adored by staff and students alike—particularly by the members of a secret society of female students known as The Maidens.

Mariana Andros is a brilliant but troubled group therapist who becomes fixated on The Maidens when one member, a friend of Mariana’s niece Zoe, is found murdered in Cambridge.

Mariana, who was once herself a student at the university, quickly suspects that behind the idyllic beauty of the spires and turrets, and beneath the ancient traditions, lies something sinister. And she becomes convinced that, despite his alibi, Edward Fosca is guilty of the murder. But why would the professor target one of his students? And why does he keep returning to the rites of Persephone, the maiden, and her journey to the underworld?

When another body is found, Mariana’s obsession with proving Fosca’s guilt spirals out of control, threatening to destroy her credibility as well as her closest relationships. But Mariana is determined to stop this killer, even if it costs her everything—including her own life.', 336, null, 2021, 474446, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Of Blood and Fire', 'Ryan  Cahill', '1836980000', 'https://assets.hardcover.app/editions/30397116/8730789054696217.jpg', 'Born in fire. Tempered in blood.

Epheria is a land divided by war and mistrust. The High Lords of the south squabble and fight, only kept in check by the Dragonguard, traitors of a time long past, who serve the empire of the North.

In the remote villages of southern Epheria, still reeling from the tragic loss of his brother, Calen Bryer prepares for The Proving—a test of courage and skill that not all survive.

But when three strangers arrive in the village of Milltown, with a secret they are willing to die for, Calen’s world is ripped from under him and he is thrust headfirst into a war that has been raging for centuries.

There is no prophecy. His coming was not foretold.

He bleeds like any man, and bleed he will.', 494, null, 2021, 475776, (select id from series where hardcover_id = 4979), '1') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Mask of Mirrors', 'M.A. Carrick', '1549190911', 'https://assets.hardcover.app/external_data/4197454/6afa7eefea11b46df8658fe046cd7abfdca33850.jpeg', 'Renata Viraudax is a con artist who has come to the sparkling city of Nadezra--the city of dreams--with one goal: to trick her way into a noble house and secure her fortune and her sister''s future. But as she''s drawn into the elite world of House Traementis, she realizes her masquerade is just one of many surrounding her.', 672, null, 2021, 476479, (select id from series where hardcover_id = 5146), '1') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Final Gambit', 'Jennifer Lynn Barnes', '0316370959', 'https://assets.hardcover.app/editions/30418508/144547674352096-91bgAVuRzFL._SL1500_.jpg', 'To inherit billions, all Avery Kylie Grambs has to do is survive a few more weeks living in Hawthorne House. The paparazzi are dogging her every step. Financial pressures are building. Danger is a fact of life. And the only thing getting Avery through it all is the Hawthorne brothers. Her life is intertwined with theirs. She knows their secrets and they know her.
 
But as the clock ticks down to the moment when Avery will become the richest teenager on the planet, trouble arrives in the form of a visitor who needs her help—and whose presence in Hawthorne House could change everything. It soon becomes clear that there is one last puzzle to solve, and Avery and the Hawthorne brothers are drawn into a dangerous game against an unknown and powerful player.
 
Secrets upon secrets. Riddles upon riddles. In this game, there are hearts and lives at stake—and there is nothing more Hawthorne than winning.', 384, null, 2022, 478573, (select id from series where hardcover_id = 5593), '3') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Our Missing Hearts', 'Celeste Ng', '3423290358', 'https://assets.hardcover.app/external_data/59720462/f152529fd7e3648c93550cef31978360eb27f2d8.jpeg', 'Twelve-year-old Bird Gardner lives a quiet existence with his loving father, a former linguist who now shelves books in a university library. His mother, Margaret, a Chinese American poet, left without a trace when he was nine years old. He doesn’t know what happened to her—only that her books have been banned—and he resents that she cared more about her work than about him.

Then one day Bird receives a mysterious letter containing only a cryptic drawing, and soon he is pulled into a quest to find her. His journey will take him back to the many folktales she poured into his head as a child, through the ranks of an underground network of heroic librarians, and finally to New York City, where he will learn the truth about what happened to his mother and what the future holds for them both.

Our Missing Hearts is an old story made new, of the ways supposedly civilized communities can ignore the most searing injustice. It’s about the lessons and legacies we pass on to our children and the power of art to create change.', 285, null, 2022, 479918, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Tales from the Cafe', 'Toshikazu Kawaguchi', '8367555422', 'https://assets.hardcover.app/edition/30420605/a3086747726e85ad04e448b87c601d51cd48fbf4.jpeg', 'If you could go back in time, who would you want to meet?

In a small back alley of Tokyo, there is a café that has been serving carefully brewed coffee for more than one hundred years. Local legend says that this shop offers something else besides coffee—the chance to travel back in time.

Over the course of one summer, four customers visit the café in the hopes of making that journey. But time travel isn’t so simple, and there are rules that must be followed. Most important, the trip can last only as long as it takes for the coffee to get cold.

Heartwarming, wistful, mysterious and delightfully quirky, Toshikazu Kawaguchi’s internationally bestselling novel explores the age-old question: What would you change if you could travel back in time?', 224, null, 2017, 480625, (select id from series where hardcover_id = 5944), '2') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Remarkably Bright Creatures', 'Shelby Van Pelt', '0063204177', 'https://assets.hardcover.app/external_data/59469142/340246db2f5b43b566a8dfc27887bb13301ca4cd.jpeg', 'After Tova Sullivan''s husband died, she began working the night shift at the Sowell Bay Aquarium, mopping floors and tidying up. Keeping busy has always helped her cope, which she''s been doing since her eighteen-year-old son, Erik, mysteriously vanished on a boat in Puget Sound over thirty years ago.

Tova becomes acquainted with curmudgeonly Marcellus, a giant Pacific octopus living at the aquarium. Marcellus knows more than anyone can imagine but wouldn''t dream of lifting one of his eight arms for his human captors--until he forms a remarkable friendship with Tova.

Ever the detective, Marcellus deduces what happened the night Tova''s son disappeared. And now Marcellus must use every trick his old invertebrate body can muster to unearth the truth for her before it''s too late.

Shelby Van Pelt''s debut novel is a gentle reminder that sometimes taking a hard look at the past can help uncover a future that once felt impossible.', 360, null, 2022, 481892, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Gild', 'Raven Kennedy', '1405955007', 'https://assets.hardcover.app/edition/30425521/89bf83ceb392e97b6974eb3488b17c39a247629e.jpeg', 'The fae abandoned this world to us. And the ones with power rule.

Gold.

Gold floors, gold walls, gold furniture, gold clothes. In Highbell, in the castle built into the frozen mountains, everything is made of gold.

Even me.

King Midas rescued me. Dug me out of the slums and placed me on a pedestal. I''m called his precious. His favored. I''m the woman he Gold-Touched to show everyone that I belong to him. To show how powerful he is. He gave me protection, and I gave him my heart. And even though I don''t leave the confines of the palace, I''m safe.

Until war comes to the kingdom and a deal is struck.

Suddenly, my trust is broken. My love is challenged. And I realize that everything I thought I knew about Midas might be wrong.

Because these bars I''m kept in, no matter how gilded, are still just a cage. But the monsters on the other side might make me wish I''d never left.', 416, null, 2022, 484819, (select id from series where hardcover_id = 17080), '1') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Bright Sword', 'Lev Grossman', '0593833562', 'https://assets.hardcover.app/edition/30425677/6ca7ddd7-683f-45c4-88c8-c7ff761b808a.jpg', 'A gifted young knight named Collum arrives at Camelot to compete for a place at the Round Table, only to find that he’s too late. King Arthur died two weeks ago at the Battle of Camlann, and only a handful of the knights of the Round Table are left.

The survivors aren’t the heroes of legend like Lancelot or Gawain. They’re the oddballs of the Round Table, like Sir Palomides, the Saracen Knight, and Sir Dagonet, Arthur’s fool, who was knighted as a joke. They’re joined by Nimue, who was Merlin’s apprentice until she turned on him and buried him under a hill. 

But it’s up to them to rebuild Camelot in a world that has lost its balance, even as God abandons Britain and the fairies and old gods return, led by Morgan le Fay. They must reclaim Excalibur and make this ruined world whole again—but first they’ll have to solve the mystery of why the lonely, brilliant King Arthur fell. 

The first major Arthurian epic of the new millennium, The Bright Sword is steeped in tradition, complete with duels and quests, battles and tournaments, magic swords and Fisher Kings. It’s also a story about imperfect men and women, full of strength and pain, trying to reforge a broken land in spite of being broken themselves.', 683, null, 2024, 484946, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Demon in White', 'Christopher Ruocchio', '0756413079', 'https://assets.hardcover.app/editions/30865885/1782910108941724.jpg', 'For almost a hundred years, Hadrian Marlowe has served the empire in its war against the Cielcin, a vicious alien race bent on humanity''s destruction. Rumors of a new king among the Cielcin have reached the imperial throne. This one is not like the others. It does not raid borderworld territories, preferring precise, strategic attacks on the humans'' empire.

To make matters worse, a cult of personality has formed around Hadrian, spurred on by legends of his having defied death itself. Men call him Halfmortal. Hadrian''s rise to prominence proves dangerous to himself and his team, as those within the imperial government distrust or resent his new influence.

Caught in the middle, Hadrian must contend with enemies before him and behind.

And above it all, there is the mystery of the Quiet. Hadrian did defy death. He did return. But the keys to the only place in the universe where Hadrian might find the answers he seeks lie in the hands of the emperor himself....', 784, null, 2020, 490388, (select id from series where hardcover_id = 6522), '3') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Hooked', 'Emily McIntire', '9798200894451', 'https://assets.hardcover.app/editions/30438901/8864459204279629.jpeg', '"James has always had one agenda: destroy his enemy, Peter Michaels. When Peter’s twenty-year-old daughter Wendy shows up in James’s bar, he sees his way in. Seduce the girl and use her for his revenge. It’s the perfect plan, until things in James’s organization begin to crumble. Suddenly, he has to find the traitor in his midst, and his plan for revenge gets murkier as James starts to see Wendy as more than just a pawn in his game.

Wendy has been cloistered away most of her life by her wealthy cold father, but a spontaneous night out with friends turns into an intense and addictive love affair with the dark and brooding James. As much as she knows James is dangerous, Wendy can’t seem to shake her desire for him. But as their relationship grows more heated and she learns more about the world he moves in, she finds herself unsure if she’s falling for the man known as James or the monster known as Hook."-- Provided by Amazon', 325, null, 2021, 491366, (select id from series where hardcover_id = 17074), '1') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Eyes of the Void', 'Adrian Tchaikovsky', '9634703445', 'https://assets.hardcover.app/edition/30920092/7f7dce698545976b2a945ec972484156e51fe35e.jpeg', 'After eighty years of fragile peace, the Architects are back, wreaking havoc as they consume entire planets. In the past, Originator artifacts—vestiges of a long-vanished civilization—could save a world from annihilation. This time, the Architects have discovered a way to circumvent these protective relics. Suddenly, no planet is safe.

Facing impending extinction, the Human Colonies are in turmoil. While some believe a unified front is the only way to stop the Architects, others insist humanity should fight alone. And there are those who would seek to benefit from the fractured politics of war—even as the Architects loom ever closer.

Idris, who has spent decades running from the horrors of his past, finds himself thrust back onto the battlefront. As an Intermediary, he could be one of the few to turn the tide of war. With a handful of allies, he searches for a weapon that could push back the Architects and save the galaxy. But to do so, he must return to the nightmarish unspace, where his mind was broken and remade.

What Idris discovers there will change everything.', 608, null, 2022, 496460, (select id from series where hardcover_id = 6015), '2') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Atlas Paradox', 'Olivie Blake', '8419030090', 'https://assets.hardcover.app/external_data/60136554/dfa405f1be6b5850a74a84ab4ec4126fd7e197fb.jpeg', 'Six magicians were presented with the opportunity of a lifetime.
Five are now members of the Society.
Two paths lay before them.

All must pick a side.

Alliances will be tested, hearts will be broken, and The Society of Alexandrians will be revealed for what it is: a secret society with raw, world-changing power, headed by a man whose plans to change life as we know it are already under way.
', 436, null, 2022, 502043, (select id from series where hardcover_id = 5884), '2') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The House Across the Lake', 'Riley Sager', '0593183215', 'https://assets.hardcover.app/external_data/59604697/1fd917b6b82de8e13c5522df90957db907c0085c.jpeg', 'Be careful what you watch for . . . Casey Fletcher, a recently widowed actress trying to escape a streak of bad press, has retreated to the peace and quiet of her family’s lake house in Vermont. Armed with a pair of binoculars and several bottles of bourbon, she passes the time watching Tom and Katherine Royce, the glamorous couple living in the house across the lake. They make for good viewing—a tech innovator, Tom is powerful; and a former model, Katherine is gorgeous. 

One day on the lake, Casey saves Katherine from drowning, and the two strike up a budding friendship. But the more they get to know each other—and the longer Casey watches—it becomes clear that Katherine and Tom’s marriage isn’t as perfect as it appears. When Katherine suddenly vanishes, Casey immediately suspects Tom of foul play. What she doesn’t realize is that there’s more to the story than meets the eye—and that shocking secrets can lurk beneath the most placid of surfaces. 

Packed with sharp characters, psychological suspense, and gasp-worthy plot twists, Riley Sager’s The House Across the Lake is the ultimate escapist read . . . no lake house required.', 368, null, 2022, 502338, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Ordinary Monsters', 'J.M.  Miro', '0771000057', 'https://assets.hardcover.app/edition/30456421/96eaf4b4fe9a644bd97fb6d45595dfc2e118f889.jpeg', 'IN THIS STUNNING HISTORICAL FANTASY, journey to the Victorian era, as children with mysterious powers are hunted by a figure of darkness in a battle of good vs. evil...

"Ordinary Monsters is a towering achievement: a dazzling mountain of wild invention, Dickensian eccentrics, supernatural horrors, and gripping suspense. Be warned... once you step into this penny dreadful to end all penny dreadfuls, you''ll never want to leave." —Joe Hill, #1 New York Times bestselling author of The Fireman and Heart-Shaped Box

Charlie Ovid, despite surviving a brutal childhood in Mississippi, doesn''t have a scar on him. His body heals itself, whether he wants it to or not. Marlowe, a foundling from a railway freight car, shines with a strange bluish light. He can melt or mend flesh. When Alice Quicke, a jaded detective with her own troubled past, is recruited to escort them to safety, all three begin a journey into the nature of difference and belonging, and the shadowy edges of the monstrous.

What follows is a story of wonder and betrayal, from the gaslit streets of London, and the wooden theaters of Meiji-era Tokyo, to an eerie estate outside Edinburgh where other children with gifts—like Komako, a witch-child and twister of dust, and Ribs, a girl who cloaks herself in invisibility—are forced to combat the forces that threaten their safety. There, the world of the dead and the world of the living threaten to collide. With this new found family, Komako, Marlowe, Charlie, Ribs, and the rest of the Talents discover the truth about their abilities. And as secrets within the Institute unfurl, a new question arises: What truly defines a monster?

Riveting in its scope, exquisitely written, Ordinary Monsters presents a catastrophic vision of the Victorian world—and of the gifted, broken children who must save it.', 672, null, 2022, 505708, (select id from series where hardcover_id = 16792), '1') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Haunting Adeline', 'H. D. Carlton', '6581238112', 'https://assets.hardcover.app/editions/30457494/2004678148140760.jpg', '"For Adeline Reilly, moving back to Seattle was supposed to be the perfect fresh start. With her flourishing career as an author, and the inheritance of her late grandmother’s gothic mansion, there is nothing to stand in her way.
But Adeline isn’t alone in Parson’s Manor.
It isn’t the angry souls haunting the hallways of her childhood home that Adeline fears–it’s the mysterious break-ins, roses appearing, and threatening messages that somehow sound more like eerie promises.
Adeline has a stalker.
Yet, she quickly discovers she’s not the first person in her family to fall victim to a shadow in pursuit.
Left behind are her great-grandmother’s haunting journals detailing the story of her own phantom, and subsequently, her brutal murder.
Parson’s Manor now holds more than just Adeline’s memories—it houses a grim future that could lead to history repeating itself.
If she doesn’t fall in love with her stalker first."-- Provided by Amazon', 549, null, 2021, 506421, (select id from series where hardcover_id = 65036), '1') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Twisted Love', 'Ana Huang', '9180007228', 'https://assets.hardcover.app/edition/30803588/9e88e0bc66c8fd950454d2034c38163bab97ca51.jpeg', 'Alex Volkov is a devil blessed with the face of an angel and cursed with a past he can’t escape.

Driven by a tragedy that has haunted him for most of his life, his ruthless pursuits for success and vengeance leave little room for matters of the heart.

But when he’s forced to look after his best friend’s sister, he starts to feel something in his chest:

A crack.
A melt.
A fire that could end his world as he knew it.

***

Ava Chen is a free spirit trapped by nightmares of a childhood she can’t remember.

But despite her broken past, she’s never stopped seeing the beauty in the world…including the heart beneath the icy exterior of a man she shouldn’t want.

Her brother’s best friend.
Her neighbor.
Her savior and her downfall.

Theirs is a love that was never supposed to happen—but when it does, it unleashes secrets that could destroy them both…and everything they hold dear.', 343, null, 2021, 506453, (select id from series where hardcover_id = 17079), '1') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Kingdoms of Death', 'Christopher Ruocchio', '9791028115395', 'https://assets.hardcover.app/edition/31464338/6576b979-c946-422d-aafe-e90ad56c61a1.jpg', 'Hadrian Marlowe is trapped.

For nearly a century, he has been a guest of the Emperor, forced into the role of advisor, a prisoner of his own legend. But the war is changing. Mankind is losing.

The Cielcin are spilling into human space from the fringes, picking their targets with cunning precision. The Great Prince Syriani Dorayaica is uniting their clans, forging them into an army and threat the likes of which mankind has never seen.

And the Empire stands alone.

Now the Emperor has no choice but to give Hadrian Marlowe—once his favorite knight—one more impossible task: journey across the galaxy to the Lothrian Commonwealth and convince them to join the war. But not all is as it seems, and Hadrian’s journey will take him far beyond the Empire, beyond the Commonwealth, impossibly deep behind enemy lines.', 531, null, 2022, 506931, (select id from series where hardcover_id = 6522), '4') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Red God', 'Pierce Brown', null, null, null, null, null, null, 507636, (select id from series where hardcover_id = 1033), '7') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('A House With Good Bones', 'T. Kingfisher', '125082981X', 'https://assets.hardcover.app/editions/30464612/3472232296846980-60784409.jpg', '"Her brother''s words echo in Sam Montgomery''s ear as she turns onto the quiet North Carolina street where their mother lives alone.

She brushes the thought away as she climbs the front steps. Sam''s excited for this rare extended visit, and looking forward to nights with just the two of them, drinking boxed wine, watching murder mystery shows, and guessing who the killer is long before the characters figure it out.

But stepping inside, she quickly realizes home isn’t what it used to be. Gone is the warm, cluttered charm her mom is known for; now the walls are painted a sterile white. Her mom jumps at the smallest noises and looks over her shoulder even when she’s the only person in the room. And when Sam steps out back to clear her head, she finds a jar of teeth hidden beneath the magazine-worthy rose bushes, and vultures are circling the garden from above.

To find out what’s got her mom so frightened in her own home, Sam will go digging for the truth. But some secrets are better left buried."-- Provided by Amazon', 247, null, 2023, 512318, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('City of Last Chances', 'Adrian Tchaikovsky', '1801108439', 'https://assets.hardcover.app/external_data/60226204/42c9e851f1e1c1fe2c9c438f1890634f155b4dcb.jpeg', 'There has always been a darkness to Ilmar, but never more so than now. The city chafes under the heavy hand of the Palleseen occupation, the choke-hold of its criminal underworld, the boot of its factory owners, the weight of its wretched poor and the burden of its ancient curse.

What will be the spark that lights the conflagration?

Despite the city''s refugees, wanderers, murderers, madmen, fanatics and thieves, the catalyst, as always, will be the Anchorwood–that dark grove of trees, that primeval remnant, that portal, when the moon is full, to strange and distant shores. 

Ilmar, some say, is the worst place in the world and the gateway to a thousand worse places. 

Ilmar, City of Long Shadows. City of Bad Decisions. City of Last Chances.

Winner of the BSFA Best Novel Award 2022.', 543, null, 2022, 552134, (select id from series where hardcover_id = 82686), '1') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('He Who Fights with Monsters 3: A LitRPG Adventure (He Who Fights with Monsters, Book 3)', 'Shirtaloon, Travis Deverell', '9798471621176', 'https://assets.hardcover.app/external_data/4078199/989d64f772f6198843e0d7f4829d315c363b0564.jpeg', 'Riding high on success, he and his team are looking to the future, preparing themselves for the challenges to come. Nothing, however, could prepare him for the lessons his enemies have to teach. When magic is involved, the stakes can be even greater than life and death.

While Jason’s personal enemies make plans, the greater foes plaguing his new home have been pushed to the brink. With one powerful card left to play, they are on a collision course with Jason and his team. With no one to help and more than their lives on the line, Jason and his companions must fight with more monsters than ever in the race to grow stronger. With an invincible enemy already anticipating them, they will learn that sometimes winning the battle is more important than surviving it.', null, null, 2021, 567926, (select id from series where hardcover_id = 12723), '3') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Deep Sky', 'Yume Kitasei', '1250875331', 'https://assets.hardcover.app/editions/31482845/2337780380156540.jpg', 'Yume Kitasei''s The Deep Sky is an enthralling sci fi thriller debut about a mission into deep space that begins with a lethal explosion that leaves the survivors questioning the loyalty of the crew. They left Earth to save humanity. They’ll have to save themselves first. It is the eve of Earth’s environmental collapse. A single ship carries humanity’s last hope: eighty elite graduates of a competitive program, who will give birth to a generation of children in deep space. But halfway to a distant but livable planet, a lethal bomb kills three of the crew and knocks The Phoenix off course. Asuka, the only surviving witness, is an immediate suspect. As the mystery unfolds on the ship, poignant flashbacks reveal how Asuka came to be picked for the mission. Despite struggling through training back on Earth, she was chosen to represent Japan, a country she only partly knows as a half-Japanese girl raised in America. But estranged from her mother back home, The Phoenix is all she has left. With the crew turning on each other, Asuka is determined to find the culprit before they all lose faith in the mission—or worse, the bomber strikes again.', 416, null, 2023, 584712, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Ashes and the Star-Cursed King', 'Carissa Broadbent', '8556512399', 'https://assets.hardcover.app/external_data/61152747/8a8c213aa8d3b370d33372f20c4e6993cb5e2d5b.jpeg', 'In the wake of the Kejari, everything Oraya once thought to be true has been destroyed. A prisoner in her own kingdom, grieving the only family she ever had, and reeling from a gutting betrayal, she no longer even knows the truth of her own blood. She’s left only with one certainty: she cannot trust anyone, least of all Raihn.

The House of Night, too, is surrounded by enemies. Raihn’s own nobles are none too eager to accept a Turned king, especially one who was once a slave. And the House of Blood digs their claws into the kingdom, threatening to tear it apart from the inside.

When Raihn offers Oraya a secret alliance, taking the deal is her only chance at reclaiming her kingdom–and gaining her vengeance against the lover who betrayed her. But to do so, she’ll need to harness a devastating ancient power, intertwined with her father’s greatest secrets.

But with enemies closing in on all sides, nothing is as it seems. As she unravels her past and faces her future, Oraya finds herself forced to choose between the bloody reality of seizing power – and the devastating love that could be her downfall.

Full of heartbreak, redemption, bloody intrigue, and heart-pounding action, The Ashes and the Star-Cursed King is the gutting second installment of the Crowns of Nyaxia series, and the conclusion of the Nightborn Duet – perfect for fans of From Blood and Ash and A Court of Thorns and Roses.', 624, null, 2023, 585716, (select id from series where hardcover_id = 29270), '2') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('He Who Fights with Monsters 2', 'Shirtaloon, Travis Deverell', '1774249162', 'https://assets.hardcover.app/external_data/1188552/0e8a568361309bb3a14d1b291b207cf2ff38dd35.jpeg', 'The path from retail middle management to interdimensional wizard adventurer wasn’t easy, but Jason Asano is settling into his new life.

Now, a contest draws young elites to the city of Greenstone, competing for a grand prize. Jason must gather a band of companions if he is to stand a chance against the best the world has to offer.

While the young adventurers are caught up in competition, the city leaders deal with revelations of betrayal as a vast and terrible enemy is revealed. Although Jason seems uninvolved, he has unknowingly crossed the enemy’s path before. Friends and foes made along the way will lead him to cross it again as inevitable conflict looms.', 562, null, 2021, 587448, (select id from series where hardcover_id = 12723), '2') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Throne of Fire', 'Rick Riordan', '0141967536', 'https://assets.hardcover.app/edition/30400879/a84168321c042584306493362fb85ffe742ba3fa.jpeg', 'Ever since the gods of Ancient Egypt were unleashed in the modern world, Carter Kane and his sister Sadie have been in trouble. As descendants of the House of Life, the Kanes have some powers at their command, but the devious gods haven’t given them much time to master their skills at Brooklyn House, which has become a training ground for young magicians.

And now their most threatening enemy yet – the chaos snake Apophis – is rising. If they don’t prevent him from breaking free in a few days’ time, the world will come to an end. In other words, it’s a typical week for the Kane family.

To have any chance of battling the Forces of Chaos, the Kanes must revive the sun god Ra. But that would be a feat more powerful than any magician has ever accomplished.

First they have to search the world for the three sections of the Book of Ra, then they have to learn how to chant its spells. Oh, and did we mention that no one knows where Ra is exactly?

Narrated in two different wisecracking voices, featuring a large cast of new and unforgettable characters, and with adventures spanning the globe, this second installment in the Kane Chronicles is nothing short of a thrill ride.', 452, null, 2011, 591748, (select id from series where hardcover_id = 5784), '2') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Chalice of the Gods', 'Rick Riordan', '1368102190', 'https://assets.hardcover.app/external_data/59775298/2559ae9ef80084c088ccdaf92c38ec7a4254fbbb.jpeg', 'After saving the world multiple times, Percy Jackson is hoping to have a normal senior year. Unfortunately, the gods aren’t quite done with him. Percy will have to fulfill three quests in order to get the necessary three letters of recommendation from Mount Olympus for college. The first quest is to help Zeus’s cup-bearer retrieve his goblet before it falls into the wrong hands. Can Percy, Grover, and Annabeth find it in time?', 269, null, 2022, 593589, (select id from series where hardcover_id = 5193), '6') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Three Musketeers', 'Alexandre Dumas', '2013971281', 'https://assets.hardcover.app/editions/31480168/8548264880766001.jpg', 'During the reign of France''s King Louis XIV, D''Artagnan and three musketeers unite to defend the honor of Anne of Austria against the plots of Cardinal Richelieu.', 624, null, 1844, 598289, (select id from series where hardcover_id = 95026), '1') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Bridge Kingdom', 'Danielle L. Jensen', '1799708934', 'https://assets.hardcover.app/edition/30425525/3678b496-c8da-4404-892c-3f388a187675.jpg', '"The first is that King Aren of the Bridge Kingdom is her enemy. And the second is that she’ll be the one to bring him to his knees.

The only route through a storm-ravaged world, the Bridge Kingdom of Ithicana enriches itself and deprives its rivals, including Lara’s homeland. So when she’s sent there as a bride under the guise of peace, Lara is prepared to do whatever it takes to fracture its impenetrable defenses—and the defenses of its king.

Yet as she infiltrates her new home and gains a deeper understanding of the war to possess the bridge, Lara begins to question whether she’s the hero or the villain. As her feelings for her husband transform from frosty hostility to fierce passion, Lara must choose which kingdom she’ll save . . . and which she’ll destroy."-- Provided by Amazon', 435, null, 2018, 617450, (select id from series where hardcover_id = 1331), '1') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Hurricane Wars', 'Thea Guanzon', '2080439944', 'https://assets.hardcover.app/external_data/60940764/3ba57a58ed3a174853939f6c9d06878e323a65ef.jpeg', 'All Talasyn has ever known is the Hurricane Wars. Growing up an orphan in a nation under siege by the ruthless Night Emperor, Talasyn has found her family among the soldiers who fight for freedom. But she is hiding a deadly secret: light magic courses through her veins, a blazing power believed to have been wiped out years ago that can cut through the Night Empire''s shadows.

Prince Alaric, the emperor''s only son and heir, has been forged into a weapon by his father. Tasked with obliterating any threats to the Night Empire''s rule with the strength of his armies and mighty Shadow magic, Alaric has never been bested. That is until he sees Talasyn burning brightly on the battlefield with the magic that killed his grandfather, turned his father into a monster, and ignited the Hurricane Wars. In a clash of light and dark, their powers merge and create a force the likes of which has never been seen.

Talasyn and Alaric both know this war can only end with them. But a greater threat is coming, and the strange new magic they can create together could be the only way to overcome it. Thrust into an uneasy alliance, they will confront the secrets at the heart of the war and find, in each other, a searing passion--one that could save their world...or destroy it.

An exquisite fantasy brimming with unforgettable characters, sizzling enemies-to-lovers romance, and richly drawn worlds, *The Hurricane Wars* marks the breathtaking debut of an extraordinary new writer.', 477, null, 2023, 617576, (select id from series where hardcover_id = 32513), '1') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Holly', 'Stephen King', '1668014947', 'https://assets.hardcover.app/external_data/59174872/6f0ce6a7711abca7c6decf84b739e5ebe22b56b6.jpeg', 'When Penny Dahl calls the Finders Keepers detective agency, hoping for help locating her missing daughter, Holly Gibney is reluctant to accept the case. Her partner, Pete, has Covid. Her (very complicated) mother has just passed away. And Holly is meant to be on leave. But something in Penny’s desperate voice makes it impossible to turn her down.

Meanwhile, mere blocks from where Bonnie Dahl disappeared live Professors Rodney and Emily Harris. They are the picture of bourgeois respectability: married octogenarians, devoted to each other, and semi-retired lifelong academics. But they are also harboring a shocking, unholy secret in the basement of their well-kept, book-lined home, one that may be related to Bonnie’s disappearance. And it will prove nearly impossible to discover what they are up to…for they are savvy, they are patient, and they are ruthless. Now Holly must summon all of her formidable talents to outthink and outmaneuver these unimaginably depraved and brilliantly disguised adversaries in this chilling and unforgettable masterwork from Stephen King.', 474, null, 2023, 633384, (select id from series where hardcover_id = 5531), '3') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Translation State', 'Ann Leckie', '154916483X', 'https://assets.hardcover.app/external_data/2002426/2c6dd8090ee80bf2b5a1ab698eaec4bc50640105.jpeg', 'Qven was created to be a Presger translator. The pride of their Clade, they always had a clear path before them: learn human ways, and eventually, make a match and serve as an intermediary between the dangerous alien Presger and the human worlds. The realization that they might want something else isn’t “optimal behavior”. It’s the type of behavior that results in elimination. 

But Qven rebels. And in doing so, their path collides with those of two others. Enae, a reluctant diplomat whose dead grandmaman has left hir an impossible task as an inheritance: hunting down a fugitive who has been missing for over 200 years. And Reet, an adopted mechanic who is increasingly desperate to learn about his genetic roots—or anything that might explain why he operates so differently from those around him.

As a Conclave of the various species approaches—and the long-standing treaty between the humans and the Presger is on the line—the decisions of all three will have ripple effects across the stars.  

Masterfully merging space adventure and mystery, and a poignant exploration about relationships and belonging, Translation State is a triumphant new standalone story set in the celebrated Imperial Radch universe.', 422, null, 2023, 643090, (select id from series where hardcover_id = 993), '5') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Ferryman', 'Justin Cronin', '0525619488', 'https://assets.hardcover.app/edition/30805987/816fe628-d252-47b0-9184-9e13b7a68fbe.jpg', 'The islands of Prospera lie in a vast ocean, in splendid isolation from the rest of humanity—or whatever remains of it.

Citizens of the main island enjoy privileged lives. They are attended to by support staff who live on a cramped neighboring island, where whispers of revolt are brewing—but for the Prosperans, life is perfection. And when the end of life approaches, they’re sent to a mysterious third island, where their bodies are refreshed, their memories are wiped away, and they return to start life anew.

Proctor Bennett is a ferryman, whose job it is to enforce the retirement process when necessary. He never questions his work, until the day he receives a cryptic message:

“The world is not the world.”

These simple words unlock something he has secretly suspected. They seep into strange dreams of the stars and the sea. They give him the unshakable feeling that someone is trying to tell him something important.

Something no one could possibly imagine, something that could change the fate of humanity itself.', 560, null, 2023, 659494, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('White Sand, Vol. 1', 'Brandon Sanderson, Rik Hoskin, Julius Gopez', '2490357034', 'https://assets.hardcover.app/edition/20176270/ed19427355c87181714fc669234c16d559775ac4.jpeg', 'A brand new saga of magic and adventure by #1 New York Times best-selling author Brandon Sanderson.

On the planet of Taldain, the legendary Sand Masters harness arcane powers to manipulate sand in spectacular ways. But when they are slaughtered in a sinister conspiracy, the weakest of their number, Kenton, believes himself to be the only survivor. With enemies closing in on all sides, Kenton forges an unlikely partnership with Khriss -- a mysterious Darksider who hides secrets of her own.

White Sand brings to life a crucial, unpublished part of Brandon Sanderson’s sprawling Cosmere universe. The story has been adapted by Rik Hoskin (Mercy Thompson), with art by Julius Gopez and colors by Ross Campbell. Employing powerful imagery and Sanderson’s celebrated approach to magical systems, White Sand is a spectacular new saga for lovers of fantasy and adventure.', 160, null, 2016, 676415, (select id from series where hardcover_id = 1052), '1') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Franny and Zooey', 'J. D. Salinger', '4102057048', 'https://assets.hardcover.app/external_data/37177452/ec7abbe3550f8ff9c6d1eb697c15cce769bd339b.jpeg', 'A novel in two halves, Franny and Zooey brilliantly captures the emotional strains and traumas of entering adulthood. It is a gleaming example of the wit, precision, and poignancy that have made J. D. Salinger one of America’s most beloved writers.', 201, null, 1957, 696714, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Spark of the Everflame', 'Penn Cole', '9897548114', 'https://assets.hardcover.app/editions/32191691/43dbd230-b0cd-4a5e-bc3b-487e79132050.jpg', 'In a mortal world colonized by the gods and ruled over by the Descended, their cruel magic-wielding offspring, Diem Bellator yearns to escape the insular life of her poor village. Her mother''s sudden disappearance-and the discovery of a dangerous secret about her past-offer Diem an unexpected opportunity to enter the dark world of Descended royalty and unlock the web of mysteries her mother left behind. With the dying King''s handsome, mysterious heir watching her every move, and a ruthless mortal alliance recruiting her to join the growing civil war, Diem will have to navigate the unwritten rules of love, power, and politics in order to save her family-and all of mortalkind. Spark of the Everflame is the first book in The Kindred''s Curse Saga, a four-book fantasy romance series. This slow burn, enemies-to-lovers epic is perfect for lovers of magic, dragons, angst, and banter and will appeal to fans of books like A Court of Thorns and Roses, From Blood and Ash, Gild, and The Serpent & the Wings of Night.', 438, null, 2021, 766436, (select id from series where hardcover_id = 53954), '1') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Orbital', 'Samantha Harvey', '1529934095', 'https://assets.hardcover.app/edition/30778685/6a4034584ba9f0e359119f7503f42ee66c270772.jpeg', 'A team of astronauts in the International Space Station collect meteorological data, conduct scientific experiments and test the limits of the human body. But mostly they observe. Together they watch their silent blue planet, circling it sixteen times, spinning past continents and cycling through seasons, taking in glaciers and deserts, the peaks of mountains and the swells of oceans. Endless shows of spectacular beauty witnessed in a single day.

Yet although separated from the world they cannot escape its constant pull. News reaches them of the death of a mother, and with it comes thoughts of returning home. They look on as a typhoon gathers over an island and people they love, in awe of its magnificence and fearful of its destruction.

The fragility of human life fills their conversations, their fears, their dreams. So far from earth, they have never felt more part - or protective - of it. They begin to ask, what is life without earth? What is earth without humanity?', 207, null, 2023, 775856, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Ficciones', 'Jorge Luis Borges', '0141183845', 'https://assets.hardcover.app/edition/27607251/07db65332612e3640198ac30d6e6c6e600aa0a5f.jpeg', 'A collection of his short stories in which Borges often uses the labyrinth as a literary device to expound his ideas on all aspects of human life and endeavor.


----------
Contains:
[Tlön, Uqbar, Orbis Tertius](https://openlibrary.org/works/OL444914W)', 192, null, 1944, 777120, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Prophet Song', 'Paul Lynch', '360812327X', 'https://assets.hardcover.app/external_data/59955446/e9404a7d6caf5ee22857d9b7b679251847f89d8c.jpeg', 'A fearless portrait of a society on the brink as a mother faces a terrible choice, from an internationally award-winning author

On a dark, wet evening in Dublin, scientist and mother-of-four Eilish Stack answers her front door to find the GNSB on her step. Two officers from Ireland’s newly formed secret police are here to interrogate her husband, a trade unionist.

Ireland is falling apart. The country is in the grip of a government turning towards tyranny and Eilish can only watch helplessly as the world she knew disappears. When first her husband and then her eldest son vanish, Eilish finds herself caught within the nightmare logic of a collapsing society.

How far will she go to save her family? And what – or who – is she willing to leave behind?

Exhilarating, terrifying and propulsive, Prophet Song is a work of breathtaking originality, offering a devastating vision of a country at war and a deeply human portrait of a mother’s fight to hold her family together.', 279, null, 2023, 809083, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('What You Are Looking for Is in the Library', 'Michiko Aoyama, Alison Watts, Rohan Eason', '5001957540', 'https://assets.hardcover.app/edition/30817995/5c4c53fa6c2dc3a08c93a409e8d85ee93d74867e.jpeg', 'So asks Tokyo’s most enigmatic librarian. For Sayuri Komachi is able to sense exactly what each visitor to her library is searching for and provide just the book recommendation to help them find it.

A restless retail assistant looks to gain new skills, a mother tries to overcome demotion at work after maternity leave, a conscientious accountant yearns to open an antique store, a recently retired salaryman searches for newfound purpose.

In Komachi’s unique book recommendations they will find just what they need to achieve their dreams. What You Are Looking For Is in the Library is about the magic of libraries and the discovery of connection. This inspirational tale shows how, by listening to our hearts, seizing opportunity and reaching out, we too can fulfill our lifelong dreams. Which book will you recommend?', 193, null, 2020, 809366, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('A Fate Inked in Blood', 'Danielle L. Jensen', '0593599845', 'https://assets.hardcover.app/edition/30899374/1010a0af70b3aacef2fe4bf776b75453eaeaec26.jpeg', 'Bound in an unwanted marriage, Freya spends her days gutting fish but dreams of becoming a warrior. And of putting an axe in her boorish husband’s back.

Freya’s dreams abruptly become reality when her husband betrays her to the region’s jarl, landing her in a fight to the death against his son, Bjorn. To survive, Freya is forced to reveal her deepest secret: She possesses a drop of a goddess’s blood, which makes her a shield maiden with magic capable of repelling any attack. And it’s been foretold that such magic will unite the fractured nation of Skaland beneath the one who controls the shield maiden’s fate.

Believing he’s destined to rule Skaland as king, the fanatical jarl binds Freya with a blood oath and orders Bjorn to protect her from their enemies. Desperate to prove her strength, Freya must train to fight and learn to control her magic, all while facing perilous tests set by the gods. The greatest test of all, however, may be resisting her forbidden attraction to Bjorn. If Freya succumbs to her lust for the charming and fierce warrior, she risks not only her own destiny but the fate of all the people she has sworn to protect.

', 431, null, 2024, 880580, (select id from series where hardcover_id = 53110), '1') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('When Among Crows', 'Veronica Roth', '1250351170', 'https://assets.hardcover.app/edition/30968283/9f696147cd05a43a517760ed50cfab04a3392569.jpeg', '"We bear the sword, and we bear the pain of the sword."

Pain is Dymitr’s calling. His family is one in a long line of hunters who sacrifice their souls to slay monsters. Now he’s tasked with a deadly mission: find the legendary witch Baba Jaga. To reach her, Dymitr must ally with the ones he’s sworn to kill.

Pain is Ala’s inheritance. A fear-eating zmora with little left to lose, Ala awaits death from the curse she carries. When Dymitr offers her a cure in exchange for her help, she has no choice but to agree.

Together they must fight against time and the wrath of the Chicago underworld. But Dymitr’s secrets—and his true motives—may be the thing that actually destroys them.', 166, null, 2024, 943215, (select id from series where hardcover_id = 156628), '1') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Butcher & Blackbird', 'Brynne Weaver', '1638931747', 'https://assets.hardcover.app/editions/30984895/8439175321212713.jpeg', 'When a chance encounter sparks an unlikely bond between rival murderers Sloane and Rowan, they find something elusive—the friendship of two like-minded, pitch-black souls who just happen to enjoy killing other serial killers.

From small-town West Virginia to upscale California, and from downtown Boston to rural Texas, the two hunters collide in an annual game of blood and suffering, one that pits them against the most dangerous monsters in the country.

But as their friendship develops into something more, the restless ghosts left in their wake are only a few steps behind, ready to claim more than just their newfound love.

Can Rowan and Sloane dig themselves out of a game of graves?
Or have they finally met their match?', 355, null, 2023, 959904, (select id from series where hardcover_id = 57397), '1') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Y: The Last Man Vol, 1 Unmanned', 'Brian K. Vaughan, Pia Guerra, José Marzán Jr.', '1840237082', 'https://assets.hardcover.app/external_data/60134922/a53eda4312c3b10255f664de679dc9c9f6e68cf3.jpeg', '"Funny and scary…an utterly believable critique of society. A+"—THE WASHINGTON POST"The best graphic novel I''ve ever read."—STEPHEN KING"This year''s best movie is a comic book."—ALL THINGS CONSIDERED, NATIONAL PUBLIC RADIO"A seriously funny, nuanced fable...Grade A."—ENTERTAINMENT WEEKLY Y: THE LAST MAN, winner of three Eisner Awards and one of the most critically acclaimed, best-selling comic books series of the last decade, is that rare example of a page-turner that is at once humorous, socially relevant and endlessly surprising. Written by Brian K. Vaughan (Lost, PRIDE OF BAGHDAD, EX MACHINA) and with art by Pia Guerra, this is the saga of Yorick Brown—the only human survivor of a planet-wide plague that instantly kills every mammal possessing a Y chromosome. Accompanied by a mysterious government agent, a brilliant young geneticist and his pet monkey, Ampersand, Yorick travels the world in search of his lost love and the answer to why he''s the last man on earth. Collecting issues #1-5.', 126, null, 2002, 977047, (select id from series where hardcover_id = 4625), '1') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Nuclear War: A Scenario', 'Annie Jacobsen', '6263967757', 'https://assets.hardcover.app/edition/31011783/dc14efa86a7cedb9695fc3936173394f0bb440a8.jpeg', '“In Nuclear War: A Scenario, Annie Jacobsen gives us a vivid picture of what could happen if our nuclear guardians fail…Terrifying.”—Wall Street Journal

There is only one scenario other than an asteroid strike that could end the world as we know it in a matter of hours: nuclear war. And one of the triggers for that war would be a nuclear missile inbound toward the United States.
 
Every generation, a journalist has looked deep into the heart of the nuclear military establishment: the technologies, the safeguards, the plans, and the risks. These investigations are vital to how we understand the world we really live in—where one nuclear missile will beget one in return, and where the choreography of the world’s end requires massive decisions made on seconds’ notice with information that is only as good as the intelligence we have.
 
Pulitzer Prize finalist Annie Jacobsen’s Nuclear War: A Scenario explores this ticking-clock scenario, based on dozens of exclusive new interviews with military and civilian experts who have built the weapons, have been privy to the response plans, and have been responsible for those decisions should they have needed to be made. Nuclear War: A Scenario examines the handful of minutes after a nuclear missile launch. It is essential reading, and unlike any other book in its depth and urgency.', 301, null, 2024, 986963, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Amulet of Samarkand', 'Jonathan Stroud', '1417628650', 'https://assets.hardcover.app/editions/30422669/1985024194403469.jpg', 'The first volume in the brilliant, best-selling Bartimaeus Trilogy; now with a brand new cover look and extra material!', 496, null, 2003, 995278, (select id from series where hardcover_id = 5791), '1') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Naturals', 'Jennifer Lynn Barnes', '6585348443', 'https://assets.hardcover.app/editions/31066835/4275430027698144.jpeg', '"Piecing together the tiniest details, she can tell you who you are and what you want. But, it''s not a skill that she''s ever taken seriously. That is, until the FBI come knocking: they''ve begun a classified program that uses exceptional teenagers to crack infamous cold cases, and they need Cassie.

What Cassie doesn''t realize is that there''s more at risk than a few unsolved homicides-especially when she''s sent to live with a group of teens whose gifts are as unusual as her own. Soon, it becomes clear that no one in the Naturals program is what they seem. And when a new killer strikes, danger looms close. Caught in a lethal game of cat and mouse with a killer, the Naturals are going to have to use all of their gifts just to survive."-- Provided by Amazon', 308, null, 2013, 1042511, (select id from series where hardcover_id = 3336), '1') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Annie Bot', 'Sierra Greer', '0063312697', 'https://assets.hardcover.app/edition/31085675/e0a423f180c23b89f9c0ca169d0102f0bafb679b.jpeg', 'For fans of Never Let Me Go and My Dark Vanessa, a powerful, provocative novel about the relationship between a female robot and her human owner, exploring questions of intimacy, power, autonomy, and control.

Annie Bot was created to be the perfect girlfriend for her human owner Doug. Designed to satisfy his emotional and physical needs, she has dinner ready for him every night, wears the pert outfits he orders for her, and adjusts her libido to suit his moods. True, she’s not the greatest at keeping Doug’s place spotless, but she’s trying to please him. She’s trying hard.

She’s learning, too.

Doug says he loves that Annie’s AI makes her seem more like a real woman, so Annie explores human traits such as curiosity, secrecy, and longing. But becoming more human also means becoming less perfect, and as Annie’s relationship with Doug grows more intricate and difficult, she starts to wonder: Does Doug really desire what he says he wants? And in such an impossible paradox, what does Annie owe herself?', 231, null, 2024, 1061553, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Someone You Can Build a Nest In', 'John Wiswell', '1529431336', 'https://assets.hardcover.app/editions/31094420/5994614363120543.jpg', 'Discover this creepy, charming monster-slaying fantasy romance—from the perspective of the monster—by Nebula Award-winning debut author John Wiswell

Shesheshen has made a mistake fatal to all monsters: she’s fallen in love.
 
Shesheshen is a shapeshifter, who happily resides as an amorphous lump at the bottom of a ruined manor. When her rest is interrupted by hunters intent on murdering her, she constructs a body from the remains of past meals: a metal chain for a backbone, borrowed bones for limbs, and a bear trap as an extra mouth.  
 
However, the hunters chase Shesheshen out of her home and off a cliff. Badly hurt, she’s found and nursed back to health by Homily, a warm-hearted human, who has mistaken Shesheshen as a fellow human. Homily is kind and nurturing and would make an excellent co-parent: an ideal place to lay Shesheshen’s eggs so their young could devour Homily from the inside out. But as they grow close, she realizes humans don’t think about love that way.
 
Shesheshen hates keeping her identity secret from Homily, but just as she’s about to confess, Homily reveals why she’s in the area: she’s hunting a shapeshifting monster that supposedly cursed her family. Has Shesheshen seen it anywhere?
 
Eating her girlfriend isn’t an option. Shesheshen didn’t curse anyone, but to give herself and Homily a chance at happiness, she has to figure out why Homily’s twisted family thinks she did. As the hunt for the monster becomes increasingly deadly, Shesheshen must unearth the truth quickly, or soon both of their lives will be at risk.

And the bigger challenge remains: surviving her toxic in-laws long enough to learn to build a life with, rather than in, the love of her life.', 320, null, 2024, 1070342, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Alien Clay', 'Adrian Tchaikovsky', '0316578975', 'https://assets.hardcover.app/edition/31628911/156a8336661ae3ea0c4cb1c91f3c8433a8940a12.jpeg', 'The planet of Kiln is where the tyrannical Mandate keeps its prison colony, and for inmates, the journey there is always a one-way trip. One such prisoner is Professor Arton Daghdev, xeno-ecologist and political dissident. Soon after arrival, he discovers that Kiln has a secret. Humanity is not the first intelligent life to set foot there.

In the midst of a ravenous, chaotic ecosystem are the ruins of a civilization, but who were the vanished builders and where did they go? If he can survive both the harsh rule of the camp commandant and the alien horrors of the world around him, then Arton has a chance at making a discovery that might just transform not only Kiln, but distant Earth as well.', 390, null, 2024, 1070572, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('How to Become the Dark Lord and Die Trying', 'Django Wexler', '1405561912', 'https://assets.hardcover.app/editions/31110227/4650252272820743.jpg', 'Groundhog Day meets Deadpool in Django Wexler’s raunchy, hilarious, blood-splattered fantasy tale about a young woman who, tired of defending humanity from the Dark Lord, decides to become the Dark Lord herself.

"Takes the old saying ''If you can''t beat ''em, join ''em,'' to the next level. A sarcastic, action-packed, intrigue-filled (mis)adventure. One of the funniest books I''ve read in a long time."--Matt Dinniman, author of Dungeon Crawler Carl

Davi has done this all before. She’s tried to be the hero and take down the all-powerful Dark Lord. A hundred times she’s rallied humanity and made the final charge. But the time loop always gets her in the end. Sometimes she’s killed quickly. Sometimes it takes a while. But she’s been defeated every time.

This time? She’s done being the hero and done being stuck in this endless time loop. If the Dark Lord always wins, then maybe that’s who she needs to be. It’s Davi’s turn to play on the winning side.
A humorous western isekai featuring the reincarnation of an antihero female lead.', 384, null, 2023, 1086192, (select id from series where hardcover_id = 85397), '1') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Knight and the Moth', 'Rachel Gillig', '0316597694', 'https://assets.hardcover.app/editions/31144704/0d158594-26c2-4b33-8258-45b36fdf58ea.jpg', 'Sybil Delling has spent nine years dreaming of having no dreams at all. Like the other foundling girls who traded a decade of service for a home in the great cathedral, Sybil is a Diviner. In her dreams she receives visions from six unearthly figures known as Omens. From them, she can predict terrible things before they occur, and lords and common folk alike travel across the kingdom of Traum’s windswept moors to learn their futures by her dreams.

Just as she and her sister Diviners near the end of their service, a mysterious knight arrives at the cathedral. Rude, heretical, and devilishly handsome, the knight Rodrick has no respect for Sybil’s visions. But when Sybil’s fellow Diviners begin to vanish one by one, she has no choice but to seek his help in finding them. For the world outside the cathedral’s cloister is wrought with peril. Only the gods have the answers she is seeking, and as much as she’d rather avoid Rodrick’s dark eyes and sharp tongue, only a heretic can defeat a god.', 400, null, 2025, 1120724, (select id from series where hardcover_id = 131398), '1') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Rocannon''s World', 'Ursula K. Le Guin, Stefan Rudnicki', '9753420927', 'https://assets.hardcover.app/edition/13845656/2b996e254763bfc0d456223249e78730ce84fb7b.jpeg', 'Earth-scientist Rocannon has been leading an ethnological survey on a remote world populated by three native races: the cavern-dwelling Gdemiar, the elvish Fiia, and the warrior clan, Liuar. But when the technologically primitive planet is suddenly invaded by a fleet of ships from the stars, rebels against the League of All Worlds, Rocannon is the only survey member left alive. Marooned among alien peoples, he leads the battle to free this newly discovered world and finds that legends grow around him as he fights.', null, null, 1966, 1134855, (select id from series where hardcover_id = 1123), '1') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Witchcraft for Wayward Girls', 'Grady Hendrix', '0593548981', 'https://assets.hardcover.app/external_data/2901973/69e4e08b452f6e981b78c03c702a201318734017.jpeg', 'There’s power in a book…
 
They call them wayward girls. Loose girls. Girls who grew up too fast. And they’re sent to Wellwood House in St. Augustine, Florida, where unwed mothers are hidden by their families to have their babies in secret, to give them up for adoption, and most important of all, to forget any of it ever happened.
 
Fifteen-year-old Fern arrives at the home in the sweltering summer of 1970, pregnant, terrified and alone. Under the watchful eye of the stern Miss Wellwood, she meets a dozen other girls in the same predicament. There’s Rose, a hippie who insists she’s going to find a way to keep her baby and escape to a commune. And Zinnia, a budding musician who plans to marry her baby’s father. And Holly, a wisp of a girl, barely fourteen, mute and pregnant by no-one-knows-who.
 
Everything the girls eat, every moment of their waking day, and everything they’re allowed to talk about is strictly controlled by adults who claim they know what’s best for them. Then Fern meets a librarian who gives her an occult book about witchcraft, and power is in the hands of the girls for the first time in their lives. But power can destroy as easily as it creates, and it’s never given freely. There’s always a price to be paid…and it’s usually paid in blood.

In Witchcraft for Wayward Girls, the author of How to Sell a Haunted House and The Final Girl Support Group delivers another searing, completely original novel and further cements his status as a “horror master” (NPR).

', 400, null, 2024, 1168736, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Lights Out', 'Navessa Allen', '1638932247', 'https://assets.hardcover.app/edition/32499986/6b1cd8bf65d5bd0305509740ba385726ba5e6202.jpeg', 'Trauma nurse Aly Cappellucci doesn’t need any more kinks. She likes the one she’s landed on just fine. To her, nothing could top the masked men she follows online. Unless one of those men was shirtless, heavily tattooed, and waiting for her in her bedroom. 

She dreams about being hunted by one in particular, of him chasing her down and doing deliciously dark things to her willing body. She never could have guessed that by sending one drunken text, those dreams would become her new reality.

I want things most people don’t, craving darkness and depravity instead of light and love.

Josh Hammond has spent his life avoiding the limelight, but his online persona is another story. At night, he posts masked thirst traps for his millions of fans to drool over, but one follower has caught his eye: Aly. After reading a comment begging him to break into her house wearing a mask, he decides to take her up on her offer.

Together, Aly and Josh live out their darkest fantasies, unaware that Aly has captured the attention of someone else. Someone with far more sinister intentions than a little light stalking. 

As Josh turns from predator to protector and the stakes heighten, he must ask himself how far he’s willing to go for the woman he’s obsessed with.', 416, null, 2024, 1180115, (select id from series where hardcover_id = 140317), '1') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Water Moon', 'Samantha Sotto', '0593946340', 'https://assets.hardcover.app/editions/31246918/8500226755792306.jpg', 'A woman inherits a pawnshop where you can sell your regrets, and then embarks on a magical journey when a charming young physicist wanders into the shop, in this dreamlike and enchanting fantasy novel.

Most will see a cozy ramen restaurant. And only the chosen ones—those who are lost—will find a place to pawn their life choices and deepest regrets.

Hana Ishikawa wakes on her first morning as the pawnshop’s new owner to find it ransacked, the shop’s most precious acquisition stolen, and her father missing. And then into the shop stumbles a charming stranger, quite unlike its other customers, for he offers help instead of seeking it.

Together, they must journey through a mystical world to find Hana’s father and the stolen choice—by way of rain puddles, rides on paper cranes, the bridge between midnight and morning, and a night market in the clouds.

But as they get closer to the truth, Hana must reveal a secret of her own—and risk making a choice that she will never be able to take back.', 384, null, 2025, 1194010, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Girl with the Dragon Tattoo', 'Stieg Larsson', '8901116154', 'https://assets.hardcover.app/books/379085/9274740-L.jpg', 'It''s about the disappearance 40 years ago of Harriet Vanger, a young scion of one of the wealthiest families in Sweden...and about her octogenarian uncle, determined to know the truth about what he believes was her murder.

It''s about Mikael Blomkvist, a crusading journalist recently at the wrong end of a libel case, hired to get to the bottom of Harriet''s disappearance...and about Lisbeth Salander, a 24-year-old, pierced and tattooed genius hacker possessed of the hard-earned wisdom of someone twice her age, who assists Blomkvist with the investigation.

This unlikely team discovers a vein of nearly unfathomable iniquity running through the Vanger family, astonishing corruption in the highest echelons of Swedish industrialism - and an unexpected connection between themselves.', 465, null, 2005, 1218611, (select id from series where hardcover_id = 2115), '1') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Raven Scholar', 'Antonia Hodgson', '139975209X', 'https://assets.hardcover.app/editions/31275866/c3fd6c03-4468-42c1-9076-09143e176e43.jpg', 'Let us fly now to the empire of Orrun, where after twenty-four years of peace, the reign of Bersun the Brusque has come to an end. In the dizzying heat of midsummer, seven exceptional warriors, thinkers, strategists compete to replace him. 

When one of them is murdered, it falls to Neema Kraa, the emperor’s brilliant, idiosyncratic High Scholar, to find the killer and fight for the throne. Neema believes she is alone. But we are here to help; all she has to do is let us in.

If she succeeds, we will win an empire. If she fails, death awaits her. But we won’t let that happen.

We are the Raven, and we are magnificent.', 654, null, 2025, 1250824, (select id from series where hardcover_id = 168997), '1') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Phantasma', 'Kaylie Smith', '1836182163', 'https://assets.hardcover.app/edition/31373154/042d9dd0-9904-40f3-9902-69aa3d828acd.jpg', 'When Ophelia’s sister disappears, there is only one way to save her. Ophelia must enter Phantasma, a deadly contest inside a haunted mansion, and claim its prize—a single wish. Phantasma is a maze of twisting corridors and lavish ballrooms, of demons and temptations. Ophelia will face nine challenges, each more dangerous than the last. There can only be one winner, and the other contestants will stop at nothing to eliminate their rivals.

Every day the house creates new monsters. But just as Ophelia’s fears threaten to overwhelm her, a mysterious stranger offers her a bargain. Charming, arrogant and infuriatingly attractive, Blackwell claims he can guide her through the lethal trials ahead. All he asks in return is ten years of her life.

Ophelia knows she shouldn’t trust him. Blackwell doesn’t seem dangerous, but appearances can be deceptive. Worse still, she feels a dark and irresistible attraction drawing them closer and closer. Her life is on the line.

But in Phantasma, the only thing deadlier than losing the game is losing your heart…

A Court of Thorns and Roses meets Caraval in this seductive fantasy adventure. With steamy romance, a sexy morally gray love interest, OCD rep and jaw-dropping twists, Phantasma is perfect for fans of Rebecca Yarros, Nisha J. Tuli and Carissa Broadbent.
', 497, null, 2024, 1348180, (select id from series where hardcover_id = 141881), '1') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Broken Angels', 'Richard K. Morgan', '291437075X', 'https://assets.hardcover.app/edition/2219140/5f748240-cfda-4b3f-a8c0-3eee5875614f.jpg', 'Welcome back to the brash, brutal new world of the twenty-fifth century: where global politics isn''t just for planet Earth anymore; and where death is just a break in the action, thanks to the techno-miracle that can preserve human consciousness and download it into one new body after another. 

Cynical, quick-on-the-trigger Takeshi Kovacs, the ex-U.N. envoy turned private eye, has changed careers, and bodies, once more . . . trading sleuthing for soldiering as a warrior-for-hire, and helping a far-flung planet''s government put down a bloody revolution.

But when it comes to taking sides, the only one Kovacs is ever really on is his own. So when a rogue pilot and a sleazy corporate fat cat offer him a lucrative role in a treacherous treasure hunt, he''s only too happy to go AWOL with a band of resurrected soldiers of fortune. All that stands between them and the ancient alien spacecraft they mean to salvage are a massacred city bathed in deadly radiation, unleashed nanotechnolgy with a million ways to kill, and whatever surprises the highly advanced Martian race may have in store. But armed with his genetically engineered instincts, and his trusty twin Kalashnikovs, Takeshi is ready to take on anything--and let the devil take whoever''s left behind.From the Trade Paperback edition.', 386, null, 2005, 1377102, (select id from series where hardcover_id = 5569), '2') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Shroud', 'Adrian Tchaikovsky', '1035013827', 'https://assets.hardcover.app/editions/31454859/9811557152460392.jpg', 'An utterly gripping story of alien encounter and survival from Adrian Tchaikovsky, author of the Arthur C. Clarke Award-winning Children of Time.

They looked into the darkness and the darkness looked back . . .

New planets are fair game to asset strippers and interplanetary opportunists – and a commercial mission to a distant star system discovers a moon that is pitch black, but alive with radio activity. Its high-gravity, high-pressure, zero-oxygen environment is anathema to human life, but ripe for exploitation. They named it Shroud.

Under no circumstances should a human end up on Shroud’s inhospitable surface. Except a catastrophic accident sees Juna Ceelander and Mai Ste Etienne doing just that. Forced to stage an emergency landing, in a small, barely adequate vehicle, they are unable to contact their ship and are running out of time. What follows is a gruelling journey across land, sea and air. During this time, Juna and Mai begin to understand Shroud’s dominant species. It also begins to understand them . . .

If they escape Shroud, they’ll face a crew only interested in profiteering from this extraordinary world. They’ll somehow have to explain the impossible and translate the incredible. That is, if they make it back at all.', 560, null, 2025, 1420497, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('When the Moon Hits Your Eye', 'John Scalzi, Wil Wheaton', '0765389096', 'https://assets.hardcover.app/editions/31483358/2553761381650439.jpg', 'Now humanity has to deal with it.

For some it’s an opportunity. For others it’s a moment to question their faith: In God, in science, in everything. Still others try to keep the world running in the face of absurdity and uncertainty. And then there are the billions looking to the sky and wondering how a thing that was always just there is now... something absolutely impossible.

Astronauts and billionaires, comedians and bank executives, professors and presidents, teenagers and terminal patients at the end of their lives -- over the length of an entire lunar cycle, each get their moment in the moonlight. To panic, to plan, to wonder and to pray, to laugh and to grieve. All in a kaleidoscopic novel that goes all the places you’d expect, and then to so many places you wouldn’t.

It’s a wild moonage daydream. Ride this rocket.', 336, null, 2025, 1443471, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Atmosphere: A Love Story', 'Taylor Jenkins Reid', '1804941433', 'https://assets.hardcover.app/edition/31625541/d80d0f61-d2a6-488f-a93c-a5dfc5a32faa.jpg', 'Joan Goodwin has been obsessed with the stars for as long as she can remember. Thoughtful and reserved, Joan is content with her life as a professor of physics and astronomy at Rice University and as aunt to her precocious niece, Frances. That is, until she comes across an advertisement seeking the first women scientists to join NASA''s Space Shuttle program. Suddenly, Joan burns to be one of the few people to go to space.

Selected from a pool of thousands of applicants in the summer of 1980, Joan begins training at Houston''s Johnson Space Center, alongside an exceptional group of fellow candidates: Top Gun pilots Hank Redmond and John Griffin, who are kind and easy going even when the stakes are highest; mission specialist Lydia Danes, who has worked too hard to play nice; warm-hearted Donna Fitzgerald, who is navigating her own secrets; and Vanessa Ford, the magnetic and mysterious aeronautical engineer, who can fix any engine and fly any plane.

As the new astronauts become unlikely friends and prepare for their first flights, Joan finds a passion and a love she never imagined. In this new light, Joan begins to question everything she thinks she knows about her place in the observable universe.

Then, in December of 1984, on mission STS-LR9, everything changes in an instant.

Fast paced, thrilling, and emotional, Atmosphere is Taylor Jenkins Reid at her best: transporting readers to iconic times and places, with complex protagonists, telling a passionate and soaring story about the transformative power of love, this time among the stars.', 352, null, 2025, 1561653, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The River Has Roots', 'Amal El-Mohtar', '1250341086', 'https://assets.hardcover.app/edition/31670038/a3a96b7d5cf7c00ba5d3f799287ccf4a199a0d1b.jpeg', 'In the small town of Thistleford, on the edge of Faerie, dwells the mysterious Hawthorn family.

There, they tend and harvest the enchanted willows and honour an ancient compact to sing to them in thanks for their magic. None more devotedly than the family’s latest daughters, Esther and Ysabel, who cherish each other as much as they cherish the ancient trees.

But when Esther rejects a forceful suitor in favor of a lover from the land of Faerie, not only the sisters’ bond but also their lives will be at risk…', 105, null, 2025, 1562200, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Automatic Noodle', 'Annalee Newitz', '1250357470', 'https://assets.hardcover.app/edition/31670039/ced78671-3ed9-4ab6-b191-4bd8d3f66356.jpg', 'A cozy near-future novella about a crew of leftover robots opening their very own noodle shop, from acclaimed sci-fi author Annalee Newitz.

You don’t have to eat food to know the way to a city’s heart is through its stomach. So when a group of deactivated robots come back online in an abandoned ghost kitchen, they decide to make their own way doing what they know: making food—the tastiest hand-pulled noodles around—for the humans of San Francisco, who are recovering from a devastating war.

But when their robot-run business starts causing a stir, a targeted wave of one-star reviews threatens to boil over into a crisis. To keep their doors open, they’ll have to call on their customers, their community, and each other—and find a way to survive and thrive in a world that wasn’t built for them.', 176, null, 2025, 1598053, (select id from series where hardcover_id = 298935), '1') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Cursed Bunny', 'Bora Chung, Anton Hur', '8556521991', 'https://assets.hardcover.app/edition/32280260/af6362aa-c707-45c7-b772-e438eb196af1.jpg', 'A wildly original debut from a rising star of Korean literature—surreal, chilling fables that take on the patriarchy, capitalism, and the reign of big tech with absurdist humor and a (sometimes literal) bite. Pre-order YOUR UTOPIA, the new book written by Bora Chung and translated by Anton Hur, coming February 2024! 
 
From an author never before published in the United States, Cursed Bunny is unique and imaginative, blending horror, sci-fi, fairy tales, and speculative fiction into stories that defy categorization. By turns thought-provoking and stomach-turning, here monsters take the shapes of furry woodland creatures and danger lurks in unexpected corners of everyday apartment buildings. But in this unforgettable collection, translated by the acclaimed Anton Hur, Chung’s absurd, haunting universe could be our own.
 
“The Head” follows a woman haunted by her own bodily waste. “The Embodiment” takes us into a dystopian gynecology office where a pregnant woman is told that she must find a father for her baby or face horrific consequences. Another story follows a young monster, forced into underground fight rings without knowing his own power. The titular fable centers on a cursed lamp in the shape of a rabbit, fit for a child’s bedroom but for its sinister capabilities.
 
No two stories are alike, and readers will be torn whether to race through them or savor Chung’s wit and frenetic energy on every page. Cursed Bunny is a book that screams to be read late into the night and passed on to the nearest set of hands the very next day. ', 192, null, 2017, 1617146, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Secret of Secrets', 'Dan Brown, Fernanda Abreu', '8817174459', 'https://assets.hardcover.app/edition/31830477/31aa397f1175d024ab3bbb8e3abf57d951d76676.jpeg', 'Robert Langdon, esteemed professor of symbology, travels to Prague to attend a groundbreaking lecture by Katherine Solomon—a prominent noetic scientist with whom he has recently begun a relationship. Katherine is on the verge of publishing an explosive book that contains startling discoveries about the nature of human consciousness and threatens to disrupt centuries of established belief. 

But a brutal murder catapults the trip into chaos, and Katherine suddenly disappears along with her manuscript. Langdon finds himself targeted by a powerful organization and hunted by a chilling assailant sprung from Prague’s most ancient mythology. 

As the plot expands into London and New York, Langdon desperately searches for Katherine... and for answers. In a thrilling race through the dual worlds of futuristic science and mystical lore, he uncovers a shocking truth about a secret project that will forever change the way we think about the human mind.', 688, null, 2025, 1729702, (select id from series where hardcover_id = 1084), '6') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Origin', 'Dan Brown', '0525563695', 'https://assets.hardcover.app/editions/24692174/8509515428193068.jpeg', 'Robert Langdon, Harvard professor of symbology, arrives at the ultramodern Guggenheim Museum Bilbao to attend the unveiling of a discovery that “will change the face of science forever.” The evening’s host is Edmond Kirsch, a forty-year-old billionaire and futurist, and one of Langdon’s first students.

But the meticulously orchestrated evening suddenly erupts into chaos, and Kirsch’s precious discovery teeters on the brink of being lost forever. Facing an imminent threat, Langdon is forced to flee. With him is Ambra Vidal, the elegant museum director who worked with Kirsch. They travel to Barcelona on a perilous quest to locate a cryptic password that will unlock Kirsch’s secret.

Navigating the dark corridors of hidden history and extreme re­ligion, Langdon and Vidal must evade an enemy whose all-knowing power seems to emanate from Spain’s Royal Palace. They uncover clues that ultimately bring them face-to-face with Kirsch’s shocking discovery . . . and the breathtaking truth that has long eluded us.', 461, null, 2013, 1938541, (select id from series where hardcover_id = 1084), '5') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Yesteryear', 'Caro Claire Burke', '0008742766', 'https://assets.hardcover.app/edition/32720645/91d910bf-e696-4366-aa09-14f0a6a6cea9.jpg', 'Natalie lives a traditional lifestyle. Her charming farmhouse is rustic, her husband a handsome cowboy, her six children each more delightful than the last. So what if there are nannies and producers behind the scenes, her kitchen hiding industrial-grade fridges and ovens, her husband the heir to a political dynasty? What Natalie’s followers—all 8 million of them—don’t know won’t hurt them. And The Angry Women? The privileged, Ivy League, coastal elite haters who call her an antifeminist iconoclast? They’re sick with jealousy. Because Natalie isn’t simply living the good life, she’s living the ideal—and just so happens to be building an empire from it.

Until one morning she wakes up in a life that isn’t hers. Her home, her husband, her children—they’re all familiar, but something’s off. Her kitchen is warmed by a sputtering fire rather than electricity, her children are dirty and strange, and her soft-handed husband is suddenly a competent farmer. Just yesterday Natalie was curating photos of homemade jam for her Instagram, and now she’s expected to haul firewood and handwash clothes until her fingers bleed. Has she become the unwitting star of a ruthless reality show? Could it really be time travel? Is she being tested by God? By Satan? When Natalie suffers a brutal injury in the woods, she realizes two things: This is not her beautiful life, and she must escape by any means possible.

A gripping, electrifying novel that is as darkly funny as it is frightening, Yesteryear is a gimlet-eyed look at tradition, fame, faith, and the grand performance of womanhood.', 391, null, 2026, 1941363, null, null) on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('The Faith of Beasts', 'James S. A. Corey', '0316525677', 'https://assets.hardcover.app/edition/32249749/821d8322-9f2e-4edd-80d5-922456a38224.jpg', 'The monstrous Carryx empire was built by subjugation and war. Thousands of species are bound to their Sovran’s command in an endless, blood-soaked test: be useful in the eternal conflict or be slaughtered.

Dafyd Alkhor, highest among their human captives, is feared and despised by the very people he champions. Ruthless in carving out his niche in the eternal war machine of the empire, he will reshape human nature itself as a tool for their alien masters’ use. But Dafyd’s loyalty is not what it seems.

The Swarm, an agent of the Carryx’s deathless enemy, has been smuggled into the Carryx world-palace along with the human slaves. Its mission: discover a way to bring down the empire’s eternal reign. But the longer it lives among and within humanity, the more it forgets that it is a weapon.

As the human captives spread through the battlefronts of empire, the awesome power of the Carryx becomes clear. And with it, a desperate plan for their destruction.

But empires hide secrets, and even the deathless enemy may not be what it appears…', 448, null, 2026, 1989375, (select id from series where hardcover_id = 52808), '2') on conflict (hardcover_id) do nothing;
insert into books (title, author, isbn, cover_url, synopsis, page_count, audiobook_duration_minutes, publication_year, hardcover_id, series_id, position_in_series) values ('Bridge to Terabithia', 'Katherine Paterson', '1581180535', 'https://assets.hardcover.app/edition/32524360/6a8954f3-40d7-4777-9545-4ca36d0444be.jpg', 'The life of a ten-year-old boy in rural Virginia expands when he becomes friends with a newcomer who subsequently meets an untimely death trying to reach their hideaway, Terabithia, during a storm.', 128, null, 1977, 2280862, null, null) on conflict (hardcover_id) do nothing;
